window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0187", [{"word":"discounted","ipa_uk":"/dɪsˈkaʊntɪd/","ipa_us":"/dɪsˈkaʊntɪd/","definition_zh":"打过折扣的；按现值折算的；被认为不可信的","definition_en":"reduced in price, restated at present value, or treated as less important than it first appears","core_image":"货架价签上原来的数字被划掉，旁边写着更小的数字，收银台边还压着一张写着日期的票据","scene":"换季清仓时，店员把冬装价签上的旧数字划掉，在旁边写上更小的数字。The store discounted every winter coat before the new stock arrived.","sceneCN":"这里这个词指「商品在标价基础上被减价出售」（第 1 个义项：零售标价被下调）；句意为新货到店之前，店家把每件冬衣都打了折。图中可辨识物件：价签、被划掉的旧数字、新写的数字、成排冬衣。","pos":[{"tag":"adj.","zh":"打过折扣的；按现值折算的；被贬低价值的"},{"tag":"v.","zh":"折扣一词的过去式与过去分词：打折；贴现；不采信"}],"collocations":[{"phrase":"discounted price","zh":"折扣价；减价后的价格"},{"phrase":"heavily discounted","zh":"大幅打折的"},{"phrase":"discounted cash flow","zh":"折现现金流"},{"phrase":"discounted rate","zh":"折扣费率；优惠费率"},{"phrase":"discounted fare","zh":"折扣票价"},{"phrase":"discounted value","zh":"折现值"}],"forms":[{"label":"原级（形容词）","form":"discounted"},{"label":"比较级","form":"more discounted"},{"label":"最高级","form":"most discounted"},{"label":"动词原形","form":"discount"},{"label":"动词三单","form":"discounts"},{"label":"动词过去式","form":"discounted"},{"label":"动词现在分词","form":"discounting"},{"label":"名词","form":"discount"}],"derivatives":[{"word":"discount","pos":"n./v.","zh":"折扣；打折；贴现"},{"word":"discounter","pos":"n.","zh":"廉价商店；贴现商"},{"word":"discountable","pos":"adj.","zh":"可贴现的；可打折的"},{"word":"discounting","pos":"n.","zh":"贴现；折现"},{"word":"undiscounted","pos":"adj.","zh":"未打折的；未折现的"}],"senses":[{"no":"01","title":"Sold below the marked price","titleCN":"以低于标价的价钱出售","definition":"sold for less than the price printed on the ticket","definitionCN":"以低于票面标价的价格卖出","example":"Every winter coat in the window is discounted by a third.","exampleCN":"橱窗里的每件冬衣都按标价减去了三分之一。","why":"The prefix means away and the root means to count, so this sense is literally an amount counted off the ticket.","whyCN":"前缀表示「去掉」，词根表示「计数」，所以这个义项字面上就是从标价上扣掉一笔。"},{"no":"02","title":"Cleared to make room for new stock","titleCN":"为给新货腾位置而清仓减价","definition":"reduced sharply so that old stock leaves the shelves before a new season","definitionCN":"大幅降价，使旧货在新一季到来之前离架","example":"The unsold summer stock was discounted the week the autumn lines arrived.","exampleCN":"秋季货品到店的那一周，没卖完的夏装被清仓减价。","why":"A seasonal cut is the same subtraction, only applied under a deadline.","whyCN":"季节性减价仍是同一种扣除，只是多了一个期限。"},{"no":"03","title":"Bought below face value","titleCN":"按低于面额的价钱买进票据","definition":"bought for less than the sum the bill promises to pay at maturity","definitionCN":"以低于票据到期应付金额的价格买进","example":"The bank discounted the note two months before it fell due.","exampleCN":"银行在票据到期前两个月按低于面额的价钱把它买下。","why":"In early banking the deduction was the charge for waiting, and the bill itself was said to be discounted.","whyCN":"在早期银行业务中，扣下的部分是对等待时间的收费，票据本身也就被称作已贴现。"},{"no":"04","title":"Restated at present value","titleCN":"折算为现值","definition":"a future sum recalculated as what it is worth today","definitionCN":"把未来的一笔钱重新计算成今天的价值","example":"The appraisal discounted the expected rent over twenty years.","exampleCN":"评估把二十年的预期租金折算成了现值。","why":"Money arriving later is worth less now, so the calculation counts part of it away.","whyCN":"往后才到手的钱在今天值不了那么多，所以计算时要把其中一部分扣掉。"},{"no":"05","title":"Adjusted for risk and the cost of capital","titleCN":"按风险与资金成本调整","definition":"future returns reduced by a rate that reflects risk and the cost of money","definitionCN":"用反映风险与资金成本的比率把未来收益折低","example":"Analysts discounted the project's cash flows at nine percent a year.","exampleCN":"分析师按每年百分之九的比率对项目的现金流做了折现。","why":"A higher rate counts more of the future away, which is how risk enters the figure.","whyCN":"比率越高，扣掉的未来部分越多，风险就是这样进入数字的。"},{"no":"06","title":"Valued below its stated worth","titleCN":"被估得低于宣称的价值","definition":"an asset or skill judged to be worth less than its advertised value","definitionCN":"某项资产或本领被判断为不值它所宣称的价钱","example":"The market discounted the company's patents as hard to defend.","exampleCN":"市场认为这家公司的专利难以维权，因而把它们的价值估低。","why":"The same downward counting is applied to a valuation rather than to a price tag.","whyCN":"同样的向下扣减被用在估值上，而不是用在价签上。"},{"no":"07","title":"Refused as unreliable","titleCN":"因不可信而不予采信","definition":"a report or claim treated as not worth believing","definitionCN":"某份报告或说法被当作不值得相信","example":"The editor discounted the rumor after checking with two sources.","exampleCN":"编辑向两个消息来源核实后，不再采信那则传闻。","why":"A claim is weighed, found light, and counted out of consideration.","whyCN":"一个说法被掂量之后显得轻，于是被从考虑范围里划掉。"},{"no":"08","title":"Offered at a lower rate to a group","titleCN":"对特定人群按较低费率提供","definition":"a special reduced price fixed in advance for students, members or seniors","definitionCN":"事先为学生、会员或老年人定好的优惠价格","example":"Members travel at a discounted rate on weekdays.","exampleCN":"会员在工作日按优惠费率出行。","why":"Here the reduction is attached to a class of buyers rather than to a season or a bill.","whyCN":"这里的减价挂在一类购买者身上，而不挂在季节或票据上。"}],"etymology":{"intro":{"en":"Discount comes through Old French from Latin computare, to reckon, with a prefix meaning away; the financial sense of buying a bill below its face value is early modern, and the adjective grew out of that verb.","cn":"discount 经古法语来自拉丁语 computare「计算」，并带一个表示「去掉」的前缀；按低于面额买进票据的金融义出现于近代早期，形容词则由这个动词的分词发展而来。"},"items":[{"era":"LATIN COMPUTARE","en":"Computare meant to reckon together or calculate, joining com- together with putare to reckon.","cn":"computare 意为「合起来算、计算」，由表示「共同」的 com- 与表示「估算」的 putare 构成。"},{"era":"LATIN PUTARE","en":"Putare meant to reckon or consider. Its deeper origin is not established; a link to the separate verb meaning to prune is a hypothesis, so the detail is source uncertain.","cn":"putare 意为「估算、考虑」。其更深来源未得到证明；把它与另一个表示「修剪」的动词相联系只是假说，因此这一点标为来源不确定。"},{"era":"OLD FRENCH DESCOMPTE","en":"Des- apart plus conter to count gave descompte, a counting off, hence a deduction from a sum.","cn":"表示「分开」的 des- 加 conter「计数」构成 descompte，本义是「扣着一笔数」，因此指从总额中减去的一笔。"},{"era":"ENGLISH DISCOUNT","en":"English borrowed the word in the seventeenth century for a deduction from a price and for buying a bill below its face value.","cn":"英语在十七世纪借入这个词，既指从价格中减去的一笔，也指按低于面额买进票据。"},{"era":"FINANCE EXTENSION","en":"Twentieth-century finance extended the verb to future cash flows brought back to present value.","cn":"二十世纪的金融业务把这个动词扩展到把未来现金流折回现值的算法。"},{"era":"ADJECTIVAL FORM","en":"The past participle became an adjective, covering both marked-down goods and claims that are not believed.","cn":"过去分词转为形容词，既修饰减价商品，也修饰不被采信的说法。"}]},"similar":{"note":{"en":"The first group holds forms built on the same counting root that are often mixed up; the second holds words with a similar downward meaning but a different scope.","cn":"第一组是同出「计数」词根、常被混用的形式；第二组是意思同样向下、但适用对象不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"discount","ipa":"/ˈdɪskaʊnt/","tag":"base form","definition":"The verb and noun behind the adjective: to take an amount off a price, or the amount taken off.","definitionCN":"形容词背后的动词与名词：从价格中减去一笔，或指被减去的那一笔。"},{"word":"count","ipa":"/kaʊnt/","tag":"same root, no deduction","definition":"To add up numbers; it shares the Latin reckoning root but carries no idea of taking anything off.","definitionCN":"把数目加起来；它与拉丁语「计算」同根，却不含扣除的意思。"},{"word":"account","ipa":"/əˈkaʊnt/","tag":"same root, different prefix","definition":"A record of money received and paid; it shares the counting root but takes a different prefix.","definitionCN":"记录收入与支出的账目；它同出「计数」词根，但前缀不同。"},{"word":"miscount","ipa":"/ˌmɪsˈkaʊnt/","tag":"same root, wrong total","definition":"To count wrongly; it keeps the root but reverses the accuracy rather than the direction.","definitionCN":"数错；它保留同一词根，改变的是准确与否，而不是扣除的方向。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reduced","ipa":"/rɪˈdjuːst/","tag":"smaller in general","definition":"Made smaller in size, amount or degree; it says nothing about a price tag or a calculation.","definitionCN":"在大小、数量或程度上变小；它不涉及价签，也不涉及计算。"},{"word":"marked down","ipa":"/ˌmɑːkt ˈdaʊn/","tag":"retail term","definition":"The shop term for lowering a ticket price; it covers the retail senses but not the financial ones.","definitionCN":"商店里降低标价的说法；它覆盖零售义，却不覆盖金融义。"},{"word":"undervalued","ipa":"/ˌʌndəˈvæljuːd/","tag":"about worth","definition":"Valued below true worth, usually of an asset or a currency; it matches the valuation sense only.","definitionCN":"被估得低于真实价值，通常用于资产或货币；它只对应估值那一义。"},{"word":"dismissed","ipa":"/dɪˈsmɪst/","tag":"about claims","definition":"Refused to consider an idea or a person; it matches the sense of a report not being believed.","definitionCN":"拒绝考虑某个想法或某人；它对应报告不被采信的那一义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"dis- away plus count to reckon: an amount reckoned away from the ticket.","cn":"表示「去掉」的前缀加「计数」：从价签上算掉的一笔。"},{"en":"The family runs discount, discounter, discountable, discounting and undiscounted.","cn":"同族词包括 discount、discounter、discountable、discounting 与 undiscounted。"},{"en":"Fixed phrases mark the retail and finance sides: discounted price, discounted cash flow, discounted rate.","cn":"固定搭配标出零售与金融两面：折扣价、折现现金流、折扣费率。"},{"en":"Count, account, recount and miscount all go back to the same Latin verb of reckoning.","cn":"count、account、recount 与 miscount 都回到同一个拉丁语「计算」动词。"},{"en":"A bank that buys a bill before maturity is doing the same subtraction as a shop with a red ticket.","cn":"银行在到期前买进票据，和商店挂出红色价签做的是同一种减法。"}],"abstract":[{"en":"Picture a banknote dated in the future that gets thinner the longer you hold it at arm's length.","cn":"想象一张写着未来日期的钞票，你把它举得越远，它就越薄。"},{"en":"Picture the printed figure stepping back and leaving a smaller shadow where it stood.","cn":"想象印好的数字向后退了一步，在原地留下一个更小的影子。"},{"en":"Picture a report laid on the corner of a desk, which lightens in your hand as you stop trusting it.","cn":"想象一份报告被放到桌角，当你不再相信它时，它在你手里就变轻了。"}]},"examples":[{"en":"The bakery sells yesterday's bread at a discounted price after six in the evening.","cn":"这家面包店在傍晚六点以后按折扣价卖出前一天的面包。"},{"en":"The fund discounted the expected returns before comparing the two plans.","cn":"基金会在比较两个方案之前，先把预期收益折算成现值。"},{"en":"The committee discounted the warning because no instrument had recorded it.","cn":"委员会没有采信那条警告，因为没有任何仪器记录到它。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「去掉（dis）一笔账（count）」——从标价或面额上扣掉的数 → 打折的、折算的","word":"discounted"},"root":"拉丁语 computare「合计、计算」由表示「共同」的前缀与 putare「估算」构成；经古法语 descompte「扣除一笔」进入英语，再由分词转为形容词。putare 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: an amount is counted off a stated figure, and that gesture is then applied to a ticket, a season, a bill, a future sum, a risky return, a valuation, a rumor and finally a group rate.","cn":"八个义项沿同一个动作展开：从一个写定的数字上扣掉一笔，这个动作再依次用于价签、季节、票据、未来金额、有风险的收益、估值、传闻，最后用于一类人的费率。"},"semanticMap":{"core":{"en":"CORE IMAGE: a printed figure with a smaller figure written beside it, and a second date stamped on the page.","cn":"核心意象：印好的数字旁边被写上更小的数字，纸页上还盖着另一个日期。"},"chain":["TAKE SOMETHING OFF","LOWER THE TAG","BUY BELOW FACE","PULL THE FUTURE BACK","WEIGH THE RISK","COUNT A CLAIM OUT"],"branches":[{"senses":"01 · 02","en":"TICKETS AND SEASONS: both are retail cuts, one permanent and one timed to clear stock.","cn":"价签与季节：两者都是零售减价，一个长期，一个为了清货而定时。"},{"senses":"03","en":"FACE VALUE: a bill bought for less than it will pay is the banking form of the same subtraction.","cn":"面额：票据以低于其应付金额的价钱买进，是同一减法在银行业务里的形态。"},{"senses":"04 · 05","en":"FUTURE MONEY: the same figure is pulled back to today, first with time alone and then with risk.","cn":"未来的钱：同一个数额被拉回今天，先只算时间，再把风险算进去。"},{"senses":"06","en":"VALUATION: an asset is judged lighter than its label claims.","cn":"估值：资产被判断得比它标签上宣称的更轻。"},{"senses":"07 · 08","en":"SOCIAL CUTS: one claim loses credibility and one class of buyers gains a lower rate.","cn":"社会性的扣减：一个说法失去可信度，一类购买者得到更低费率。"}]},"affixes":{"intro":{"en":"The word is a Latin verb of reckoning with a French prefix meaning away, so its parts read as counting something off.","cn":"这个词是一个带「去掉」前缀的拉丁语「计算」动词，因此各部分可以读作「把某笔数扣掉」。"},"latinIntro":{"en":"Latin computare supplies count, compute and account, while the prefix dis- turns the reckoning into a deduction.","cn":"拉丁语 computare 提供 count、compute 与 account 的词根，前缀 dis- 则把「计算」转为「扣除」。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, apart, away)","meaning":"away; apart","meaningCN":"去掉；分开","example":"The prefix marks the amount as taken off.","exampleCN":"这个前缀标明数额是被扣掉的。"},{"word":"com-","structure":"com- (Latin prefix, together)","meaning":"together; wholly","meaningCN":"共同；完全","example":"The prefix binds the reckoning into one sum.","exampleCN":"这个前缀把计算收束成一个总额。"},{"word":"putare","structure":"putare (Latin verb, first conjugation)","meaning":"to reckon; to consider","meaningCN":"估算；认为","example":"The root supplies the act of reckoning itself.","exampleCN":"这个词根提供「估算」这一动作本身。"},{"word":"computare","structure":"com- + putare","meaning":"to reckon together; to calculate","meaningCN":"合计；计算","example":"Merchants computare their gains before the market closes.","exampleCN":"商人在市场收市前合计自己的收益。"},{"word":"count","structure":"Old French conter, from Latin computare","meaning":"to add up; to enumerate","meaningCN":"点数；计数","example":"The clerk counts the till at closing time.","exampleCN":"店员在打烊时清点钱箱。"},{"word":"discount","structure":"dis- + count","meaning":"to take an amount off","meaningCN":"减去一笔；打折","example":"The shop discounts slow-moving lines each spring.","exampleCN":"这家店每年春天都给滞销货减价。"},{"word":"discounter","structure":"discount + -er (person or firm that does)","meaning":"a firm that sells cheaply","meaningCN":"廉价商店；贴现商","example":"A discounter undercut the high street shops.","exampleCN":"一家廉价商店把商业街上的店铺压低了价。"},{"word":"discountable","structure":"discount + -able (fit to be)","meaning":"able to be discounted","meaningCN":"可贴现的；可打折的","example":"Only bills with a sound signature are discountable.","exampleCN":"只有签章可靠的票据才可贴现。"},{"word":"discounting","structure":"discount + -ing (the act or process)","meaning":"the practice of discounting","meaningCN":"贴现；折现","example":"Discounting turns a future payment into today's money.","exampleCN":"折现把未来的付款变成今天的钱。"},{"word":"undiscounted","structure":"un- + discounted (not subjected to)","meaning":"not reduced in price","meaningCN":"未打折的","example":"The last two shelves remain undiscounted.","exampleCN":"最后两排货架上的商品仍未打折。"}],"latinEntries":[{"word":"computare","structure":"computare, -avi, -atum (first conjugation; Latin)","meaning":"to reckon together, calculate","meaningCN":"合计；计算"},{"word":"putare","structure":"putare, -avi, -atum (first conjugation; Latin)","meaning":"to reckon, consider","meaningCN":"估算；认为"},{"word":"dis-","structure":"dis- (Latin prefix)","meaning":"apart, away","meaningCN":"分开；去掉"}]}},{"word":"wholesale price","ipa_uk":"/ˌhəʊlˈseɪl praɪs/","ipa_us":"/ˌhoʊlˈseɪl praɪs/","definition_zh":"批发价；整批成交时按单位计算的进货价格","definition_en":"the unit price at which goods are sold in large lots to shops, distributors or other businesses","core_image":"仓库门口的月台上堆着一整托盘货物，单据上的单价远低于街角小店货架上的标价","scene":"仓库门口，装卸工把整托盘货物推上卡车，单据上的单价按整批数量计算。The wholesale price of coffee beans fell after a record harvest.","sceneCN":"这里这个词组指「整批货物卖给零售商时的单位价格」（第 1 个义项：大批量成交的进货价）；句意为咖啡豆丰收之后，批发价下跌。图中可辨识物件：仓库月台、整托盘货物、卡车、批发单据。","pos":[{"tag":"n.","zh":"批发价（可数；指某一商品在批发环节的单位价格）"}],"collocations":[{"phrase":"wholesale price index","zh":"批发价格指数"},{"phrase":"at wholesale price","zh":"按批发价"},{"phrase":"the wholesale price of","zh":"某物的批发价"},{"phrase":"rising wholesale prices","zh":"上涨的批发价"},{"phrase":"wholesale electricity price","zh":"电力批发价"},{"phrase":"wholesale price level","zh":"批发价格水平"}],"forms":[{"label":"复数","form":"wholesale prices"},{"label":"相关名词（批发）","form":"wholesale"},{"label":"相关名词（批发商）","form":"wholesaler"},{"label":"相关名词（批发业务）","form":"wholesaling"},{"label":"对照说法（零售价）","form":"retail price"},{"label":"限定用法","form":"wholesale-price（作定语时连写）"}],"derivatives":[{"word":"wholesale","pos":"n./adj./adv.","zh":"批发；批发的；以批发方式"},{"word":"wholesaler","pos":"n.","zh":"批发商"},{"word":"wholesaling","pos":"n.","zh":"批发业务"},{"word":"pricing","pos":"n.","zh":"定价；计价"},{"word":"priced","pos":"adj.","zh":"标价的；定价的"}],"senses":[{"no":"01","title":"The unit price a shop pays for bulk stock","titleCN":"商店整批进货时支付的单位价格","definition":"the price per unit that a retailer pays when buying a large lot from a supplier","definitionCN":"零售商从供货方大批买进时按单位支付的价格","example":"Retailers buy flour at a wholesale price far below the shelf tag.","exampleCN":"零售商买面粉的批发价远低于货架标价。","why":"Wholesale names the sale of a whole lot, so the price attached to it is the price of buying in bulk.","whyCN":"「批发」指的是整批卖出，所以附在它上面的价格就是整批买进的价格。"},{"no":"02","title":"A quotation on a produce or commodity market","titleCN":"农产品或大宗商品市场上的报价","definition":"the price set at an auction or exchange where goods change hands in bulk","definitionCN":"在拍卖场或交易所整批成交时定下的价格","example":"On the auction floor the wholesale price is fixed before any shop opens.","exampleCN":"在拍卖场上，批发价在任何店铺开门之前就已定下。","why":"The trading floor is the original place where whole lots meet a single quoted figure.","whyCN":"交易场正是整批货物与一个报价相遇的原始场所。"},{"no":"03","title":"The figure before retail costs are added","titleCN":"尚未加上零售成本的那个数字","definition":"the amount to which rent, wages and profit are later added to reach the shelf price","definitionCN":"之后再加上租金、人工与利润才成为货架价的那个金额","example":"Rent and wages are added to the wholesale price to set the retail tag.","exampleCN":"租金与人工被加到批发价上，才定出货架上的标价。","why":"In the chain from maker to buyer, wholesale is the stage just before the shop adds its own costs.","whyCN":"在从制造者到买家的链条上，批发是店铺加上自身成本之前的那一站。"},{"no":"04","title":"A component of the producer price index","titleCN":"生产者价格指数中的一个组成价格","definition":"the price series that statistics offices track to measure inflation at the bulk stage","definitionCN":"统计部门用来衡量批发环节通胀的价格序列","example":"The wholesale price index rose for the third month in a row.","exampleCN":"批发价格指数连续第三个月上涨。","why":"Once the figure is collected monthly, it stops being one deal and becomes an indicator.","whyCN":"当这个数字按月被收集，它就不再是一笔交易，而成为一个指标。"},{"no":"05","title":"Bulk price in energy markets","titleCN":"能源市场的大宗价格","definition":"the price at which electricity or gas is sold to distributors rather than to households","definitionCN":"电力或燃气卖给分销商而非家庭时的价格","example":"A mild winter pushed the wholesale price of gas down.","exampleCN":"暖冬把燃气的批发价压低了。","why":"Energy is sold in lots too, so the same word covers a market measured in megawatts rather than crates.","whyCN":"能源同样按整批卖出，所以同一个词也覆盖以兆瓦而非箱数计量的市场。"},{"no":"06","title":"The transfer price inside one company","titleCN":"同一家公司内部的调拨价","definition":"the internal price one arm of a business charges another for goods","definitionCN":"企业内部一个部门向另一个部门供货时收取的价格","example":"The factory books its output at a wholesale price set by the parent company.","exampleCN":"工厂按母公司设定的批发价把产出记账。","why":"A firm that both makes and sells treats its own factory as a supplier, so the bulk price turns inward.","whyCN":"既制造又销售的公司把自家工厂当作供货方，于是整批价转向了内部。"},{"no":"07","title":"The floor under a retail price","titleCN":"零售价下方的底线","definition":"the minimum a shop must recover before its own costs can be covered","definitionCN":"店铺在覆盖自身成本之前必须收回的最低金额","example":"No retailer can sell below the wholesale price for long.","exampleCN":"没有哪家零售商能长期以低于批发价的价格出售。","why":"Because the shop must recover what it paid, the bulk figure acts as a floor.","whyCN":"因为店铺必须收回它付出的钱，这个整批价就成了底线。"},{"no":"08","title":"A one-off price for a single large order","titleCN":"单笔大订单议定的价格","definition":"a figure negotiated for one particular bulk order rather than a standard list","definitionCN":"为某一笔特定的大宗订单谈定的价格，而非标准价目表上的价格","example":"For one large order the mill agreed on a special wholesale price.","exampleCN":"为了一笔大订单，工厂同意了一个特别的批发价。","why":"The lot is still sold whole, but the quantity is large enough to move the figure away from the list.","whyCN":"货仍然整批卖出，只是数量大到足以让价格离开价目表。"}],"etymology":{"intro":{"en":"Wholesale is a native English compound of whole and sale, first naming the selling of an entire lot; price comes from Latin pretium. The two were joined as trade statistics grew.","cn":"wholesale 是英语本族复合词，由「整体」与「售卖」两部分组成，最初指整批卖出；price 来自拉丁语 pretium。两者在贸易统计发展之后组合成固定说法。"},"items":[{"era":"OLD ENGLISH HAL","en":"Hal meant whole, entire or healthy, and became the modern adjective whole.","cn":"hal 意为「完整的、完好的、健康的」，后来成为现代英语中的 whole。"},{"era":"OLD ENGLISH SALA","en":"Sala meant a selling or a sale, from the verb sellan, to sell.","cn":"sala 意为「售卖、一笔买卖」，来自动词 sellan「卖」。"},{"era":"MIDDLE ENGLISH WHOLE SALE","en":"The phrase whole sale named the selling of an entire lot at one time, as opposed to selling it off in pieces.","cn":"whole sale 这个短语指一次把整批货卖掉，与拆成小份分卖相对。"},{"era":"ENGLISH WHOLESALE","en":"By the sixteenth century wholesale was a fixed term for trade in bulk, and the person who did it was a wholesaler.","cn":"到十六世纪，wholesale 已成为指整批贸易的固定词，做这种生意的人称作 wholesaler。"},{"era":"TRADE STATISTICS","en":"Wholesale price became a standard label when offices began recording bulk prices monthly, and the wholesale price index followed.","cn":"当统计部门开始按月记录整批价格时，wholesale price 成了标准说法，批发价格指数随后出现。"}]},"similar":{"note":{"en":"The first group holds the retail counterpart and the parts of the same compound; the second holds other names for a bulk or list figure.","cn":"第一组是零售端的对应说法以及同一复合词的组成部分；第二组是大宗价与目录价的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"retail price","ipa":"/ˌriːteɪl ˈpraɪs/","tag":"the shelf figure","definition":"The price a customer pays in a shop, after the shop has added its own costs.","definitionCN":"顾客在商店支付的价格，此时店铺已加上自身成本。"},{"word":"wholesale","ipa":"/ˈhəʊlseɪl/","tag":"the trade, not the figure","definition":"The activity or adjective of selling in bulk; it names the stage rather than the amount.","definitionCN":"整批卖出的活动或形容词；它指环节，而不指具体金额。"},{"word":"wholesaler","ipa":"/ˈhəʊlseɪlə/","tag":"the person or firm","definition":"The business that buys from makers and sells lots to shops; it is a trader, not a price.","definitionCN":"从制造商买进、再整批卖给店铺的企业；它指交易者，不指价格。"},{"word":"sale","ipa":"/seɪl/","tag":"one half of the compound","definition":"A single act of selling, or a period of reduced prices; it supplies the second half of wholesale.","definitionCN":"一次售卖行为，或一段降价促销期；它构成「批发」一词的后半。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cost price","ipa":"/ˈkɒst praɪs/","tag":"what the seller paid","definition":"The amount a seller paid to acquire an item; a wholesale price is the buyer's cost price, seen from the other side.","definitionCN":"卖方取得商品时付出的金额；批发价从另一方看就是买方的成本价。"},{"word":"trade price","ipa":"/ˈtreɪd praɪs/","tag":"price for the trade","definition":"The discounted figure offered to businesses in the same trade; often close to wholesale but tied to membership.","definitionCN":"提供给同行业商户的优惠价；常接近批发价，但以行业身份为条件。"},{"word":"bulk price","ipa":"/bʌlk praɪs/","tag":"quantity-based","definition":"A price lowered because of the size of one order; it stresses quantity rather than the trade stage.","definitionCN":"因单笔订单数量大而降低的价格；它强调数量，而非贸易环节。"},{"word":"list price","ipa":"/lɪst praɪs/","tag":"published figure","definition":"The published price before any discount; a wholesale price may itself be quoted as a list for the trade.","definitionCN":"折扣之前公布的价格；批发价本身也可能作为行业目录价公布。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Whole plus sale: the entire lot is sold at one time, so the unit figure drops.","cn":"「整体」加「售卖」：整批一次卖出，所以单位价格下降。"},{"en":"The family runs wholesale, wholesaler, wholesaling and wholesale price.","cn":"同族说法包括批发、批发商、批发业务与批发价。"},{"en":"Fixed phrases mark the statistics and the market: wholesale price index, at wholesale price, wholesale electricity price.","cn":"固定搭配标出统计与市场两面：批发价格指数、按批发价、电力批发价。"},{"en":"Set it against retail price: one is the figure at the loading bay, the other the figure on the shelf.","cn":"把它与零售价对照：一个是装货月台上的数字，一个是货架上的数字。"},{"en":"On an invoice the unit price is multiplied by the number of cases, which is why the lot matters.","cn":"发票上的单价要乘以箱数，这正是「整批」要紧的原因。"}],"abstract":[{"en":"Picture a reservoir gate opened once for the whole downstream instead of a tap turned on in every kitchen.","cn":"想象水库闸门一次向下游放水，而不是每家厨房各开一个水龙头。"},{"en":"Picture buying the whole tree instead of picking single fruit from it.","cn":"想象买下整棵树，而不是从树上单个摘果子。"},{"en":"Picture a price walking from the warehouse to the shelf and growing heavier at every door.","cn":"想象一个价格从仓库走向货架，每过一道门就变重一些。"}]},"examples":[{"en":"The cooperative sells its grain at a wholesale price negotiated before planting.","cn":"合作社按播种前谈定的批发价卖出粮食。"},{"en":"Rising wholesale prices usually reach the shelf within a few months.","cn":"上涨的批发价通常会在几个月内传到货架上。"},{"en":"The hospital buys dressings at a wholesale price and resells them at cost.","cn":"医院按批发价买进敷料，再按成本价转给病人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「整（whole）批卖（sale）」——整批成交时按单位算的价，就是批发价","word":"wholesale price"},"root":"英语本族复合词：whole 来自古英语 hal「完整」，sale 来自古英语 sala「售卖」，合起来指整批卖出；price 来自拉丁语 pretium「价值、价格」。","sensesIntro":{"en":"Eight senses follow one figure as it moves: the unit price of a bulk lot, its quotation on a market, the level before shop costs, an index component, an energy price, an internal transfer, a retail floor and a single large order.","cn":"八个义项跟着同一个数字移动：整批货的单位价、市场上的报价、加上店铺成本之前的水平、指数成分、能源价格、内部调拨、零售底线，以及单笔大订单。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pallet of goods on a loading bay with one unit figure written on the docket.","cn":"核心意象：月台上的一整托盘货物，单据上只写着一个单位价格。"},"chain":["BUY THE WHOLE LOT","ONE UNIT FIGURE","BEFORE THE SHOP ADDS","MEASURE THE MARKET","BULK ENERGY","THE FLOOR BELOW RETAIL"],"branches":[{"senses":"01 · 08","en":"ONE LOT, TWO WAYS: a routine supply price and a figure moved by the size of a single order.","cn":"一种整批，两种情形：常规供货价，以及因单笔订单之大而变动的价格。"},{"senses":"02 · 03","en":"BEFORE THE SHOP: the auction quotation and the pre-retail level are the same figure seen at two moments.","cn":"店铺之前：拍卖报价与零售前水平是同一数字在两个时刻的样子。"},{"senses":"04","en":"MEASURED MONTHLY: one deal becomes a statistic once offices record it.","cn":"按月计量：一旦统计部门记录，一笔交易就变成一项统计。"},{"senses":"05","en":"ENERGY IN LOTS: gas and power are sold whole too, so the word crosses into another market.","cn":"整批的能源：燃气与电力同样整批卖出，于是这个词跨入另一个市场。"},{"senses":"06 · 07","en":"INSIDE THE TRADE: the same figure becomes an internal charge and a floor no shop can pass.","cn":"行业之内：同一个数字变成内部收费，也成为店铺不能越过的底线。"}]},"affixes":{"intro":{"en":"The phrase is a compound of two native English words plus a Latin noun of value, so it is read as whole lot, selling, and price.","cn":"这个短语由两个英语本族词加一个拉丁语表示价值的名词构成，可以读作「整批」「售卖」与「价格」。"},"latinIntro":{"en":"Price goes back to Latin pretium, value or worth, which also gives precious and appraise through related forms.","cn":"price 可回溯到拉丁语 pretium「价值、价钱」，相关形式还衍生出 precious 与 appraise。"},"items":[{"word":"whole","structure":"Old English hal (entire, healthy)","meaning":"entire; complete","meaningCN":"整个的；完整的","example":"The lot is sold whole, not in single units.","exampleCN":"这批货整批卖出，不拆成单件。"},{"word":"sale","structure":"Old English sala (a selling), from sellan","meaning":"the act of selling","meaningCN":"售卖；出售","example":"The sale of the whole harvest takes one morning.","exampleCN":"整季收成的售卖一个上午就完成。"},{"word":"price","structure":"Latin pretium (value, worth), through Old French pris","meaning":"the amount asked for something","meaningCN":"价格；价钱","example":"The price is quoted per kilogram.","exampleCN":"价格按每公斤报出。"},{"word":"wholesale","structure":"whole + sale","meaning":"selling in bulk","meaningCN":"批发；整批卖出","example":"The cooperative sells wholesale to city shops.","exampleCN":"合作社向城里店铺整批供货。"},{"word":"wholesaler","structure":"wholesale + -er (one who does)","meaning":"a bulk trader","meaningCN":"批发商","example":"A wholesaler takes the pallet before it reaches a shop.","exampleCN":"批发商在货物进入店铺之前接手整托盘。"},{"word":"wholesaling","structure":"wholesale + -ing (the business of)","meaning":"the trade of selling in bulk","meaningCN":"批发业务","example":"Wholesaling employs fewer people than retailing.","exampleCN":"批发业务用的人比零售业务少。"},{"word":"retail","structure":"Old French retaillier (to cut up)","meaning":"selling in small quantities","meaningCN":"零售；拆成小份卖出","example":"Retail takes over after the pallet is broken up.","exampleCN":"整托盘被拆开之后，零售接手。"},{"word":"bulk","structure":"Old Norse bulki (a heap, a cargo)","meaning":"a large quantity","meaningCN":"大批；大宗","example":"The bulk of the order goes to one chain.","exampleCN":"订单的大部分货物流向一家连锁店。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one that performs an action","meaningCN":"做某事的人或物","example":"The suffix turns the trade into the trader.","exampleCN":"这个后缀把「行业」变成「从业者」。"}],"latinEntries":[{"word":"pretium","structure":"pretium, -i (n., second declension; Latin)","meaning":"price, value, worth","meaningCN":"价格；价值"}]}},{"word":"retail price","ipa_uk":"/ˌriːteɪl ˈpraɪs/","ipa_us":"/ˌriːteɪl ˈpraɪs/","definition_zh":"零售价；商店卖给最终消费者时单件商品的价格","definition_en":"the price a customer pays for a single item in a shop, after the seller has added its own costs","core_image":"街角小店的货架上每件商品都贴着一张面向顾客的价签，价签下方就是收银台","scene":"街角小店的货架前，顾客拿起一件商品，翻过来看背面的价签。The retail price includes the shop's rent and staff costs.","sceneCN":"这里这个词组指「商店卖给最终消费者的单件价格」（第 1 个义项：货架上面对顾客的标价）；句意为零售价里包含店铺的租金与人工成本。图中可辨识物件：货架、商品、价签、收银台。","pos":[{"tag":"n.","zh":"零售价（可数；指某件商品在零售环节的价格）"}],"collocations":[{"phrase":"recommended retail price","zh":"建议零售价"},{"phrase":"retail price index","zh":"零售价格指数"},{"phrase":"at retail price","zh":"按零售价"},{"phrase":"the retail price of","zh":"某物的零售价"},{"phrase":"average retail price","zh":"平均零售价"},{"phrase":"retail price gap","zh":"零售价差"}],"forms":[{"label":"复数","form":"retail prices"},{"label":"相关名词（零售）","form":"retail"},{"label":"相关名词（零售商）","form":"retailer"},{"label":"相关名词（零售业务）","form":"retailing"},{"label":"对照说法（批发价）","form":"wholesale price"},{"label":"限定用法","form":"retail-price（作定语时连写）"}],"derivatives":[{"word":"retail","pos":"n./v./adj./adv.","zh":"零售；零售的；以零售方式"},{"word":"retailer","pos":"n.","zh":"零售商"},{"word":"retailing","pos":"n.","zh":"零售业务"},{"word":"pricing","pos":"n.","zh":"定价；计价"},{"word":"priced","pos":"adj.","zh":"标价的；定价的"}],"senses":[{"no":"01","title":"The price a customer pays at the shelf","titleCN":"顾客在货架前支付的价格","definition":"the amount a shopper hands over for one item in a shop","definitionCN":"顾客在商店为一件商品付出的金额","example":"The retail price of the kettle is printed on the box.","exampleCN":"水壶的零售价印在盒子上。","why":"Retail names selling in small pieces, so the price attached to it is the price of one piece to one buyer.","whyCN":"「零售」指拆成小份卖出，所以附在它上面的价格就是一份商品卖给一位买家的价格。"},{"no":"02","title":"The manufacturer's suggested figure","titleCN":"厂商建议的数字","definition":"the price a maker recommends that shops charge, often printed on the packaging","definitionCN":"制造商建议商店收取的价格，常印在包装上","example":"The maker lowered the recommended retail price when the model aged.","exampleCN":"型号变旧之后，制造商下调了建议零售价。","why":"The same shelf figure can be set upstream, in which case it is a recommendation rather than a local decision.","whyCN":"同一个货架价格也可以由上游设定，这时它是建议，而不是店铺自己的决定。"},{"no":"03","title":"The price with sales tax included","titleCN":"含销售税的价格","definition":"the figure after tax is added at the counter, which is what the customer actually pays","definitionCN":"在收银台加上税之后的数字，也就是顾客实际支付的金额","example":"The label shows the retail price with tax already included.","exampleCN":"标签上的零售价已经含税。","why":"A shelf tag may be before tax, but the retail price in law is the full figure the buyer pays.","whyCN":"货架价签可能不含税，但法律意义上的零售价是买家支付的完整金额。"},{"no":"04","title":"The average price tracked in an index","titleCN":"指数所跟踪的平均价格","definition":"a statistical average of shop prices used to measure inflation","definitionCN":"用于衡量通胀的商店价格统计平均值","example":"The retail price index climbed as transport costs rose.","exampleCN":"随着运输成本上升，零售价格指数攀升。","why":"Collected across many shops, one tag becomes a series that stands for the whole country.","whyCN":"在许多商店采集之后，一张价签就变成代表整个国家的序列。"},{"no":"05","title":"The price actually charged after a markdown","titleCN":"降价之后实际收取的价格","definition":"the figure a shop charges once a discount has been applied to the tag","definitionCN":"价签被打了折扣之后商店实际收取的数字","example":"After the sale the retail price dropped by a quarter.","exampleCN":"促销之后，零售价降了四分之一。","why":"The shelf figure is the starting point, and a markdown is the same price after a subtraction.","whyCN":"货架上的数字是起点，降价就是同一价格减去一笔之后的样子。"},{"no":"06","title":"The price of a service or an experience","titleCN":"服务或体验的价格","definition":"the charge for a haircut, a meal or a night in a hotel rather than for goods on a shelf","definitionCN":"理发、用餐或住店一晚的收费，而非货架上商品的价钱","example":"The retail price of the tour covers the guide and the bus.","exampleCN":"这趟游览的零售价包含导游与巴士。","why":"Retail also sells time and attention, and the price of those is set the same way.","whyCN":"零售也出售时间与照料，它们的价格同样是这样定出来的。"},{"no":"07","title":"The end figure that wholesale must stay under","titleCN":"批发价必须低于的终端数字","definition":"the final amount that the earlier stages of the chain must leave room for","definitionCN":"链条前面各环节必须为之留出空间的最终金额","example":"The wholesale price cannot exceed the retail price the market will bear.","exampleCN":"批发价不能超过市场能承受的零售价。","why":"Seen from upstream, the shelf figure is a ceiling that every earlier price has to fit beneath.","whyCN":"从上游看，货架上的数字是一个上限，前面每一个价格都必须装得下。"},{"no":"08","title":"The advertised starting figure before negotiation","titleCN":"议价之前公布出的起价","definition":"the figure printed in an advert or on a window, from which a bargain may later move","definitionCN":"印在广告或橱窗上的数字，之后的讨价还价可能从此移动","example":"The retail price in the window was only a starting point.","exampleCN":"橱窗里的零售价只是一个起点。","why":"Where bargaining is normal, the published figure is an opening bid rather than a fixed charge.","whyCN":"在习惯议价的地方，公布的数字是开价，而不是固定收费。"}],"etymology":{"intro":{"en":"Retail comes from Old French retaillier, to cut up, built on a Latin noun for a piece cut off; it first meant selling goods in small pieces, and price comes from Latin pretium.","cn":"retail 来自古法语 retaillier「切碎」，其词根是拉丁语中表示「切下的一块」的名词；它最初指把货物拆成小份卖出，而 price 来自拉丁语 pretium。"},"items":[{"era":"LATIN TALEA","en":"Talea meant a cutting or a piece cut off, as from a branch or a block.","cn":"talea 意为「切下的一块」，如从枝条或木块上切下的部分。"},{"era":"LATIN TALIARE","en":"The verb taliare meant to cut, and it passed into French as taillier.","cn":"动词 taliare 意为「切」，传入法语后成为 taillier。"},{"era":"OLD FRENCH RETAILLIER","en":"Re- back plus taillier to cut gave retaillier, to cut up or cut off, and the noun retail named selling in small pieces.","cn":"表示「再、往回」的 re- 加 taillier「切」构成 retaillier「切碎、切下」，其名词形式指拆成小份卖出。"},{"era":"ENGLISH RETAIL","en":"English borrowed the word in the fifteenth century for selling goods in small quantities to final buyers.","cn":"英语在十五世纪借入这个词，指把货物小份卖给最终买家。"},{"era":"RETAIL PRICE","en":"The compound retail price became standard as shops began printing tags and advertising figures in the nineteenth century.","cn":"十九世纪商店开始印价签、登广告之后，retail price 这一组合成为标准说法。"},{"era":"STATISTICAL USE","en":"In the twentieth century the retail price index turned the shop figure into an official measure of inflation.","cn":"二十世纪的零售价格指数把商店里的数字变成官方的通胀度量。"}]},"similar":{"note":{"en":"The first group holds the trade word and its relatives plus one look-alike from the same cutting root; the second holds other names for a published figure.","cn":"第一组是行业词及其同族，再加一个同出「切」词根的形近词；第二组是公布价格的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"retail","ipa":"/ˈriːteɪl/","tag":"the trade itself","definition":"The activity or adjective of selling to final buyers; it names the stage, not the amount.","definitionCN":"面向最终买家出售的活动或形容词；它指环节，不指金额。"},{"word":"retailer","ipa":"/ˈriːteɪlə/","tag":"the shop","definition":"The business that sells to the public; a person or firm rather than a price.","definitionCN":"面向公众出售的企业；它指人或公司，不指价格。"},{"word":"detail","ipa":"/dɪˈteɪl/","tag":"same cutting root","definition":"A small part cut off from a whole; it shares the cutting root but takes a different prefix and means a item of information.","definitionCN":"从整体中切出的一小块；它同出「切」词根，但前缀不同，意思是一条具体信息。"},{"word":"wholesale price","ipa":"/ˌhəʊlˈseɪl praɪs/","tag":"the other end","definition":"The bulk figure paid before the shop adds its costs, the direct counterpart of retail price.","definitionCN":"店铺加上成本之前按整批支付的数字，正是零售价的直接对应。"}]},{"heading":"NEAR MEANING","entries":[{"word":"list price","ipa":"/lɪst praɪs/","tag":"published before discount","definition":"The price printed in a catalogue or on a tag before any reduction; a retail price may fall below it after a sale.","definitionCN":"目录或标签上在减价之前印出的价格；促销之后零售价可能低于它。"},{"word":"sticker price","ipa":"/ˈstɪkə praɪs/","tag":"the physical tag","definition":"The figure on the label stuck to the goods, often open to negotiation in some markets.","definitionCN":"贴在商品上的标签上的数字，在某些市场常可商量。"},{"word":"selling price","ipa":"/ˈselɪŋ praɪs/","tag":"what it actually goes for","definition":"The amount a seller finally accepts, which may be above or below the printed retail price.","definitionCN":"卖方最终接受的金额，可能高于也可能低于印出的零售价。"},{"word":"shelf price","ipa":"/ʃelf praɪs/","tag":"in the aisle","definition":"The figure displayed beside goods in a store; a practical name for the same retail figure.","definitionCN":"商店里摆在商品旁的数字，是同一个零售价的实用叫法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"The word first meant cutting a whole piece into small parts, and retail still sells in small parts.","cn":"这个词最初指把整块切开分成小份，而零售至今仍是拆成小份卖出。"},{"en":"The family runs retail, retailer, retailing and retail price.","cn":"同族说法包括零售、零售商、零售业务与零售价。"},{"en":"Fixed phrases mark the shop and the statistics: recommended retail price, retail price index, average retail price.","cn":"固定搭配标出商店与统计两面：建议零售价、零售价格指数、平均零售价。"},{"en":"Set it against wholesale price: one is on the shelf, the other at the loading bay.","cn":"把它与批发价对照：一个在货架上，一个在装货月台。"},{"en":"A price tag faces the customer, which is exactly who the retail price is for.","cn":"价签是朝向顾客的，而零售价正是给顾客看的。"}],"abstract":[{"en":"Picture a single orange cut free from the crate and priced on its own small label.","cn":"想象一只橙子从整箱里被切下来，单独贴上自己的小价签。"},{"en":"Picture a number standing at the end of a corridor of doors, growing larger at each door.","cn":"想象一个数字站在一列门的尽头，每过一道门就变大一些。"},{"en":"Picture a shop window where every object carries a small mirror reflecting its own price.","cn":"想象商店橱窗里每件物品都带一面小镜子，镜中映出它自己的价格。"}]},"examples":[{"en":"The retail price of the phone fell by a fifth within a year.","cn":"这款手机的零售价一年之内降了五分之一。"},{"en":"Shops may sell below the recommended retail price during a clearance.","cn":"清仓期间，商店可以低于建议零售价出售。"},{"en":"The retail price index is published every month.","cn":"零售价格指数每月公布一次。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「拆（re）成小份零卖」——货架上面对顾客的单件标价，就是零售价","word":"retail price"},"root":"retail 来自古法语 retaillier「切碎」，其词根为拉丁语 talea「切下的一块」，本义是拆成小份卖出；price 来自拉丁语 pretium「价值、价格」。","sensesIntro":{"en":"Eight senses follow one tag: the figure at the shelf, the maker's suggestion, the taxed total, an index average, a marked-down figure, a service charge, the ceiling for wholesale and an opening bid.","cn":"八个义项跟着同一张价签：货架上的数字、厂商的建议、含税的总额、指数平均值、降价后的数字、服务收费、批发价的上限，以及一个开价。"},"semanticMap":{"core":{"en":"CORE IMAGE: one tag turned toward the customer, with the shop counter sitting directly below it.","cn":"核心意象：一张朝向顾客的价签，正下方就是收银台。"},"chain":["SELL IN SMALL PARTS","ONE TAG, ONE BUYER","SET UPSTREAM","ADD THE TAX","AVERAGE THE TOWN","THE CEILING ABOVE WHOLESALE"],"branches":[{"senses":"01 · 06","en":"ONE BUYER, GOODS OR SERVICE: the same tag stands in front of an object or an hour of someone's time.","cn":"一位买家，货物或服务：同一张价签既立在物品前，也立在他人的一小时劳动前。"},{"senses":"02 · 03","en":"WHO WRITES THE FIGURE: a maker upstream or a tax office at the counter can both fix the number.","cn":"谁写下这个数字：上游的制造商或收银台的税务规则都能把它定下。"},{"senses":"04","en":"MANY TAGS: collected across shops, one figure becomes an average.","cn":"许多价签：在许多商店采集后，一个数字变成平均值。"},{"senses":"05 · 08","en":"MOVING FIGURES: a sale lowers it and a bargain moves it from an opening bid.","cn":"会动的数字：促销把它压低，讨价还价则让它从一个开价开始移动。"},{"senses":"07","en":"SEEN FROM UPSTREAM: the shelf figure is the ceiling every earlier price must fit under.","cn":"从上游看：货架上的数字是前面每个价格都必须装得下的上限。"}]},"affixes":{"intro":{"en":"The phrase joins a French verb of cutting with a Latin noun of value, so it reads as selling in cut pieces at a stated worth.","cn":"这个短语把法语中表示「切」的动词与拉丁语中表示价值的名词组合起来，读作「把切小的份按定价卖出」。"},"latinIntro":{"en":"Latin talea and taliare supply the retail half; Latin pretium supplies the price half and also stands behind precious and appraise.","cn":"拉丁语 talea 与 taliare 提供前半，拉丁语 pretium 提供后半，pretium 还支撑着 precious 与 appraise。"},"items":[{"word":"re-","structure":"re- (Latin prefix, back, again)","meaning":"back; again","meaningCN":"往回；再","example":"The prefix adds the idea of cutting back into pieces.","exampleCN":"这个前缀添上「往回切、切成小块」的意思。"},{"word":"talea","structure":"talea, -ae (f., first declension; Latin)","meaning":"a cutting, a piece cut off","meaningCN":"切下的一块","example":"The noun supplies the image of a piece cut from a whole.","exampleCN":"这个名词提供「从整体切下一块」的意象。"},{"word":"taliare","structure":"taliare (Late Latin verb, to cut)","meaning":"to cut","meaningCN":"切；切开","example":"The verb becomes taillier in Old French.","exampleCN":"这个动词在古法语中变成 taillier。"},{"word":"retail","structure":"re- + taillier (to cut up)","meaning":"to sell in small quantities","meaningCN":"零售；拆成小份卖出","example":"The shop retails the cloth by the metre.","exampleCN":"这家店把布按米零售。"},{"word":"retailer","structure":"retail + -er (one who does)","meaning":"a shop that sells to the public","meaningCN":"零售商","example":"The retailer buys in bulk and sells in pieces.","exampleCN":"零售商整批买进，再拆成小份卖出。"},{"word":"retailing","structure":"retail + -ing (the business of)","meaning":"the trade of selling to final buyers","meaningCN":"零售业务","example":"Retailing now employs more people than manufacturing.","exampleCN":"零售业务现在雇用的人比制造业还多。"},{"word":"price","structure":"Latin pretium, through Old French pris","meaning":"the amount asked","meaningCN":"价格；要价","example":"The price is written on the tag.","exampleCN":"价格写在价签上。"},{"word":"detail","structure":"de- + taillier","meaning":"a small part; an item of information","meaningCN":"细部；一条具体信息","example":"The report lists every detail of the order.","exampleCN":"报告列出了订单的每一个细目。"},{"word":"wholesale","structure":"whole + sale (native compound)","meaning":"selling in bulk","meaningCN":"批发；整批卖出","example":"Wholesale sits one step before retail.","exampleCN":"批发站在零售的前一步。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one that performs an action","meaningCN":"做某事的人或物","example":"The suffix turns a trade into its keeper.","exampleCN":"这个后缀把「行业」变成「从业者」。"}],"latinEntries":[{"word":"talea","structure":"talea, -ae (f., first declension; Latin)","meaning":"a cutting, a piece cut off","meaningCN":"切下的一块"},{"word":"taliare","structure":"taliare (Late Latin verb)","meaning":"to cut","meaningCN":"切；切开"},{"word":"pretium","structure":"pretium, -i (n., second declension; Latin)","meaning":"price, value, worth","meaningCN":"价格；价值"}]}},{"word":"markup","ipa_uk":"/ˈmɑːkʌp/","ipa_us":"/ˈmɑːrkʌp/","definition_zh":"加价；加价幅度；在文稿或文档上加的标记","definition_en":"an amount added to cost in setting a price, or marks and instructions added to a text or a document","core_image":"成本单上写着进货价，旁边用红笔向上画一道箭头，箭头末端写着新售价","scene":"采购员在成本单的进货价旁边画了一道向上的箭头，把新售价写在箭头末端。The shop applies a forty percent markup to imported goods.","sceneCN":"这里这个词指「在成本之上加出的那部分价格」（第 1 个义项：成本与售价之间的加价额）；句意为这家店对进口商品加价四成。图中可辨识物件：成本单、向上的箭头、新售价、红笔。","pos":[{"tag":"n.","zh":"加价；加价幅度；标记（文稿或文档上的标注）"},{"tag":"v.","zh":"加价；在文本上作标注（通常写作两个词）"}],"collocations":[{"phrase":"markup on cost","zh":"在成本上的加价"},{"phrase":"markup percentage","zh":"加价百分比"},{"phrase":"price markup","zh":"价格加价"},{"phrase":"markup language","zh":"标记语言"},{"phrase":"markup rate","zh":"加价率"},{"phrase":"add a markup","zh":"加上一笔加价"}],"forms":[{"label":"复数","form":"markups"},{"label":"连字符写法","form":"mark-up"},{"label":"动词（分写）","form":"mark up"},{"label":"动词三单","form":"marks up"},{"label":"动词过去式","form":"marked up"},{"label":"动词现在分词","form":"marking up"},{"label":"对照名词（降价）","form":"markdown"}],"derivatives":[{"word":"mark","pos":"n./v.","zh":"标记；作记号"},{"word":"mark up","pos":"v.","zh":"加价；在文稿上标注"},{"word":"marked-up","pos":"adj.","zh":"加过价的；标注过的"},{"word":"markdown","pos":"n.","zh":"降价；减价"},{"word":"marking","pos":"n.","zh":"标记；批改"}],"senses":[{"no":"01","title":"An amount added over cost","titleCN":"加在成本之上的那笔钱","definition":"the sum by which a seller raises its cost to reach a selling price","definitionCN":"卖方把自己的成本提高到售价时所加上的金额","example":"The dealer's markup on each car covers transport and warranty.","exampleCN":"经销商在每辆车上加的价涵盖运输与保修。","why":"To mark up is literally to write a higher figure above the cost line, so the difference is the addition.","whyCN":"「往上标」字面上就是在成本那一行上方写一个更高的数字，差额就是加上的部分。"},{"no":"02","title":"The added amount as a percentage of cost","titleCN":"以成本为基数的加价百分比","definition":"the addition expressed as a share of what the seller paid, not of the selling price","definitionCN":"把加价额表示成占进货成本的比例，而不是占售价的比例","example":"A markup of half the cost doubles the wholesale figure.","exampleCN":"加价达到成本的一半，就把批发数字翻了一倍。","why":"Because the base is cost, the same money appears as a larger percentage than a margin would.","whyCN":"因为基数取成本，同一笔钱用加价率表示会比用利润率表示显得更大。"},{"no":"03","title":"A pricing rule applied across a line of goods","titleCN":"对一整类商品统一套用的定价规则","definition":"a fixed addition charged on every item in a category rather than negotiated item by item","definitionCN":"对某一类中每件商品统一加收的固定额度，而非逐件谈定","example":"The chain uses a standard markup for all stationery.","exampleCN":"这家连锁店对所有文具采用统一加价。","why":"Once the addition is written into a rule, the word names the policy rather than one sum.","whyCN":"当加价被写进规则，这个词指的就是政策，而不是某一笔金额。"},{"no":"04","title":"Typesetting instructions written on a manuscript","titleCN":"写在稿件上的排版指令","definition":"the notes a designer or editor writes beside text to specify type, spacing and layout","definitionCN":"设计者或编辑写在文字旁、用来说明字体、间距与版面的注记","example":"The printer followed every markup in the margin.","exampleCN":"印刷方照着页边上的每一条标注执行。","why":"The marks are added on top of the text, which is the original physical sense of marking up.","whyCN":"这些记号是加在文字之上的，这正是「标注」最原始的实物含义。"},{"no":"05","title":"A system of tags that describes a document","titleCN":"用标签描述文档结构的体系","definition":"a set of codes placed around content to say what each part is, without changing the words themselves","definitionCN":"围绕内容放置的一套代码，用来说明每一部分是什么，而不改动文字本身","example":"The page is written in a simple markup that any browser can read.","exampleCN":"这个页面用一种任何浏览器都能读懂的简单标记写成。","why":"Tags stand above the visible text the way an editor's marks stand above a proof.","whyCN":"标签悬在可见文字之上，正如编辑的记号悬在校样之上。"},{"no":"06","title":"An editor's marks on a proof","titleCN":"编辑在校样上留下的修改记号","definition":"corrections and queries written on a printed draft before it is final","definitionCN":"在定稿之前写在打印草稿上的修改与疑问","example":"Her markup covered the whole first page in red.","exampleCN":"她的修改记号用红色盖满了整页。","why":"This is the everyday printing sense: a draft is marked so that it can be corrected.","whyCN":"这是印刷业的日常义：在草稿上作记号，好据此修改。"},{"no":"07","title":"A price increase made at one stroke","titleCN":"一次调高中加入的幅度","definition":"the amount by which a price is raised in a single revision","definitionCN":"一次调价中售价被抬高的幅度","example":"The sudden markup caught regular customers by surprise.","exampleCN":"突然的加价让老顾客措手不及。","why":"Instead of the gap between cost and price, the word can name the upward step itself.","whyCN":"这个词可以不指成本与售价之间的差，而指向上迈出的那一步本身。"},{"no":"08","title":"The accountant's figure, counted on cost","titleCN":"会计口径的数字，以成本为分母","definition":"the added sum measured against cost, which is why it differs from a margin measured against sales","definitionCN":"以成本为分母衡量的加价额，因此与以销售额为分母的利润率不同","example":"The auditor recalculated the markup and the margin separately.","exampleCN":"审计人员分别重算了加价率与利润率。","why":"Two ratios can describe one price gap; the difference lies in which figure sits underneath.","whyCN":"同一个价格差可以由两个比率描述，差别只在于下面放的是哪个数字。"}],"etymology":{"intro":{"en":"Markup joins the native English noun mark, from Old English mearc, with the particle up; the pricing sense and the printing sense both rest on writing a mark above something.","cn":"markup 由英语本族名词 mark（来自古英语 mearc）与副词性小品词 up 组合而成；定价义与排版义都建立在「在某物上方作记号」这一动作上。"},"items":[{"era":"OLD ENGLISH MEARC","en":"Mearc meant a boundary, a sign or a trace, and became the modern noun mark.","cn":"mearc 意为「边界、记号、痕迹」，后来成为现代名词 mark。"},{"era":"PROTO-GERMANIC MARKA","en":"The earlier form marka is a reconstruction, not a recorded word, so any statement about its exact shape is a reconstructed form.","cn":"更早的形式 marka 是重构出来的，并非有记录的词，因此关于它确切形态的说法都属于重构形式。"},{"era":"MIDDLE ENGLISH MARK","en":"In Middle English mark named a visible sign, a written note or a target, and the verb meant to put such a sign on something.","cn":"在中古英语中，mark 指可见的记号、写下的注记或靶标，动词义则是在某物上留下这种记号。"},{"era":"PHRASAL MARK UP","en":"The combination mark up meant to write marks on a page, and later to raise a figure, since the new figure is written above the old one.","cn":"mark up 这一组合先指在纸页上写记号，后来指抬高数字，因为新数字写在旧数字上方。"},{"era":"PRINTING AND PROOFREADING","en":"In printing houses markup became the standard word for instructions written in the margin of a proof.","cn":"在印刷厂里，markup 成为写在页边、用来说明排版的指令的标准叫法。"},{"era":"DIGITAL MARKUP","en":"The computer age reused the word for tags placed around text to describe its structure.","cn":"计算机时代把这个词再次用于围绕文字、用来说明结构的标签。"}]},"similar":{"note":{"en":"The first group holds the base word and its opposite; the second holds accounting and pricing terms that are close in use but not in base.","cn":"第一组是基础词与其反义说法；第二组是用法相近、但计算基数不同的会计与定价术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mark","ipa":"/mɑːk/","tag":"the base word","definition":"A sign, trace or written note; the compound simply adds the idea of placing it above something.","definitionCN":"记号、痕迹或写下的注记；复合词只是加上「放在某物上方」的意思。"},{"word":"marked","ipa":"/ˈmɑːkɪd/","tag":"not the same compound","definition":"Bearing a mark, or noticeably different; it says nothing about a price being raised.","definitionCN":"带有记号，或明显不同；它不表示价格被抬高。"},{"word":"markdown","ipa":"/ˈmɑːkdaʊn/","tag":"the opposite direction","definition":"A reduction written below the old figure; it is the mirror image of a markup.","definitionCN":"写在旧数字下方的一次下调，是加价的反向对应。"},{"word":"mark up","ipa":"/ˌmɑːk ˈʌp/","tag":"two-word verb","definition":"The verb form, spelled as two words, meaning to raise a price or to annotate a text.","definitionCN":"分写成两个词的动词形式，意为抬高价格或在文本上作标注。"}]},{"heading":"NEAR MEANING","entries":[{"word":"margin","ipa":"/ˈmɑːdʒɪn/","tag":"measured on sales","definition":"The share of the selling price left after costs; it uses sales as its base, while a markup uses cost.","definitionCN":"售价扣除成本后剩下的比例；它以销售额为基数，而加价以成本为基数。"},{"word":"surcharge","ipa":"/ˈsɜːtʃɑːdʒ/","tag":"an extra charge","definition":"An additional charge added to a stated price for a specific reason, such as fuel or a late payment.","definitionCN":"因特定原因在已定价格上追加的费用，如燃油附加或逾期附加。"},{"word":"premium","ipa":"/ˈpriːmiəm/","tag":"a higher price for quality","definition":"An amount above the normal price, charged because of quality, scarcity or urgency.","definitionCN":"因品质、稀缺或急迫而在正常价格之上加收的金额。"},{"word":"price rise","ipa":"/praɪs raɪz/","tag":"the event, not the ratio","definition":"The event of a price going up, without reference to cost or to any fixed percentage.","definitionCN":"价格上升这件事本身，不涉及成本，也不涉及某个固定百分比。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Mark plus up: a higher figure written above the cost line.","cn":"「标记」加「向上」：在成本那一行上方写一个更高的数字。"},{"en":"The family runs mark, mark up, marked-up, markdown and marking.","cn":"同族词包括 mark、mark up、marked-up、markdown 与 marking。"},{"en":"Fixed phrases mark the shop and the page: markup on cost, markup percentage, markup language.","cn":"固定搭配标出商店与页面两面：成本加价、加价百分比、标记语言。"},{"en":"Keep markup and margin apart by the base: cost underneath for markup, sales underneath for margin.","cn":"用基数区分加价与利润率：加价下面放成本，利润率下面放销售额。"},{"en":"A proof covered in red notes and a price tag raised in red ink are the same gesture on paper.","cn":"校样上写满红色批注，与用红笔抬高价签，是纸面上同一个动作。"}],"abstract":[{"en":"Picture a ladder standing on the cost line, with a new price sitting on its top rung.","cn":"想象一架梯子立在成本线上，新价格坐在最上面一级。"},{"en":"Picture a page whose margins are crowded with small arrows pointing at the words.","cn":"想象一页纸的页边挤满了指向文字的小箭头。"},{"en":"Picture two fractions sharing one numerator but standing on different floors.","cn":"想象两个分数共用一个分子，却站在不同的楼层上。"}]},"examples":[{"en":"The bookseller adds a small markup to the publisher's price.","cn":"书商在出版社的价格上加了一小笔加价。"},{"en":"A high markup does not always mean a high margin.","cn":"高加价并不总意味着高利润率。"},{"en":"The designer sent the manuscript back with markup in every margin.","cn":"设计师把稿件退回，每页页边都写满了标注。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「往上（up）标（mark）」——在成本上面写一个更高的数 → 加价；在文稿上面写记号 → 标注","word":"markup"},"root":"英语本族复合：mark 来自古英语 mearc「边界、记号」，加表示「向上」的小品词构成；加价义来自「在成本上方写更高数字」，标注义来自「在纸页上写记号」。","sensesIntro":{"en":"Eight senses follow one gesture: a sign is written above something, whether the figure above a cost line, a rule for a whole line of goods, instructions above a manuscript, tags above a page, or the accountant's ratio built on cost.","cn":"八个义项沿同一个动作展开：在某物上方写下记号，可以是成本行上方的数字、整类商品的加价规则、稿件上方的排版指令、页面上的标签，或会计以成本为基数的比率。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cost line with an arrow drawn upward from it and a higher figure at the tip.","cn":"核心意象：一条成本线，从它向上画出一道箭头，箭头尖端是一个更高的数字。"},"chain":["WRITE ABOVE","RAISE THE FIGURE","RULE FOR A LINE","INSTRUCTIONS ON A PROOF","TAGS ON A PAGE","RATIO ON COST"],"branches":[{"senses":"01 · 07","en":"THE UPWARD STEP: one sum added over cost, or the whole step by which a price is lifted.","cn":"向上的一步：加在成本上的一笔金额，或价格被抬高的整个幅度。"},{"senses":"02 · 08","en":"THE RATIO: the same gap measured against cost, which is what separates it from a margin.","cn":"比率：同一个差额以成本为分母衡量，这正是它与利润率的分别。"},{"senses":"03","en":"WRITTEN INTO POLICY: a standard addition applied to a whole category.","cn":"写进政策：对一整类商品统一套用的加价。"},{"senses":"04 · 06","en":"MARKS ON PAPER: typesetting notes and proof corrections are the same written sign.","cn":"纸上的记号：排版注记与校样修改是同一个写下的记号。"},{"senses":"05","en":"MARKS AROUND CONTENT: digital tags describe a page the way margin notes describe a proof.","cn":"内容周围的记号：数字标签描述页面，正如页边注描述校样。"}]},"affixes":{"intro":{"en":"The word is a native compound of a noun for a sign and a particle meaning upward, so every sense keeps the picture of a mark placed above something.","cn":"这个词由表示「记号」的本族名词与表示「向上」的小品词复合而成，因此每个义项都保留「把记号放在某物上方」的画面。"},"latinIntro":{"en":"There is no Latin root here: mark is Germanic and up is a native particle, so the Latin entries stay empty.","cn":"这里没有拉丁词根：mark 属日耳曼语，up 是本族小品词，因此拉丁语词形一栏留空。"},"items":[{"word":"mark","structure":"Old English mearc (boundary, sign)","meaning":"a sign; a trace","meaningCN":"记号；痕迹","example":"A red mark beside the price means it has changed.","exampleCN":"价格旁边的红记号表示它已变动。"},{"word":"up","structure":"Old English up, adverb and particle","meaning":"toward a higher place","meaningCN":"向上；在高处","example":"The particle turns the mark into an upward movement.","exampleCN":"这个小品词把「记号」变成向上的动作。"},{"word":"markup","structure":"mark + up","meaning":"an addition over cost; written marks","meaningCN":"加价；标注","example":"The shop keeps a steady markup on staples.","exampleCN":"这家店对主粮维持稳定的加价。"},{"word":"mark up","structure":"verb + particle","meaning":"to raise a price; to annotate","meaningCN":"抬高价格；作标注","example":"The manager marked up the winter stock in October.","exampleCN":"经理在十月调高了冬货的价格。"},{"word":"marked-up","structure":"marked + up (participial adjective)","meaning":"priced higher; covered with notes","meaningCN":"已加价的；写满标注的","example":"The marked-up copy went back to the author.","exampleCN":"写满标注的那一份被送回作者手中。"},{"word":"markdown","structure":"mark + down","meaning":"a reduction in price","meaningCN":"降价；减价","example":"A markdown cleared the last of the stock.","exampleCN":"一次降价把最后的存货清掉了。"},{"word":"marking","structure":"mark + -ing (the act)","meaning":"the act of putting marks","meaningCN":"作记号；批改","example":"The marking took the editor a whole evening.","exampleCN":"作标注花了编辑一整晚。"},{"word":"marker","structure":"mark + -er (the instrument)","meaning":"a pen or tool that marks","meaningCN":"记号笔；标记工具","example":"She used a red marker on the cost sheet.","exampleCN":"她在成本单上用了红色记号笔。"},{"word":"remark","structure":"re- + mark (native verb)","meaning":"to notice and say something","meaningCN":"评论；注意到","example":"He remarked that the price had doubled.","exampleCN":"他评论说价格翻了一倍。"},{"word":"landmark","structure":"land + mark","meaning":"a boundary sign; a notable feature","meaningCN":"界标；地标","example":"The tower has been a landmark for a century.","exampleCN":"这座塔作为地标已有一百年。"}],"latinEntries":[]}},{"word":"profit margin","ipa_uk":"/ˈprɒfɪt ˌmɑːdʒɪn/","ipa_us":"/ˈprɑːfɪt ˌmɑːrdʒɪn/","definition_zh":"利润率；利润占销售收入的比重","definition_en":"the share of sales revenue that a business keeps as profit after its costs are paid","core_image":"收支表最下面一行，收入数字旁边留出一小块空白，那一小块被红框框住并写上比例","scene":"会计把全年收入与各项成本写进表格，最后在收入旁边框出剩下的那一小块。A thin profit margin forced the factory to raise its prices.","sceneCN":"这里这个词组指「利润占销售收入的比重」（第 1 个义项：毛利口径的利润率）；句意为微薄的利润率迫使工厂提价。图中可辨识物件：收支表、收入数字、被框出的一小块、红笔。","pos":[{"tag":"n.","zh":"利润率（可数；指利润占销售收入的比重）"}],"collocations":[{"phrase":"gross profit margin","zh":"毛利率"},{"phrase":"net profit margin","zh":"净利率"},{"phrase":"thin profit margin","zh":"微薄的利润率"},{"phrase":"operating profit margin","zh":"营业利润率"},{"phrase":"improve the profit margin","zh":"提高利润率"},{"phrase":"profit margin on sales","zh":"销售利润率"}],"forms":[{"label":"复数","form":"profit margins"},{"label":"相关名词（利润）","form":"profit"},{"label":"相关形容词（边缘的；边际的）","form":"marginal"},{"label":"相关名词（毛利）","form":"gross margin"},{"label":"相关名词（净利）","form":"net margin"},{"label":"相关名词（利润率，同义）","form":"margin"}],"derivatives":[{"word":"profit","pos":"n./v.","zh":"利润；获利"},{"word":"profitable","pos":"adj.","zh":"有利可图的"},{"word":"profitability","pos":"n.","zh":"盈利能力"},{"word":"margin","pos":"n.","zh":"利润率；差额；页边"},{"word":"marginal","pos":"adj.","zh":"边际的；微小的"}],"senses":[{"no":"01","title":"Gross margin, before overheads","titleCN":"扣除日常开销之前的毛利率","definition":"the share left from sales after only the direct cost of the goods is subtracted","definitionCN":"销售额在只扣除货物直接成本之后剩下的比重","example":"The bakery's gross profit margin stays near a third.","exampleCN":"这家面包店的毛利率维持在三成左右。","why":"Margin first meant the edge of a page; the accounting sense is what is left at the edge of a sale.","whyCN":"margin 本指纸页的边缘；会计义指一笔销售走到边缘时剩下的部分。"},{"no":"02","title":"Net margin, after everything","titleCN":"扣除一切之后的净利率","definition":"the share left after all costs, interest and tax have been paid","definitionCN":"在支付全部成本、利息与税款之后剩下的比重","example":"After the loan was repaid the net profit margin fell to a few percent.","exampleCN":"偿还贷款之后，净利率降到几个百分点。","why":"The edge moves inward as more layers of cost are peeled away.","whyCN":"随着一层层成本被剥去，那道边缘就向内收。"},{"no":"03","title":"Operating margin, before financing","titleCN":"融资成本之前的营业利润率","definition":"the share left from ordinary operations, before interest and tax are counted","definitionCN":"日常经营剩下、尚未计入利息与税款的比重","example":"The operating profit margin improved when the old plant closed.","exampleCN":"旧厂关闭之后，营业利润率有所提高。","why":"This is the edge of the trading itself, with the cost of money still outside the line.","whyCN":"这是交易本身的边缘，资金成本还站在线外。"},{"no":"04","title":"Margin on a single product","titleCN":"单件产品的利润率","definition":"the profit left by one item, measured against what that item sold for","definitionCN":"一件商品带来的利润，相对该商品的售价来衡量","example":"The margin on each pair of shoes is smaller than on the bags.","exampleCN":"每双鞋的利润率低于每只包的利润率。","why":"The same ratio can be narrowed from a whole firm to one line on a shelf.","whyCN":"同一个比率可以从整个公司缩小到货架上的一个品类。"},{"no":"05","title":"A thin industry average","titleCN":"行业里微薄的平均水平","definition":"the low figure typical of a trade where competition keeps prices close to cost","definitionCN":"竞争使价格紧贴成本的那种行业所常见的低水平","example":"Grocers survive on a thin profit margin and high volume.","exampleCN":"杂货商靠微薄的利润率与高销量维持。","why":"When the edge is narrow, the word describes the whole trade rather than one firm.","whyCN":"当那道边缘很窄时，这个词描述的是整个行业，而不只是一家公司。"},{"no":"06","title":"A buffer against shocks","titleCN":"抵挡冲击的缓冲","definition":"the amount of profit that can absorb a rise in costs before losses begin","definitionCN":"在开始亏损之前能够吸收成本上涨的利润额度","example":"A healthy profit margin let the airline survive the fuel spike.","exampleCN":"健康的利润率让这家航空公司挺过了燃油价格暴涨。","why":"A margin is space at the edge, and space is exactly what absorbs a blow.","whyCN":"margin 是边缘上的余地，而余地正是吸收打击的东西。"},{"no":"07","title":"The figure that is not a markup","titleCN":"与加价率不同的那个数字","definition":"profit measured against sales, as opposed to an addition measured against cost","definitionCN":"以销售额为分母的利润，与以成本为分母的加价相对","example":"Managers often confuse the profit margin with the markup on cost.","exampleCN":"管理者常把利润率与成本加价率混为一谈。","why":"The two numbers describe one gap from opposite ends, so they can never be equal.","whyCN":"两个数字从两端描述同一个差额，因此永远不可能相等。"},{"no":"08","title":"A target set in a plan","titleCN":"写进计划的目标值","definition":"a figure that a business aims to reach, written into a budget or a strategy","definitionCN":"企业力争达到、写进预算或战略的数值","example":"The new plan sets a profit margin target for every region.","exampleCN":"新计划给每个区域都设定了利润率目标。","why":"Once a ratio is chosen as a goal, the word shifts from description to intention.","whyCN":"当一个比率被选为目标，这个词就从描述变成了意图。"}],"etymology":{"intro":{"en":"Profit comes from Latin profectus, progress or gain, built on proficere to accomplish; margin comes from Latin margo, edge or border. Their accounting pairing is modern.","cn":"profit 来自拉丁语 profectus「进展、收益」，由 proficere「完成、取得」构成；margin 来自拉丁语 margo「边缘、边界」。两者在会计上的搭配是近代的事。"},"items":[{"era":"LATIN PROFICERE","en":"Proficere joined pro- forward with facere to do, and meant to make progress or to accomplish something.","cn":"proficere 由表示「向前」的 pro- 与 facere「做」构成，意为「取得进展、完成某事」。"},{"era":"LATIN PROFECTUS","en":"The noun profectus named progress or an advance, and in commercial Latin it came to mean gain.","cn":"名词 profectus 指「进展、前进」，在商业拉丁语中逐渐指「收益」。"},{"era":"OLD FRENCH PROFIT","en":"Old French profit carried the commercial sense into English, where profit named the gain from a transaction.","cn":"古法语 profit 把这个商业义带入英语，profit 指一笔交易带来的收益。"},{"era":"LATIN MARGO","en":"Margo meant an edge, a border or a brink, and it survives in English margin as the blank edge of a page.","cn":"margo 意为「边缘、边界、崖沿」，在英语 margin 中保留为纸页的空白边缘。"},{"era":"ENGLISH MARGIN","en":"Margin extended from the edge of a page to any difference or allowance, including the space between cost and price.","cn":"margin 从纸页边缘扩展到任何差额或余量，包括成本与价格之间的空间。"},{"era":"ACCOUNTING COMPOUND","en":"Profit margin became a fixed accounting term once firms began reporting profit as a share of sales.","cn":"当企业开始把利润按占销售额的比例报告时，profit margin 成为固定的会计术语。"}]},"similar":{"note":{"en":"The first group holds the two words that make the phrase and their near forms; the second holds other measures of what a business keeps.","cn":"第一组是构成这个短语的两个词及其近形；第二组是衡量企业留存的其他指标。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"margin","ipa":"/ˈmɑːdʒɪn/","tag":"the edge, then the ratio","definition":"The blank edge of a page, and by extension the difference between two figures; it carries the second half of the phrase.","definitionCN":"纸页的空白边缘，引申为两个数字之间的差；它构成短语的后半。"},{"word":"marginal","ipa":"/ˈmɑːdʒɪnəl/","tag":"adjective, not the ratio","definition":"At the edge, hence small or barely worth doing; it describes size, not a percentage of sales.","definitionCN":"处在边缘的，因此指微小或几乎不值得做；它描述大小，不指占销售额的比例。"},{"word":"markup","ipa":"/ˈmɑːkʌp/","tag":"measured on cost","definition":"The addition over cost; it uses cost as its base, which is the opposite base from a profit margin.","definitionCN":"在成本之上的加价；它以成本为基数，与利润率的基数正好相反。"},{"word":"profit","ipa":"/ˈprɒfɪt/","tag":"the amount, not the ratio","definition":"The money gained itself; a margin turns that money into a share of sales.","definitionCN":"实际赚到的钱本身；利润率则把这笔钱变成占销售额的比重。"}]},{"heading":"NEAR MEANING","entries":[{"word":"return","ipa":"/rɪˈtɜːn/","tag":"gain on money invested","definition":"The gain measured against what was put in, often used for investments rather than for shop sales.","definitionCN":"相对投入衡量的收益，常用于投资，而不常用于店铺销售。"},{"word":"spread","ipa":"/spred/","tag":"gap between two prices","definition":"The difference between a buying price and a selling price, common in trading and lending.","definitionCN":"买入价与卖出价之间的差，常见于交易与借贷。"},{"word":"earnings","ipa":"/ˈɜːnɪŋz/","tag":"the total, reported","definition":"A firm's reported profit for a period, stated as an amount rather than as a share of sales.","definitionCN":"企业某一期公布的利润，以金额而非占销售额的比例表示。"},{"word":"gross income","ipa":"/ɡrəʊs ˈɪnkʌm/","tag":"before deductions","definition":"Money received before costs or tax are taken out; it is a total, while a margin is a ratio.","definitionCN":"在扣除成本或税之前收到的钱；它是总额，而利润率是比率。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Profit plus margin: the gain measured at the edge of a sale.","cn":"「收益」加「边缘」：在销售的边缘上衡量的收益。"},{"en":"The family runs profit, profitable, profitability, margin and marginal.","cn":"同族词包括 profit、profitable、profitability、margin 与 marginal。"},{"en":"Fixed phrases mark the layers: gross profit margin, net profit margin, operating profit margin.","cn":"固定搭配标出层次：毛利率、净利率、营业利润率。"},{"en":"Remember the base: a margin sits on sales, a markup sits on cost.","cn":"记住基数：利润率坐在销售额上，加价率坐在成本上。"},{"en":"A thin margin is a narrow ledge: there is little room left before a fall.","cn":"微薄的利润率就是一条窄窄的台子：在跌落之前几乎没有余地。"}],"abstract":[{"en":"Picture a page whose margin is the only white space left after the text of costs fills it.","cn":"想象一页纸被成本写满，只剩下页边那一点空白。"},{"en":"Picture a narrow ledge above a drop, wide enough for one foot only.","cn":"想象悬崖边一条窄窄的台子，只够放一只脚。"},{"en":"Picture the same gap seen from two shores, one calling it cost, the other calling it sales.","cn":"想象同一个缺口从两岸看过去，一岸称它成本，另一岸称它销售额。"}]},"examples":[{"en":"The firm's net profit margin has stayed above ten percent for five years.","cn":"这家公司的净利率已连续五年保持在百分之十以上。"},{"en":"Discounting can raise volume while shrinking the profit margin.","cn":"打折可以提高销量，同时压缩利润率。"},{"en":"Small farms work on a profit margin too thin to absorb one bad season.","cn":"小农场的利润率太薄，承受不住一个坏季节。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「收益（profit）留在页边（margin）」——卖出去的钱走到边缘时剩下的那一小块 → 利润率","word":"profit margin"},"root":"profit 来自拉丁语 profectus「进展、收益」，由 pro-「向前」与 facere「做」构成；margin 来自拉丁语 margo「边缘、边界」，引申为差额与余量。","sensesIntro":{"en":"Eight senses follow one ratio as it is peeled inward: gross, net, operating, a single product, an industry average, a buffer, the contrast with a markup, and a target written into a plan.","cn":"八个义项跟着同一个比率向内剥：毛利、净利、营业、单件产品、行业平均、缓冲余地、与加价率的对照，最后是写进计划的目标。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger page filled with costs, with one small boxed space left at the edge.","cn":"核心意象：一页写满成本的账簿，边缘还留着一小块被框住的空白。"},"chain":["GAIN FROM A SALE","EDGE OF THE PAGE","WHAT IS LEFT","LAYER BY LAYER","NARROW LEDGE","A WRITTEN TARGET"],"branches":[{"senses":"01 · 02 · 03","en":"LAYERS OF COST: gross, net and operating differ only in how many layers have been peeled away.","cn":"成本的层次：毛利、净利与营业利润的差别只在于剥去了几层。"},{"senses":"04","en":"ONE ITEM: the same ratio narrowed from a firm to a single pair of shoes.","cn":"单件商品：同一个比率从一家公司缩小到一双鞋。"},{"senses":"05","en":"A WHOLE TRADE: a narrow ledge becomes the description of an industry.","cn":"整个行业：一条窄台子成了对一个行业的描述。"},{"senses":"06","en":"SPACE AS SHOCK ABSORBER: the width of the edge is what absorbs a rise in costs.","cn":"作为缓冲的余地：边缘的宽度就是吸收成本上涨的东西。"},{"senses":"07 · 08","en":"THE OTHER BASE AND THE GOAL: the ratio is distinguished from a markup and then fixed as a target.","cn":"另一个基数与目标：这个比率先与加价率区分开，再被固定为目标。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of gain with a Latin noun of edge, so it reads as the gain that remains at the edge of a sale.","cn":"这个短语把拉丁语中表示「收益」的名词与表示「边缘」的名词组合起来，读作「一笔销售走到边缘时留下的收益」。"},"latinIntro":{"en":"Latin proficere and profectus supply profit; Latin margo supplies margin, which also stands behind marginal.","cn":"拉丁语 proficere 与 profectus 提供 profit；拉丁语 margo 提供 margin，marginal 也出自同一词根。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, forward)","meaning":"forward; in front","meaningCN":"向前；在前","example":"The prefix turns doing into getting ahead.","exampleCN":"这个前缀把「做」变成「向前取得」。"},{"word":"facere","structure":"facere (Latin verb, to do, make)","meaning":"to do; to make","meaningCN":"做；制造","example":"The verb supplies the act at the heart of profit.","exampleCN":"这个动词提供「收益」一词核心处的行动。"},{"word":"proficere","structure":"pro- + facere","meaning":"to make progress, accomplish","meaningCN":"取得进展；完成","example":"The business profited steadily through the year.","exampleCN":"这家企业在一年中稳步获利。"},{"word":"profit","structure":"Latin profectus, through Old French","meaning":"gain from a transaction","meaningCN":"交易带来的收益","example":"The year's profit paid for the new roof.","exampleCN":"这一年的收益付了新屋顶的钱。"},{"word":"profitable","structure":"profit + -able (capable of)","meaning":"able to yield gain","meaningCN":"有利可图的","example":"The route became profitable once freight returned.","exampleCN":"货运恢复之后，这条线路变得有利可图。"},{"word":"profitability","structure":"profitable + -ity (state of)","meaning":"the state of yielding gain","meaningCN":"盈利能力","example":"Profitability improved after the merger.","exampleCN":"合并之后盈利能力有所提高。"},{"word":"margo","structure":"margo, -inis (f., third declension; Latin)","meaning":"edge, border, brink","meaningCN":"边缘；边界；崖沿","example":"The noun gave English its page edge.","exampleCN":"这个名词给英语带来了「页边」。"},{"word":"margin","structure":"Latin margo, through Old French marge","meaning":"an edge; a difference or allowance","meaningCN":"边缘；差额；余量","example":"The margin between cost and price widened.","exampleCN":"成本与价格之间的差额扩大了。"},{"word":"marginal","structure":"margin + -al (relating to)","meaning":"at the edge; barely sufficient","meaningCN":"边缘的；勉强够的","example":"The second factory made only a marginal gain.","exampleCN":"第二家工厂只带来勉强可观的收益。"}],"latinEntries":[{"word":"proficere","structure":"proficere, -feci, -fectum (third conjugation; Latin)","meaning":"to make progress, accomplish","meaningCN":"取得进展；完成"},{"word":"profectus","structure":"profectus, -us (m., fourth declension; Latin)","meaning":"progress, gain","meaningCN":"进展；收益"},{"word":"margo","structure":"margo, -inis (f., third declension; Latin)","meaning":"edge, border","meaningCN":"边缘；边界"}]}},{"word":"bargaining","ipa_uk":"/ˈbɑːɡənɪŋ/","ipa_us":"/ˈbɑːrɡənɪŋ/","definition_zh":"讨价还价；谈判；（劳资）集体谈判","definition_en":"the activity of negotiating over a price or the terms of an agreement","core_image":"集市摊位两侧站着两个人，一人伸出一根手指报价，另一人摇头，价格在手指与摇头之间来回移动","scene":"集市上，摊主与顾客隔着一筐菜，一个伸出手指报价，另一个摇头。The two sides spent the morning bargaining over the price of the grain.","sceneCN":"这里这个词指「买卖双方就价格反复商量的过程」（第 1 个义项：市场里的讨价还价）；句意为双方花了一上午就谷物的价格讨价还价。图中可辨识物件：菜筐、伸出的手指、摇头的动作、摊位。","pos":[{"tag":"n.","zh":"讨价还价；谈判（不可数；也可作定语，如谈判权）"}],"collocations":[{"phrase":"collective bargaining","zh":"劳资集体谈判"},{"phrase":"bargaining power","zh":"议价能力；谈判实力"},{"phrase":"bargaining chip","zh":"谈判筹码"},{"phrase":"bargaining position","zh":"谈判地位"},{"phrase":"plea bargaining","zh":"认罪协商"},{"phrase":"hard bargaining","zh":"强硬谈判"}],"forms":[{"label":"不可数名词","form":"bargaining"},{"label":"动词原形","form":"bargain"},{"label":"动词三单","form":"bargains"},{"label":"动词过去式","form":"bargained"},{"label":"动词现在分词","form":"bargaining"},{"label":"名词（交易；便宜货）","form":"bargain"}],"derivatives":[{"word":"bargain","pos":"n./v.","zh":"便宜货；交易；讨价还价"},{"word":"bargainer","pos":"n.","zh":"讨价还价的人；谈判者"},{"word":"bargainable","pos":"adj.","zh":"可议价的"},{"word":"collective bargaining","pos":"n.","zh":"集体谈判（固定说法）"}],"senses":[{"no":"01","title":"Haggling over a price in a market","titleCN":"在市场上就价格来回商量","definition":"the back-and-forth talk between buyer and seller before a price is agreed","definitionCN":"买卖双方在价格谈定之前的反复商议","example":"Bargaining is expected in the old market, so the first price is only a start.","exampleCN":"老市场里习惯讨价还价，所以第一个报价只是起点。","why":"The word first named haggling, and this face-to-face exchange remains its most concrete sense.","whyCN":"这个词最初就指讨价还价，这种面对面交换仍是它最具体的义项。"},{"no":"02","title":"Collective bargaining between employer and union","titleCN":"雇主与工会之间的集体谈判","definition":"negotiation between a employer and a union over pay and working conditions for a whole workforce","definitionCN":"雇主与工会就全体员工的薪酬与工作条件进行的谈判","example":"Collective bargaining produced a new wage scale for the whole plant.","exampleCN":"集体谈判为整个工厂谈出了新的工资等级。","why":"One voice bargaining for many is the same haggling scaled up to an institution.","whyCN":"一个声音替许多人谈价，就是同一种讨价还价放大成制度。"},{"no":"03","title":"Bargaining power in a negotiation","titleCN":"谈判中的议价能力","definition":"the strength one side has because the other side needs what it holds","definitionCN":"一方因对方需要自己手中的东西而拥有的力量","example":"Scarce water gave the farmers unusual bargaining power.","exampleCN":"稀缺的水源让农民拥有了不寻常的议价能力。","why":"Power in a haggle is the ability to walk away, so the abstract noun follows from the market scene.","whyCN":"讨价还价中的力量就是转身走开的能力，抽象名词由此从市场场景延伸出来。"},{"no":"04","title":"A bargaining chip offered in a trade","titleCN":"在交换中拿出的谈判筹码","definition":"something held back or offered in order to obtain a better term","definitionCN":"为了换取更好条件而保留或拿出的一样东西","example":"The port became a bargaining chip in the treaty talks.","exampleCN":"这座港口成了条约谈判中的筹码。","why":"A chip is a token placed on the table, and bargaining turns it into leverage.","whyCN":"筹码是摆到桌面上的一个代币，谈判使它变成杠杆。"},{"no":"05","title":"Plea bargaining in a criminal case","titleCN":"刑事案件中的认罪协商","definition":"an agreement in which a defendant pleads guilty in exchange for a lighter charge or sentence","definitionCN":"被告认罪以换取较轻指控或较轻刑罚的协议","example":"Plea bargaining shortened the trial but left the family uneasy.","exampleCN":"认罪协商缩短了审理，却让家属心里不安。","why":"The courtroom borrows the market word because a charge is being exchanged for a plea.","whyCN":"法庭借用了市场里的词，因为指控正被用来交换认罪。"},{"no":"06","title":"A bargaining position held in advance","titleCN":"事先摆好的谈判立场","definition":"the stated terms a side enters a negotiation with, before any concession","definitionCN":"一方在作出任何让步之前就带着进入谈判的条件","example":"Each side opened from a strong bargaining position.","exampleCN":"双方都从一个强势的谈判立场开局。","why":"Position is where you stand before the haggling begins, and the word extends to that stance.","whyCN":"立场是讨价还价开始之前你站的位置，这个词就延伸到那种姿态。"},{"no":"07","title":"Hard bargaining as a style","titleCN":"作为一种风格的强硬谈判","definition":"a manner of negotiating that makes few concessions and presses for the best terms","definitionCN":"很少让步、力争最优条件的谈判方式","example":"After weeks of hard bargaining the supplier cut its price.","exampleCN":"经过数周强硬谈判，供货方降低了价格。","why":"The activity can name a temperament, not just a meeting.","whyCN":"这个活动词也可以指一种脾性，而不只是一场会谈。"},{"no":"08","title":"Negotiation as a general process","titleCN":"作为一般过程的谈判","definition":"any extended discussion aimed at an agreement, not necessarily about money","definitionCN":"任何以达成协议为目标的长谈，未必涉及金钱","example":"The months of bargaining ended with a shared schedule.","exampleCN":"数月的谈判以一份共同时间表收尾。","why":"Once the price element fades, the word covers any give-and-take toward agreement.","whyCN":"当价格因素淡去，这个词就覆盖任何为达成一致的互让过程。"}],"etymology":{"intro":{"en":"Bargaining is the noun of the verb bargain, which came through Old French from a word for haggling whose deeper origin is disputed; the labour sense is nineteenth-century.","cn":"bargaining 是动词 bargain 的名词形式，经古法语来自一个表示「讨价还价」的词，其更深来源有争议；劳资谈判义出现于十九世纪。"},"items":[{"era":"OLD FRENCH BARGAIGNIER","en":"Bargaignier meant to haggle or to trade, and it supplied English with the verb bargain.","cn":"bargaignier 意为「讨价还价、做买卖」，它给英语提供了动词 bargain。"},{"era":"MEDIEVAL LATIN BARCANIARE","en":"A Latin form barcaniare is recorded in medieval sources with a trading sense, but its relation to the French verb is source uncertain.","cn":"中世纪文献中记录了一个表示买卖的拉丁语形式 barcaniare，但它与法语动词的关系属于来源不确定。"},{"era":"FRANKISH BORGAN","en":"The often cited Frankish word for to borrow or to pledge is a reconstructed form, not a recorded one, and any exact sense given for it is a reconstruction.","cn":"常被引用的法兰克语中表示「借、抵押」的词是重构形式，而非有记录的形式，为它给出的确切含义都属重构。"},{"era":"ENGLISH BARGAIN","en":"By the fourteenth century bargain was both a noun for an agreement and a verb for haggling.","cn":"到十四世纪，bargain 既是表示「协议」的名词，也是表示「讨价还价」的动词。"},{"era":"CHEAP PURCHASE","en":"From the eighteenth century a bargain also named an item bought cheaply, a sense that grew out of a good agreement.","cn":"从十八世纪起，bargain 也指便宜买到的物品，这一义项由「划算的协议」发展而来。"},{"era":"LABOUR NEGOTIATION","en":"Collective bargaining became a fixed phrase in the nineteenth century as unions negotiated for whole workplaces.","cn":"随着工会为整个工作场所谈条件，collective bargaining 在十九世纪成为固定说法。"}]},"similar":{"note":{"en":"The first group holds forms of the same word plus one accidental look-alike; the second holds other names for the same kind of talk.","cn":"第一组是同一个词的各种形式，外加一个偶然形近的词；第二组是同类谈话的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bargain","ipa":"/ˈbɑːɡən/","tag":"verb and noun base","definition":"To haggle, or the agreement and the cheap item that result; the noun in the entry is built on it.","definitionCN":"讨价还价，或由此得来的协议与便宜货；本词条的名词就建立在它之上。"},{"word":"bargainer","ipa":"/ˈbɑːɡənə/","tag":"the person","definition":"A person who haggles or negotiates; it names the actor rather than the activity.","definitionCN":"讨价还价或谈判的人；它指行动者，而不指活动。"},{"word":"bargaining","ipa":"/ˈbɑːɡənɪŋ/","tag":"the activity","definition":"The activity itself, which can name a market exchange, a labour talk or a courtroom deal.","definitionCN":"活动本身，可指市场交换、劳资谈判或法庭上的交易。"},{"word":"barge","ipa":"/bɑːdʒ/","tag":"different origin","definition":"A flat-bottomed boat; it looks close in spelling but comes from a different source and has nothing to do with haggling.","definitionCN":"一种平底船；拼写相近，但来源不同，与讨价还价无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"haggling","ipa":"/ˈhæɡlɪŋ/","tag":"the market version","definition":"Argument over a price, usually in a small transaction; narrower and more informal than bargaining.","definitionCN":"为价格争论，通常见于小额交易；比 bargaining 更窄、更口语。"},{"word":"negotiation","ipa":"/nɪˌɡəʊʃiˈeɪʃn/","tag":"the formal version","definition":"Formal discussion aimed at an agreement; it covers treaties and contracts better than market haggling.","definitionCN":"以达成协议为目标的正式商谈；比市场讨价更适合指条约与合同。"},{"word":"dealing","ipa":"/ˈdiːlɪŋ/","tag":"the transaction side","definition":"The business of buying and selling, or a way of conducting oneself with others.","definitionCN":"买卖业务，或与他人打交道的方式。"},{"word":"mediation","ipa":"/ˌmiːdiˈeɪʃn/","tag":"with a third party","definition":"Negotiation helped by a neutral outsider; bargaining needs no outsider.","definitionCN":"由中立第三方协助的谈判；讨价还价不需要外人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Bargain plus ing: the act of haggling, with the noun ending naming the activity.","cn":"「讨价还价」加名词后缀：这个后缀把动作变成活动本身。"},{"en":"The family runs bargain, bargainer, bargaining and bargainable.","cn":"同族词包括 bargain、bargainer、bargaining 与 bargainable。"},{"en":"Fixed phrases mark the workplace and the courtroom: collective bargaining, bargaining chip, plea bargaining.","cn":"固定搭配标出职场与法庭两面：集体谈判、谈判筹码、认罪协商。"},{"en":"Bargaining power is the ability to walk away from the stall.","cn":"议价能力就是能从摊位前转身走开的本事。"},{"en":"A price that moves back and forth across a table is the picture behind every abstract use.","cn":"价格在桌子两边来回移动，是所有抽象用法背后的画面。"}],"abstract":[{"en":"Picture a rope pulled from both ends, each side testing how much the other will give.","cn":"想象一根绳子被两端拉扯，每一边都在试探对方肯让多少。"},{"en":"Picture a scale that never settles because a hand keeps adding and removing weights.","cn":"想象一台天平始终停不下来，因为有一只手不断加减砝码。"},{"en":"Picture two doors facing each other, each opening only when the other closes a little.","cn":"想象两扇相对的门，只有一扇稍微关上，另一扇才会打开。"}]},"examples":[{"en":"Bargaining over a taxi fare is common at the station.","cn":"在车站为出租车车费讨价还价很常见。"},{"en":"The union entered bargaining with a clear list of demands.","cn":"工会带着一份明确的要求清单进入谈判。"},{"en":"Years of hard bargaining finally produced a shared water plan.","cn":"多年强硬谈判终于促成了一项共同的水资源方案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「把（bar）价格谈下来」——买卖双方反复商量、来回压价的过程 → 讨价还价、谈判","word":"bargaining"},"root":"经古法语 bargaignier「讨价还价、做买卖」进入英语；其更深来源有争议，常被引用的法兰克语形式属重构形式，中世纪拉丁语中相关形式的关联亦属来源不确定。","sensesIntro":{"en":"Eight senses follow one table talk: haggling in a market, a union facing an employer, the power behind it, a chip on the table, a courtroom deal, a starting stance, a hard style and negotiation in general.","cn":"八个义项沿同一场桌边谈话展开：市场上的讨价、工会面对雇主、背后的力量、桌上的筹码、法庭上的交易、开局立场、强硬风格，以及一般意义上的谈判。"},"semanticMap":{"core":{"en":"CORE IMAGE: two people across a stall, one raising a finger and the other shaking a head.","cn":"核心意象：摊位两侧的两个人，一人伸出一根手指，另一人摇头。"},"chain":["PRICE GOES BACK AND FORTH","TWO SIDES, ONE TABLE","STRENGTH TO WALK AWAY","SOMETHING ON THE TABLE","A FORMAL TALK","ANY GIVE AND TAKE"],"branches":[{"senses":"01 · 08","en":"ONE TABLE, TWO SCALES: a stall haggling and a long negotiation are the same exchange at different sizes.","cn":"一张桌子，两种规模：摊位前的讨价与漫长的谈判是同一交换的不同大小。"},{"senses":"02","en":"MANY VOICES: a union bargains for a whole workforce, which is haggling made institutional.","cn":"许多声音：工会替整个劳动群体谈价，就是把讨价还价制度化。"},{"senses":"03 · 06","en":"WHERE YOU STAND: power and position are the same advantage seen as force and as stance.","cn":"你站在哪里：力量与立场是同一种优势，一个看成力气，一个看成姿态。"},{"senses":"04 · 05","en":"WHAT IS TRADED: a chip on the table and a plea in court are both goods exchanged for terms.","cn":"拿来交换的东西：桌上的筹码与法庭上的认罪，都是用一样东西换条件。"},{"senses":"07","en":"A HARD STYLE: the activity becomes a manner of pressing rather than conceding.","cn":"强硬的风格：这个活动变成一种施压而不让步的方式。"}]},"affixes":{"intro":{"en":"The noun is a verb of haggling with the native suffix that turns an action into an activity, so the parts read as the doing of a deal.","cn":"这个名词是一个表示「讨价还价」的动词加上本族后缀构成，该后缀把动作变成活动，因此各部分读作「做交易这件事」。"},"latinIntro":{"en":"No Latin root is established for this word; the recorded Latin form is doubtful, so the Latin entries stay empty.","cn":"这个词没有已确立的拉丁词根；有记录的相关拉丁形式本身可疑，因此拉丁语词形一栏留空。"},"items":[{"word":"bargain","structure":"Old French bargaignier (to haggle, to trade)","meaning":"to haggle; an agreement","meaningCN":"讨价还价；协议","example":"They bargain over every crate of fruit.","exampleCN":"他们为每一箱水果讨价还价。"},{"word":"-ing","structure":"-ing (native suffix forming a verbal noun)","meaning":"the activity of doing something","meaningCN":"做某事这一活动","example":"The suffix turns the verb into the activity itself.","exampleCN":"这个后缀把动词变成活动本身。"},{"word":"bargaining","structure":"bargain + -ing","meaning":"the activity of negotiating","meaningCN":"谈判；讨价还价","example":"Bargaining continued until midnight.","exampleCN":"谈判一直持续到午夜。"},{"word":"bargainer","structure":"bargain + -er (one who does)","meaning":"a person who haggles","meaningCN":"讨价还价的人","example":"A patient bargainer rarely pays the first price.","exampleCN":"有耐心的讨价者很少按第一个报价付钱。"},{"word":"bargainable","structure":"bargain + -able (fit to be)","meaning":"open to negotiation","meaningCN":"可议价的","example":"Only the larger items are bargainable.","exampleCN":"只有较大的商品可以议价。"},{"word":"collective","structure":"Latin collectivus, from colligere (to gather)","meaning":"shared by a group","meaningCN":"集体共享的","example":"A collective agreement binds every worker in the shop.","exampleCN":"集体协议约束车间里的每个工人。"},{"word":"plea","structure":"Old French plait (a plea), from Latin placitum","meaning":"an appeal or a formal answer","meaningCN":"请求；答辩","example":"The plea changed the shape of the trial.","exampleCN":"这次答辩改变了审理的走向。"},{"word":"chip","structure":"Old English cipp (a piece cut off)","meaning":"a small token or fragment","meaningCN":"小片；筹码","example":"The offer was a chip on the table.","exampleCN":"那个提议是摆上桌面的一枚筹码。"},{"word":"position","structure":"Latin positio, from ponere (to place)","meaning":"a place where something stands","meaningCN":"位置；立场","example":"A strong position shortens the talk.","exampleCN":"强势的立场会缩短谈话。"}],"latinEntries":[]}},{"word":"bargain","ipa_uk":"/ˈbɑːɡən/","ipa_us":"/ˈbɑːrɡən/","definition_zh":"便宜货；划算的交易；协议；讨价还价","definition_en":"something bought for less than its usual price, an agreement between two sides, or to negotiate a price","core_image":"摊位前挂着一块手写的牌子，顾客把几枚硬币在手心里数了又数，摊主点头把货递过去","scene":"摊位前挂着写有今日特价的牌子，顾客把几枚硬币在手心里数了又数。At the market she found a bargain: two kilos of apples for the price of one.","sceneCN":"这里这个词指「比平常价格便宜、很划算的买卖或商品」（第 1 个义项：便宜买到的物品）；句意为她在市场上捡了个便宜，买两公斤苹果只付一公斤的价钱。图中可辨识物件：手写牌子、硬币、苹果堆、摊位。","pos":[{"tag":"n.","zh":"便宜货；划算的交易；（正式的）协议"},{"tag":"v.","zh":"讨价还价；谈条件"}],"collocations":[{"phrase":"a real bargain","zh":"真正的便宜货"},{"phrase":"bargain price","zh":"特价；廉价"},{"phrase":"bargain hunter","zh":"淘便宜货的人"},{"phrase":"strike a bargain","zh":"达成协议"},{"phrase":"into the bargain","zh":"此外；而且还"},{"phrase":"bargain basement","zh":"廉价商品部"}],"forms":[{"label":"复数","form":"bargains"},{"label":"动词三单","form":"bargains"},{"label":"动词过去式","form":"bargained"},{"label":"动词过去分词","form":"bargained"},{"label":"动词现在分词","form":"bargaining"},{"label":"名词（谈判）","form":"bargaining"}],"derivatives":[{"word":"bargaining","pos":"n.","zh":"谈判；讨价还价"},{"word":"bargainer","pos":"n.","zh":"讨价还价的人；谈判者"},{"word":"bargainable","pos":"adj.","zh":"可议价的"},{"word":"bargain basement","pos":"n.","zh":"廉价商品部（固定说法）"},{"word":"bargain hunter","pos":"n.","zh":"淘便宜货的人（固定说法）"}],"senses":[{"no":"01","title":"Something bought cheaply","titleCN":"便宜买到的物品","definition":"an item obtained for noticeably less than its usual price","definitionCN":"以明显低于平常价格的价钱得到的物品","example":"The coat was a bargain at half its original price.","exampleCN":"这件外套只卖原价的一半，真是便宜。","why":"A good agreement leaves one side with a cheap item, and the item took the name of the agreement.","whyCN":"一笔划算的协议会让一方得到便宜货，于是物品沿用了协议的名字。"},{"no":"02","title":"An agreement between two sides","titleCN":"双方达成的协议","definition":"a mutual arrangement in which each side promises something","definitionCN":"双方各自作出承诺的相互安排","example":"The two firms struck a bargain that split the route between them.","exampleCN":"两家公司达成协议，把这条线路一分为二。","why":"This is the older sense: a bargain is first what two parties settle, before it is a cheap object.","whyCN":"这是更早的义项：bargain 首先是双方谈定的事，其次才是便宜的物件。"},{"no":"03","title":"To negotiate a price","titleCN":"就价格进行商谈","definition":"to discuss a price until both sides accept it","definitionCN":"反复商议价格，直到双方都接受","example":"Tourists who bargain politely often pay less.","exampleCN":"礼貌地讨价还价的游客常常付得更少。","why":"The verb names the act that produces both the agreement and the cheap item.","whyCN":"动词所指的动作，正是既产生协议又产生便宜货的那件事。"},{"no":"04","title":"A reduced price offered as a special","titleCN":"作为特价给出的低价","definition":"the low figure itself, advertised to draw buyers into a shop","definitionCN":"被宣传出来以吸引顾客进店的低数字本身","example":"The bargain price lasted only through the weekend.","exampleCN":"这个特价只持续到周末。","why":"The cheap item can be reduced to its price, and the price becomes the attraction.","whyCN":"便宜的物品可以再缩成它的价格，而价格又成了吸引人的东西。"},{"no":"05","title":"A person who hunts for cheap goods","titleCN":"专门淘便宜货的人","definition":"a shopper who searches out reduced goods rather than buying at the first price seen","definitionCN":"专门寻找降价商品、不按第一眼看到的价格购买的顾客","example":"The January sales bring every bargain hunter into town.","exampleCN":"一月大促销把每个淘便宜货的人都引到城里。","why":"The word for the thing also labels the person who chases it.","whyCN":"指物的词也用来标记追逐它的人。"},{"no":"06","title":"Something added on top of the deal","titleCN":"在交易之外额外附带的东西","definition":"an extra item or advantage included without a further payment","definitionCN":"不用再付钱就一并包含的额外物品或好处","example":"The bike came with a pump into the bargain.","exampleCN":"这辆自行车还额外附带一个打气筒。","why":"If the bargain is good, extras are thrown in, and the fixed phrase names those extras.","whyCN":"如果交易划算，就会附带额外的东西，这个固定说法正指那些附带物。"},{"no":"07","title":"The cheap section of a shop","titleCN":"商店里的廉价商品区","definition":"a part of a store where goods are sold well below their usual price","definitionCN":"商店中以远低于平常价格出售商品的区域","example":"She found the lamp in the bargain basement.","exampleCN":"她在那间廉价商品部找到了这盏灯。","why":"A place can be named after the kind of price it holds.","whyCN":"一个地方可以按它所售的价格类型来命名。"},{"no":"08","title":"A deal as an exchange of promises","titleCN":"作为相互承诺的正式交易","definition":"a binding arrangement in law or politics, each side giving something for something","definitionCN":"法律或政治上有约束力的安排，各方以某物换某物","example":"The treaty was a bargain between security and access.","exampleCN":"这项条约是安全与准入之间的一笔交易。","why":"Stripped of the market, the word still means a balance of promises, which is its oldest legal use.","whyCN":"去掉市场场景之后，这个词仍指承诺之间的平衡，这是它最早的法律用法。"}],"etymology":{"intro":{"en":"The word entered English through Old French as a noun for an agreement, then a verb for haggling; the sense of a cheap purchase is eighteenth-century, and the deeper origin remains disputed.","cn":"这个词经古法语进入英语，先作表示「协议」的名词，再作表示「讨价还价」的动词；「便宜货」义出现于十八世纪，其更深来源仍有争议。"},"items":[{"era":"OLD FRENCH BARGAIGNIER","en":"Bargaignier meant to haggle or trade, and its noun form named the resulting agreement.","cn":"bargaignier 意为「讨价还价、做买卖」，其名词形式指由此达成的协议。"},{"era":"MEDIEVAL LATIN BARCANIARE","en":"A Latin verb of trading is recorded, but whether the French word comes from it is source uncertain.","cn":"文献中记录了一个表示买卖的拉丁语动词，但法语词是否出自它属于来源不确定。"},{"era":"FRANKISH BORGAN","en":"The frequently cited Germanic source meaning to borrow or pledge is a reconstructed form, so its exact shape and sense are reconstructions.","cn":"常被引用的日耳曼语来源表示「借、抵押」，它是重构形式，因此其确切形态与含义都属重构。"},{"era":"ENGLISH AGREEMENT","en":"In the fourteenth century a bargain was chiefly an agreement or a contract between two parties.","cn":"在十四世纪，bargain 主要指双方之间的协议或合同。"},{"era":"ENGLISH HAGGLING","en":"The verb sense of discussing a price developed alongside the noun, and both survive today.","cn":"表示商议价格的动词义与名词义并肩发展，两者都保留至今。"},{"era":"CHEAP PURCHASE","en":"By the eighteenth century a bargain could name the cheap item itself, the sense that now dominates everyday speech.","cn":"到十八世纪，bargain 可指便宜的物品本身，这一义项如今在日常口语中占主导。"}]},"similar":{"note":{"en":"The first group holds the word, its relatives and one accidental look-alike; the second holds other names for a deal or a cheap buy.","cn":"第一组是这个单词、它的同族，以及一个偶然形近的词；第二组是交易或便宜货的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bargaining","ipa":"/ˈbɑːɡənɪŋ/","tag":"the activity","definition":"The process of haggling; it names the talk, while bargain names the result or the cheap item.","definitionCN":"讨价还价的过程；它指谈话本身，而 bargain 指结果或便宜货。"},{"word":"bargainer","ipa":"/ˈbɑːɡənə/","tag":"the person","definition":"One who haggles; it is the doer, not the deal.","definitionCN":"讨价还价的人；它指行动者，而非交易。"},{"word":"barge","ipa":"/bɑːdʒ/","tag":"unrelated look-alike","definition":"A river boat; the spelling is close but the origin is different and no trading sense exists.","definitionCN":"一种河船；拼写相近，但来源不同，也没有交易义。"},{"word":"bazaar","ipa":"/bəˈzɑː/","tag":"unrelated look-alike","definition":"A market of stalls, from Persian; it names the place where bargains happen, not the deal.","definitionCN":"由摊位构成的市场，来自波斯语；它指发生交易的场所，不指交易。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deal","ipa":"/diːl/","tag":"the agreement","definition":"An arrangement between two sides; it matches the agreement sense but not the cheap item.","definitionCN":"双方之间的安排；它对应协议义，但不对应便宜货义。"},{"word":"discount","ipa":"/ˈdɪskaʊnt/","tag":"the reduction","definition":"An amount taken off a price; a bargain is the whole cheap purchase, not the amount removed.","definitionCN":"从价格中减去的金额；bargain 指整笔便宜买卖，而非减去的数额。"},{"word":"steal","ipa":"/stiːl/","tag":"very cheap, informal","definition":"Something remarkably cheap, used informally; stronger and more casual than bargain.","definitionCN":"极便宜的东西，属口语用法；比 bargain 语气更强、更随意。"},{"word":"purchase","ipa":"/ˈpɜːtʃəs/","tag":"the buying, neutral","definition":"The act or object of buying, with no suggestion of a low price.","definitionCN":"购买的行为或买到的物品，不含低价的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"One word holds both the agreement and the cheap item, because a good agreement produces the cheap item.","cn":"同一个词既指协议又指便宜货，因为划算的协议产生了便宜货。"},{"en":"The family runs bargain, bargaining, bargainer and bargainable.","cn":"同族词包括 bargain、bargaining、bargainer 与 bargainable。"},{"en":"Fixed phrases mark the deal and the shop: strike a bargain, into the bargain, bargain basement.","cn":"固定搭配标出交易与商店两面：达成协议、此外、廉价商品部。"},{"en":"A bargain hunter chases the item, a bargainer argues over it.","cn":"淘便宜货的人追逐那件物品，讨价还价的人为它争论。"},{"en":"The oldest sense is the agreement; the newest everyday sense is the cheap thing.","cn":"最早的义项是协议，最新的日常义项是便宜的东西。"}],"abstract":[{"en":"Picture a handshake that leaves one palm heavier with goods and the other lighter with coins.","cn":"想象一次握手之后，一只手掌多了货物，另一只手掌少了硬币。"},{"en":"Picture a price tag that folds in half when two people nod at each other.","cn":"想象两个人彼此点头时，价签自己对折成一半。"},{"en":"Picture a promise and a purchase standing back to back, sharing one shadow.","cn":"想象一个承诺与一笔购买背靠背站着，共用同一个影子。"}]},"examples":[{"en":"At that stall, a bargain is always possible if you buy three.","cn":"在那个摊位上，只要买三件就总能谈到便宜价。"},{"en":"They struck a bargain that ended the long dispute.","cn":"他们达成了一项协议，结束了漫长的争执。"},{"en":"The used desk was a bargain, even after the repair.","cn":"这张旧书桌就算加上修理费也很划算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「把（bar）价谈低」——谈成一笔划算的买卖，便宜到手的货 → 便宜货、协议、讨价还价","word":"bargain"},"root":"经古法语 bargaignier「讨价还价、做买卖」进入英语，先指协议，后指便宜货；更深来源有争议，常被引用的日耳曼语形式属重构形式。","sensesIntro":{"en":"Eight senses follow one good agreement: the cheap item it produces, the agreement itself, the haggling that precedes it, the special price, the shopper who hunts it, the extras thrown in, the cheap aisle and the legal balance of promises.","cn":"八个义项沿一笔划算的协议展开：由此得到的便宜货、协议本身、谈成之前的讨价、特价、专门淘货的人、额外附带的东西、廉价商品区，以及法律上承诺的平衡。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand-written sign over a stall and a buyer counting coins in one palm.","cn":"核心意象：摊位上方一块手写牌子，买家在一只手掌里数硬币。"},"chain":["TWO SIDES AGREE","A PRICE SETTLES","THE ITEM COMES CHEAP","THE PRICE IS ADVERTISED","EXTRAS THROWN IN","PROMISES BALANCED"],"branches":[{"senses":"01 · 04","en":"THE CHEAP RESULT: the item and the special figure are the same gain seen as goods and as price.","cn":"便宜的结果：物品与特价是同一份好处，一个看成货物，一个看成价格。"},{"senses":"02 · 08","en":"THE AGREEMENT: a market deal and a treaty are the same balance of promises at different scales.","cn":"协议：市场交易与条约是同一份承诺平衡的不同规模。"},{"senses":"03","en":"THE TALK: the verb is the activity that produces everything else.","cn":"谈话：动词所指的活动产生其余一切。"},{"senses":"05 · 07","en":"THE CHASE AND THE AISLE: a person and a place are named after the cheap thing they pursue and hold.","cn":"追逐与货区：一个人和一个地方都因他们所追、所放的便宜货而得名。"},{"senses":"06","en":"THE EXTRA: a good deal spills over into something included without further payment.","cn":"额外之物：划算的交易溢出为不用再付钱就包含的东西。"}]},"affixes":{"intro":{"en":"The word is a single French loan whose ending is not a living English suffix, so its parts are best read as the borrowed stem plus a noun or verb use.","cn":"这个词是一个整体借入的法语词，词尾并不是能产的英语后缀，因此各部分宜读作「借入的词干」加名词或动词用法。"},"latinIntro":{"en":"No Latin root is securely established; the recorded Latin trading verb is doubtful, so the Latin entries stay empty.","cn":"没有可靠的拉丁词根；文献中相关的拉丁语买卖动词本身可疑，因此拉丁语词形一栏留空。"},"items":[{"word":"bargain","structure":"Old French bargaignier (to haggle, trade)","meaning":"an agreement; a cheap buy","meaningCN":"协议；便宜货","example":"The bargain was settled with a nod.","exampleCN":"这笔交易一个点头就定了。"},{"word":"bargaining","structure":"bargain + -ing (verbal noun)","meaning":"the activity of negotiating","meaningCN":"谈判活动","example":"Bargaining took most of the afternoon.","exampleCN":"谈判占去了大半个下午。"},{"word":"bargainer","structure":"bargain + -er (agent)","meaning":"a person who haggles","meaningCN":"讨价还价者","example":"A skilled bargainer knows when to leave.","exampleCN":"老练的讨价者知道何时离开。"},{"word":"bargainable","structure":"bargain + -able (capable of)","meaning":"open to a deal","meaningCN":"可议价的","example":"The larger pieces are bargainable.","exampleCN":"较大的物件可以议价。"},{"word":"strike","structure":"Old English strican (to stroke, to go)","meaning":"to conclude an agreement","meaningCN":"达成（协议）","example":"They struck a deal before nightfall.","exampleCN":"他们在天黑前达成了交易。"},{"word":"basement","structure":"base + -ment (place)","meaning":"the lower floor of a building","meaningCN":"地下室；底层","example":"The cheap stock sits in the basement.","exampleCN":"廉价存货放在底层。"},{"word":"hunter","structure":"hunt + -er (agent)","meaning":"one who searches","meaningCN":"搜寻者","example":"A bargain hunter checks every aisle.","exampleCN":"淘便宜货的人会走遍每条货道。"},{"word":"into","structure":"Old English into (in + to)","meaning":"in addition, in the phrase into the bargain","meaningCN":"此外（用于固定说法中）","example":"The bag came into the bargain.","exampleCN":"那只袋子是额外附带的。"}],"latinEntries":[]}},{"word":"contractual","ipa_uk":"/kənˈtræktʃuəl/","ipa_us":"/kənˈtræktʃuəl/","definition_zh":"合同的；契约上的；由合同规定的","definition_en":"relating to a contract, or required by the terms of one","core_image":"会议桌上摊开一份盖了骑缝章的合同，每一条条款旁都有供签字的小方框","scene":"会议室桌上摊开一份合同，双方在每一条条款旁的小方框里签下名字。A missed delivery date created a contractual dispute.","sceneCN":"这里这个词指「与合同有关的」（第 1 个义项：属于合同范畴的）；句意为一次延误的交货引发了合同纠纷。图中可辨识物件：合同纸页、骑缝章、条款、签字方框。","pos":[{"tag":"adj.","zh":"合同的；契约上的；合同规定的"}],"collocations":[{"phrase":"contractual obligation","zh":"合同义务"},{"phrase":"contractual terms","zh":"合同条款"},{"phrase":"contractual relationship","zh":"合同关系"},{"phrase":"contractual liability","zh":"合同责任"},{"phrase":"contractual rights","zh":"合同权利"},{"phrase":"contractual dispute","zh":"合同纠纷"}],"forms":[{"label":"原级","form":"contractual"},{"label":"比较级","form":"more contractual"},{"label":"最高级","form":"most contractual"},{"label":"副词","form":"contractually"},{"label":"名词（合同）","form":"contract"},{"label":"名词（立约人）","form":"contractor"},{"label":"名词（收缩）","form":"contraction"}],"derivatives":[{"word":"contract","pos":"n./v.","zh":"合同；订立合同；收缩"},{"word":"contractually","pos":"adv.","zh":"按合同地；在合同上"},{"word":"contractor","pos":"n.","zh":"承包商；立约人"},{"word":"contraction","pos":"n.","zh":"收缩；缩略形式"},{"word":"contractualism","pos":"n.","zh":"契约主义"}],"senses":[{"no":"01","title":"Relating to a contract in general","titleCN":"泛指与合同有关的","definition":"belonging to the field of contracts rather than to any single agreement","definitionCN":"属于合同这一领域，而非某一具体协议","example":"The lawyer explained the contractual side of the sale.","exampleCN":"律师解释了这笔买卖在合同层面的问题。","why":"The adjective simply attaches the noun to its field, the broadest of its uses.","whyCN":"这个形容词只是把「合同」这一名词挂到它的领域上，是最宽的用法。"},{"no":"02","title":"Required by the terms of a contract","titleCN":"合同条款所要求的","definition":"owed because a signed agreement says so, not because of a general duty","definitionCN":"因签署的协议如此规定而应当履行的，而非因一般义务","example":"Payment within thirty days is a contractual obligation.","exampleCN":"三十天内付款是一项合同义务。","why":"Here the adjective marks the source of a duty: the duty exists because the contract exists.","whyCN":"这里的形容词标出义务的来源：义务存在，是因为合同存在。"},{"no":"03","title":"Agreed in the written terms","titleCN":"写进条款并商定的","definition":"fixed in the clauses of an agreement rather than left to custom or law","definitionCN":"固定在协议条款里，而非留给习惯或法律","example":"The contractual terms barred a second supplier.","exampleCN":"合同条款禁止另找第二家供货商。","why":"Terms that are written down turn a general arrangement into clauses with edges.","whyCN":"被写下来的条款把一般安排变成有边界的条文。"},{"no":"04","title":"Employed on a fixed-term agreement","titleCN":"按定期合同受雇的","definition":"working under a limited agreement rather than on a permanent footing","definitionCN":"按有期限的协议工作，而非长期编制","example":"Contractual staff do not receive the same pension.","exampleCN":"合同制员工拿不到同样的养老金。","why":"A person can be described by the kind of agreement that holds them, not only a duty.","whyCN":"一个人也可以用约束他的那种协议来描述，而不只是义务。"},{"no":"05","title":"Liability arising from a broken agreement","titleCN":"因违反协议而产生的责任","definition":"responsibility in law for failing to perform what was promised","definitionCN":"在法律上因未履行承诺而承担的责任","example":"The court limited the contractual liability to the value of the goods.","exampleCN":"法院把合同责任限定在货物的价值之内。","why":"When a promise fails, the agreement turns into a source of liability rather than of rights.","whyCN":"当承诺落空，协议就从权利的来源变成责任的来源。"},{"no":"06","title":"A relationship governed by an agreement","titleCN":"由协议约束的关系","definition":"a continuing connection between parties whose conduct is set by their contract","definitionCN":"各方行为由合同设定的持续关系","example":"After the merger the two firms kept a contractual relationship.","exampleCN":"合并之后，两家公司仍保持合同关系。","why":"The adjective can describe a whole relationship, not just one clause inside it.","whyCN":"这个形容词可以描述整段关系，而不只是其中一条条款。"},{"no":"07","title":"Rights created by agreement","titleCN":"由协议创设的权利","definition":"entitlements that exist because a contract grants them, as opposed to rights given by statute","definitionCN":"因合同授予而存在的权利，与法律直接赋予的权利相对","example":"The tenant's contractual rights outlived the original owner.","exampleCN":"租户的合同权利在原业主离场后仍然有效。","why":"Rights can come from two sources, and the adjective identifies the private one.","whyCN":"权利可以有两个来源，这个形容词标出其中私人约定的那一个。"},{"no":"08","title":"Contract-based rather than statutory","titleCN":"基于合同而非基于成文法","definition":"a remedy or claim that rests on the agreement itself, not on a general rule of law","definitionCN":"依据协议本身而非一般法律规则提出的救济或主张","example":"The buyer chose a contractual remedy instead of a statutory one.","exampleCN":"买方选择了合同上的救济，而非成文法上的救济。","why":"The adjective's final job is to separate two legal routes that can reach the same money.","whyCN":"这个形容词最后的作用，是把两条能通向同一笔钱的法律路径分开。"}],"etymology":{"intro":{"en":"Contractual is contract plus a Latin adjective ending. Contract comes from Latin contractus, the past participle of contrahere, to draw together, built on com- and trahere.","cn":"contractual 是 contract 加一个拉丁语形容词词尾构成。contract 来自拉丁语 contractus，即 contrahere 的过去分词，意为「拉到一起」，由 com- 与 trahere 构成。"},"items":[{"era":"LATIN TRAHERE","en":"Trahere meant to draw or drag. Its deeper origin is not established, so any earlier form claimed for it is source uncertain.","cn":"trahere 意为「拉、拖」。其更深来源未得到证明，因此为它主张的更早形式都属于来源不确定。"},{"era":"LATIN CONTRAHERE","en":"Com- together plus trahere to draw gave contrahere, to draw together, and also to make a compact.","cn":"表示「共同」的 com- 加 trahere「拉」构成 contrahere，意为「拉到一起」，也指「订立协议」。"},{"era":"LATIN CONTRACTUS","en":"The past participle contractus named something drawn together, and in law an agreement drawn up between parties.","cn":"过去分词 contractus 指「被拉到一起的东西」，在法律上指各方拟定的一份协议。"},{"era":"OLD FRENCH CONTRACT","en":"Old French contract kept the legal sense, and English borrowed it in the fourteenth century.","cn":"古法语 contract 保留了法律义，英语在十四世纪借入。"},{"era":"ENGLISH CONTRACT","en":"English contract covers both the document and the act of catching a disease or shrinking a muscle, all from the same image of drawing together.","cn":"英语 contract 既指文件，也指染病或肌肉收缩，这些都出自同一个「拉到一起」的意象。"},{"era":"ADJECTIVAL ENDING","en":"The ending -ual, from Latin -alis, turns the noun into an adjective meaning having the nature of a contract.","cn":"词尾 -ual 来自拉丁语 -alis，把名词变成表示「具有合同性质」的形容词。"}]},"similar":{"note":{"en":"The first group holds forms of the same root, including one look-alike from a different verb; the second holds legal adjectives that are often used interchangeably but are not.","cn":"第一组是同根形式，其中包括一个来自不同动词的形近词；第二组是常被混用、实际却有区别的法律形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"contract","ipa":"/ˈkɒntrækt/","tag":"the noun and verb","definition":"The agreement itself, or to enter one; the adjective merely describes what belongs to it.","definitionCN":"协议本身，或订立协议；形容词只是描述属于它的事物。"},{"word":"contraction","ipa":"/kənˈtrækʃn/","tag":"the other branch","definition":"A shrinking or a shortened form, from the same verb but a different sense of drawing together.","definitionCN":"收缩或缩略形式，同出那个动词，但取「拉紧」的另一义。"},{"word":"contractor","ipa":"/kənˈtræktə/","tag":"the person","definition":"A party that agrees to supply work or goods; it names a person, not a quality.","definitionCN":"同意提供工程或货物的一方；它指人，不指性质。"},{"word":"contact","ipa":"/ˈkɒntækt/","tag":"different Latin verb","definition":"From contingere, to touch, built on tangere; it looks close to contract but has a different root.","definitionCN":"来自 contingere「接触」，其词根是 tangere；它与 contract 拼写相近，词根却不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"legal","ipa":"/ˈliːɡl/","tag":"the whole field","definition":"Relating to law in general; contractual is narrower and points to private agreements only.","definitionCN":"泛指与法律有关；contractual 更窄，只指向私人协议。"},{"word":"binding","ipa":"/ˈbaɪndɪŋ/","tag":"enforceable","definition":"Able to be enforced in law; a contractual term may exist without being binding.","definitionCN":"可在法律上强制执行的；合同条款可能存在却不具约束力。"},{"word":"statutory","ipa":"/ˈstætʃətri/","tag":"the opposite source","definition":"Created by a statute rather than by an agreement; the direct contrast in legal writing.","definitionCN":"由成文法而非协议创设的；在法律文书中正是对照说法。"},{"word":"agreed","ipa":"/əˈɡriːd/","tag":"settled between sides","definition":"Accepted by both parties, which may happen without any written contract.","definitionCN":"双方都接受的，未必有任何书面合同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Contract plus ual: the adjective of everything a signed agreement carries.","cn":"「合同」加形容词词尾：凡是签署协议所带的东西，都用这个形容词。"},{"en":"The family runs contract, contractual, contractually, contractor and contraction.","cn":"同族词包括 contract、contractual、contractually、contractor 与 contraction。"},{"en":"Fixed phrases mark duties and disputes: contractual obligation, contractual terms, contractual dispute.","cn":"固定搭配标出义务与纠纷两面：合同义务、合同条款、合同纠纷。"},{"en":"Keep contract and contact apart: one draws terms together, the other touches.","cn":"把合同与接触分开：一个把条件拉到一起，一个是触碰。"},{"en":"A clause with a signature box is the smallest visible unit of anything contractual.","cn":"一条带签字方框的条款，就是任何合同事物最小的可见单位。"}],"abstract":[{"en":"Picture two strings pulled into one knot, and a written line under the knot.","cn":"想象两根绳子被拉成一个结，结下写着一条文字。"},{"en":"Picture a promise wearing a sealed envelope as its body.","cn":"想象一个承诺把密封的信封当作自己的身体。"},{"en":"Picture two roads to the same sum of money, one paved by a signature and one by a statute.","cn":"想象通往同一笔钱的两条路，一条由签名铺成，一条由成文法铺成。"}]},"examples":[{"en":"The lease sets out the contractual duties of both sides.","cn":"租约列明了双方的合同义务。"},{"en":"She refused the extra shift because it was not contractual.","cn":"她拒绝了那次加班，因为合同里并没有这一项。"},{"en":"A contractual claim must be brought within the stated period.","cn":"合同上的请求必须在规定的期限内提出。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「合同（contract）上的」——凡是写在合同条款里、由合同规定的，就是合同的","word":"contractual"},"root":"contract 来自拉丁语 contractus，即 contrahere「拉到一起」的过去分词，由表示「共同」的 com- 与 trahere「拉」构成；加形容词词尾 -ual 成为 contractual。","sensesIntro":{"en":"Eight senses follow one signed page: the field of contracts, a duty it creates, a term it fixes, a job it defines, a liability it produces when broken, a relationship it governs, a right it grants, and a route distinct from statute.","cn":"八个义项沿同一页签字的纸展开：合同这个领域、它产生的义务、它定下的条款、它界定的工作、被违反时产生的责任、它所约束的关系、它授予的权利，以及区别于成文法的一条路径。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open contract on a table, each clause with a small box for a signature.","cn":"核心意象：桌上摊开的合同，每条条款旁都有一个小签字框。"},"chain":["DRAW TOGETHER","SIGN THE PAGE","FIX THE DUTY","HOLD A JOB","BREAK AND OWE","A PRIVATE ROUTE"],"branches":[{"senses":"01","en":"THE WHOLE FIELD: the adjective at its widest, naming a domain rather than a duty.","cn":"整个领域：形容词最宽的用法，指一个范畴而非一项义务。"},{"senses":"02 · 03","en":"WHAT THE PAGE REQUIRES: an obligation and a written term are the same page seen as duty and as text.","cn":"纸页要求的事：义务与条款是同一页纸，一个看成责任，一个看成文字。"},{"senses":"04","en":"A PERSON HELD BY PAPER: employment on a fixed term is the adjective applied to a life.","cn":"被纸约束的人：定期雇用把这个形容词用在人的生计上。"},{"senses":"05 · 07","en":"TWO SIDES OF THE SAME PAGE: a broken promise creates liability, a kept one creates rights.","cn":"同一页纸的两面：承诺落空产生责任，承诺履行产生权利。"},{"senses":"06 · 08","en":"A LASTING BOND AND A SEPARATE ROAD: the relationship persists, and the remedy runs beside statute rather than through it.","cn":"持续的关系与另一条路：关系延续，救济与成文法并行而不经过它。"}]},"affixes":{"intro":{"en":"The word is a Latin participle turned noun, then turned adjective by a Latin ending, so it reads as something drawn together and belonging to that drawing.","cn":"这个词由拉丁语分词转成名词，再加拉丁语词尾转成形容词，读作「被拉到一起的东西」以及「属于这种拉合」。"},"latinIntro":{"en":"Latin trahere and contrahere supply contract; the ending -alis, through French -al, supplies the adjective form.","cn":"拉丁语 trahere 与 contrahere 提供 contract；拉丁语词尾 -alis 经法语 -al 提供形容词形式。"},"items":[{"word":"com-","structure":"com- (Latin prefix, together)","meaning":"together","meaningCN":"共同；一起","example":"The prefix pulls two parties into one act.","exampleCN":"这个前缀把两方拉进同一个动作。"},{"word":"trahere","structure":"trahere (Latin verb, to draw, drag)","meaning":"to draw; to drag","meaningCN":"拉；拖","example":"The root supplies the image of drawing lines together.","exampleCN":"这个词根提供「把线拉到一起」的意象。"},{"word":"contrahere","structure":"com- + trahere","meaning":"to draw together; to make an agreement","meaningCN":"拉到一起；订立协议","example":"The parties contrahere before witnesses.","exampleCN":"各方在见证人面前订立协议。"},{"word":"contract","structure":"Latin contractus, past participle of contrahere","meaning":"an agreement drawn up between parties","meaningCN":"各方拟定的协议","example":"The contract runs for three years.","exampleCN":"这份合同为期三年。"},{"word":"contractual","structure":"contract + -ual (relating to)","meaning":"belonging to a contract","meaningCN":"与合同有关的","example":"The delay raised a contractual question.","exampleCN":"这次延误引出了一个合同问题。"},{"word":"contractually","structure":"contractual + -ly (in the manner of)","meaning":"by the terms of a contract","meaningCN":"按合同地","example":"The firm is contractually bound to deliver.","exampleCN":"这家公司在合同上有交付义务。"},{"word":"contractor","structure":"contract + -or (one who does)","meaning":"a party who agrees to supply","meaningCN":"承包商；立约人","example":"The contractor signed before starting work.","exampleCN":"承包商在开工前签了字。"},{"word":"contraction","structure":"contract + -ion (act or result)","meaning":"a shrinking; a shortened form","meaningCN":"收缩；缩略形式","example":"The contraction of the muscle was visible.","exampleCN":"肌肉的收缩肉眼可见。"},{"word":"-al","structure":"-alis (Latin adjective ending)","meaning":"relating to; having the nature of","meaningCN":"与……有关的","example":"The ending turns a noun into a description.","exampleCN":"这个词尾把名词变成描述性形容词。"}],"latinEntries":[{"word":"trahere","structure":"trahere, traxi, tractum (third conjugation; Latin)","meaning":"to draw, drag","meaningCN":"拉；拖"},{"word":"contrahere","structure":"contrahere, contraxi, contractum (third conjugation; Latin)","meaning":"to draw together, make an agreement","meaningCN":"拉到一起；订立协议"},{"word":"contractus","structure":"contractus, -us (m., fourth declension; Latin)","meaning":"a drawing together; an agreement","meaningCN":"拉合；协议"}]}},{"word":"transaction","ipa_uk":"/trænˈzækʃn/","ipa_us":"/trænˈzækʃn/","definition_zh":"交易；业务；（数据库）事务","definition_en":"a single act of buying, selling or transferring, or one unit of work that must succeed or fail as a whole","core_image":"柜台两侧，一只手递出货品，另一只手交过钱，中间的收据被撕成两半，各留一份","scene":"柜台两侧，一只手递出货品，另一只手交过钱，中间的收据被撕成两半。Every transaction is recorded twice, once for the buyer and once for the seller.","sceneCN":"这里这个词指「一次买卖或资金往来」（第 1 个义项：一笔商业交易）；句意为每一笔交易都被记录两次，一次给买方，一次给卖方。图中可辨识物件：柜台、递出的货品、钱币、撕成两半的收据。","pos":[{"tag":"n.","zh":"交易；业务往来；（数据库）事务"}],"collocations":[{"phrase":"business transaction","zh":"商业交易"},{"phrase":"financial transaction","zh":"金融交易；资金往来"},{"phrase":"transaction cost","zh":"交易成本"},{"phrase":"transaction record","zh":"交易记录"},{"phrase":"bank transaction","zh":"银行交易"},{"phrase":"transaction processing","zh":"事务处理"}],"forms":[{"label":"复数","form":"transactions"},{"label":"动词","form":"transact"},{"label":"动词三单","form":"transacts"},{"label":"名词（办理者）","form":"transactor"},{"label":"形容词","form":"transactional"},{"label":"副词","form":"transactionally"}],"derivatives":[{"word":"transact","pos":"v.","zh":"进行交易；办理业务"},{"word":"transactor","pos":"n.","zh":"交易者；办理者"},{"word":"transactional","pos":"adj.","zh":"交易的；事务性的"},{"word":"transactionally","pos":"adv.","zh":"按交易方式地"},{"word":"transactionalize","pos":"v.","zh":"使变为交易"}],"senses":[{"no":"01","title":"A single business deal","titleCN":"一笔商业交易","definition":"one completed exchange of goods, services or money between two parties","definitionCN":"两方之间一次完成的货物、服务或金钱交换","example":"The deal was recorded as one transaction in the ledger.","exampleCN":"这笔买卖在账簿上记为一笔交易。","why":"The Latin verb means to carry something through, and a deal is a thing carried to completion.","whyCN":"拉丁语动词意为「把某事办到底」，一笔交易就是被办到底的一件事。"},{"no":"02","title":"One movement in an account","titleCN":"账户上的一次资金变动","definition":"a single deposit, withdrawal or transfer shown on a bank statement","definitionCN":"银行对账单上显示的一次存入、取出或划转","example":"Each transaction appears on the statement with a date.","exampleCN":"每一笔交易都带着日期出现在对账单上。","why":"A bank account breaks a month into single movements, and each one is a transaction.","whyCN":"银行账户把一个月拆成一次次资金变动，每一次都是一笔交易。"},{"no":"03","title":"A database unit that must wholly succeed","titleCN":"必须整体成功或整体失败的数据库事务","definition":"a group of operations that either all take effect or none does","definitionCN":"一组要么全部生效、要么全部不生效的操作","example":"If the second step fails, the whole transaction is rolled back.","exampleCN":"如果第二步失败，整个事务就被回滚。","why":"Computing borrowed the word because a unit of work is carried through completely or not at all.","whyCN":"计算机借用了这个词，因为一项工作要么被完整办完，要么根本不办。"},{"no":"04","title":"The cost of arranging an exchange","titleCN":"安排一次交换所付的成本","definition":"the time, fee and effort needed to bring a buyer and a seller together","definitionCN":"把买卖双方凑到一起所需的时间、费用与精力","example":"Low transaction costs made the online market grow quickly.","exampleCN":"低廉的交易成本让这个线上市场迅速成长。","why":"Once deals are counted, the expense of making one becomes a quantity of its own.","whyCN":"当交易被计入之后，促成一次交易的花费本身也成了一个量。"},{"no":"05","title":"A legal act that moves rights","titleCN":"转移权利的法律行为","definition":"an act recognized by law as transferring ownership or creating an obligation","definitionCN":"被法律承认、能转移所有权或创设义务的行为","example":"The transfer of the land was a transaction in law.","exampleCN":"这片土地的转让在法律上是一宗交易。","why":"Law treats the physical exchange and the change of rights as one act.","whyCN":"法律把实物的交换与权利的变动看作同一个行为。"},{"no":"06","title":"A completed exchange of goods or services","titleCN":"已完成的货物或服务交换","definition":"the finished swap itself, after both sides have performed what they promised","definitionCN":"双方都履行承诺之后完成的那次交换本身","example":"The transaction closed when the keys changed hands.","exampleCN":"钥匙易手时，这笔交易就完成了。","why":"The emphasis falls on completion, the meaning carried by the Latin verb.","whyCN":"这里的重点落在「完成」上，这正是拉丁语动词所带的意思。"},{"no":"07","title":"Transaction processing as a system","titleCN":"作为系统的事务处理","definition":"the routine, high-volume handling of many small operations, as in banking or ticketing","definitionCN":"对大量小型操作进行例行的、高吞吐的处理，如银行或售票系统","example":"The airline's transaction processing handles thousands of bookings a minute.","exampleCN":"这家航空公司的交易处理系统每分钟处理成千上万的订票。","why":"The single deal becomes a stream, and the stream needs a system with a name.","whyCN":"单笔交易汇成一条流，这条流需要一个有名字的系统。"},{"no":"08","title":"An exchange treated as a social act","titleCN":"被当作社会互动的交换","definition":"an interaction in which people give and receive something, not necessarily money","definitionCN":"人们互给互取的一种互动，未必涉及金钱","example":"He treated the favor as a transaction with a hidden price.","exampleCN":"他把这份人情当作一桩暗含代价的交易。","why":"The market word can be stretched to cover any give-and-take between people.","whyCN":"这个市场词可以被拉到任何人与人之间的互给互取上。"}],"etymology":{"intro":{"en":"Transaction comes from Latin transigere, to drive through or settle, built on trans- across and agere to drive; the computing sense is twentieth-century.","cn":"transaction 来自拉丁语 transigere「办到底、了结」，由表示「穿过」的 trans- 与 agere「驱动、做」构成；计算机义出现于二十世纪。"},"items":[{"era":"LATIN AGERE","en":"Agere meant to drive, do or act, and it supplies dozens of English verbs through its participle actus.","cn":"agere 意为「驱动、做、行动」，通过其分词 actus 为英语提供了大量动词。"},{"era":"LATIN TRANSIGERE","en":"Trans- across plus agere to drive gave transigere, to drive something through to its end, hence to settle a matter.","cn":"表示「穿过」的 trans- 加 agere「驱动」构成 transigere，意为「把某事推到底」，因此指「了结一件事」。"},{"era":"LATIN TRANSACTUM","en":"The supine transactum supplied the noun transactionem, a settling or an accomplishment.","cn":"动名词形式 transactum 提供了名词 transactionem，意为「了结、完成之事」。"},{"era":"FRENCH TRANSACTION","en":"French transaction carried the commercial sense of a settled deal into English in the fifteenth century.","cn":"法语 transaction 在十五世纪把「已了结的买卖」这一商业义带入英语。"},{"era":"ENGLISH LEDGER","en":"In bookkeeping every settled exchange became one line, and the word named that line.","cn":"在簿记中，每一次了结的交换成为一行记录，这个词就指那一行。"},{"era":"COMPUTING SENSE","en":"In the later twentieth century databases reused the word for a unit of work that must finish completely or not at all.","cn":"二十世纪后期，数据库把这个词再次用于必须完整完成、否则不生效的一项工作。"}]},"similar":{"note":{"en":"The first group holds forms of the same verb plus two other prefixes that are often confused; the second holds plainer names for an exchange.","cn":"第一组是同一个动词的形式，另加两个常被混淆的其它前缀词；第二组是交换的更朴素叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"transact","ipa":"/trænˈzækt/","tag":"the verb","definition":"To carry out a deal; the noun names the thing done, the verb names doing it.","definitionCN":"进行一笔交易；名词指做成的事，动词指做这件事。"},{"word":"transactor","ipa":"/trænˈzæktə/","tag":"the party","definition":"A person or firm that carries out the deal; it names the actor, not the act.","definitionCN":"完成交易的个人或公司；它指行动者，不指行为。"},{"word":"transition","ipa":"/trænˈzɪʃn/","tag":"different root","definition":"A passing from one state to another, from trans- plus ire, to go; the prefix matches but the verb does not.","definitionCN":"从一种状态过渡到另一种，由 trans- 加 ire「走」构成；前缀相同，动词不同。"},{"word":"transfer","ipa":"/trænsˈfɜː/","tag":"different root","definition":"To carry across, from trans- plus ferre, to carry; it moves things, while a transaction settles a deal.","definitionCN":"搬移过去，由 trans- 加 ferre「搬运」构成；它移动东西，而交易是了结一笔买卖。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deal","ipa":"/diːl/","tag":"informal, broad","definition":"An arrangement or an exchange, used in speech for deals of every size.","definitionCN":"一种安排或交换，口语中可用于各种规模的交易。"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","tag":"the swap itself","definition":"The act of giving one thing and receiving another; it stresses reciprocity rather than settlement.","definitionCN":"给出一样东西并收到另一样；它强调相互性，而非了结。"},{"word":"operation","ipa":"/ˌɒpəˈreɪʃn/","tag":"one step in a system","definition":"A single piece of work inside a larger process; a computing transaction is one kind of operation.","definitionCN":"更大流程中的一项工作；数据库事务是其中一种操作。"},{"word":"purchase","ipa":"/ˈpɜːtʃəs/","tag":"buying only","definition":"The act of buying; a transaction may also be a sale, a transfer or a deposit.","definitionCN":"购买行为；而交易也可以是出售、转让或存入。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Trans- across plus agere to drive: something driven through to its end.","cn":"表示「穿过」的前缀加「驱动」：一件被推到底的事。"},{"en":"The family runs transact, transaction, transactor and transactional.","cn":"同族词包括 transact、transaction、transactor 与 transactional。"},{"en":"Fixed phrases mark money and machines: financial transaction, transaction cost, transaction processing.","cn":"固定搭配标出金钱与机器两面：金融交易、交易成本、事务处理。"},{"en":"Keep the prefixes apart: trans- with agere settles, with ire passes, with ferre carries.","cn":"把前缀后的动词分清：接「驱动」是了结，接「走」是过渡，接「搬运」是转移。"},{"en":"A receipt torn in two is the simplest picture of one deal recorded on both sides.","cn":"一张撕成两半的收据，就是一笔交易被双方各记一次的最简画面。"}],"abstract":[{"en":"Picture a door that only closes when both hands push it, and stays shut afterwards.","cn":"想象一扇门只有在两只手同时推时才关上，关上之后就不再打开。"},{"en":"Picture a row of dominoes that either all fall or all stand.","cn":"想象一排多米诺骨牌，要么全部倒下，要么全部站住。"},{"en":"Picture two hands meeting in the air, each holding what the other needs.","cn":"想象两只手在半空相遇，各拿着对方需要的东西。"}]},"examples":[{"en":"The bank flags any transaction above the reporting limit.","cn":"银行会标记任何超过申报限额的交易。"},{"en":"A failed step cancels the entire transaction.","cn":"一步失败就会取消整个事务。"},{"en":"Cheap transactions encouraged people to trade small amounts often.","cn":"低廉的交易成本促使人们频繁进行小额买卖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「穿过（trans）把事情办成（act）」——一笔办到底的买卖或一次资金往来 → 交易、事务","word":"transaction"},"root":"拉丁语 transigere「办到底、了结」= trans-「穿过」+ agere「驱动、做」；其动名词形式提供名词 transaction，计算机义为后起引申。","sensesIntro":{"en":"Eight senses follow one thing driven through to its end: a business deal, a bank movement, a database unit, the cost of arranging it, a legal act, a completed swap, a processing stream and a social exchange.","cn":"八个义项沿同一件被办到底的事展开：商业交易、银行资金变动、数据库事务、促成它的成本、法律行为、已完成的交换、处理流水，以及社会性的互给互取。"},"semanticMap":{"core":{"en":"CORE IMAGE: a receipt torn in two across a counter, one half kept by each side.","cn":"核心意象：柜台上一张被撕成两半的收据，双方各留一半。"},"chain":["DRIVE IT THROUGH","ONE DEAL DONE","ONE LINE IN A LEDGER","ONE UNIT IN A SYSTEM","COST OF ARRANGING","ANY GIVE AND TAKE"],"branches":[{"senses":"01 · 06","en":"ONE DEAL: the exchange and its completion are the same act seen at its start and its end.","cn":"一笔交易：交换与它的完成是同一个行为在起点与终点的样子。"},{"senses":"02","en":"ONE LINE: a bank statement breaks a month into single recorded movements.","cn":"一行记录：银行对账单把一个月拆成一次次被记下的变动。"},{"senses":"03 · 07","en":"ONE UNIT, THEN MANY: a database transaction and a processing stream are the same unit at one and at scale.","cn":"一个单元，再到许多：数据库事务与处理流水是同一单元的单数与规模版。"},{"senses":"04","en":"THE PRICE OF ARRANGING: the effort of bringing two sides together becomes its own quantity.","cn":"安排的价格：把双方凑到一起的力气本身成了一个量。"},{"senses":"05 · 08","en":"BEYOND MONEY: a legal transfer of rights and a social favor are both exchanges with a price.","cn":"金钱之外：权利的法定转移与一桩人情，都是带有代价的交换。"}]},"affixes":{"intro":{"en":"The word is a Latin verb with a prefix meaning across plus a verb meaning to drive, turned into a noun of result.","cn":"这个词由表示「穿过」的前缀与表示「驱动」的动词构成的拉丁语动词，再转为表示结果的名词。"},"latinIntro":{"en":"Latin agere supplies act, agent and agenda; trans- supplies a family of crossing words including transition and transfer.","cn":"拉丁语 agere 提供 act、agent 与 agenda；trans- 提供 transition 与 transfer 等一组表示「越过」的词。"},"items":[{"word":"trans-","structure":"trans- (Latin prefix, across, through)","meaning":"across; through","meaningCN":"穿过；越过","example":"The prefix carries the action from one side to the other.","exampleCN":"这个前缀把动作从一边带到另一边。"},{"word":"agere","structure":"agere (Latin verb, to drive, do)","meaning":"to drive; to do","meaningCN":"驱动；做","example":"The verb supplies the doing at the centre of the word.","exampleCN":"这个动词提供词中央的「做」。"},{"word":"transigere","structure":"trans- + agere","meaning":"to drive through; to settle","meaningCN":"推到底；了结","example":"The parties settled the dispute before winter.","exampleCN":"各方在入冬前了结了争端。"},{"word":"transaction","structure":"transigere + -tion (result of an action)","meaning":"a settled deal","meaningCN":"已了结的交易","example":"The transaction closed at noon.","exampleCN":"这笔交易在中午完成。"},{"word":"transact","structure":"back formation from transaction","meaning":"to carry out a deal","meaningCN":"进行交易","example":"They transact business by phone.","exampleCN":"他们通过电话办理业务。"},{"word":"transactor","structure":"transact + -or (one who does)","meaning":"a party to a deal","meaningCN":"交易的一方","example":"Each transactor keeps a copy of the record.","exampleCN":"交易各方各留一份记录。"},{"word":"transactional","structure":"transaction + -al (relating to)","meaning":"relating to a deal","meaningCN":"与交易有关的","example":"The bank charges a small transactional fee.","exampleCN":"银行收取一小笔交易费。"},{"word":"act","structure":"Latin actus, from agere","meaning":"a deed","meaningCN":"行为；举动","example":"The act closed the matter.","exampleCN":"这一行为把此事了结。"},{"word":"agent","structure":"Latin agent-, from agere","meaning":"one who acts","meaningCN":"行动者；代理人","example":"The agent signed on behalf of the firm.","exampleCN":"代理人代表公司签了字。"}],"latinEntries":[{"word":"agere","structure":"agere, egi, actum (third conjugation; Latin)","meaning":"to drive, do, act","meaningCN":"驱动；做；行动"},{"word":"transigere","structure":"transigere, transegi, transactum (third conjugation; Latin)","meaning":"to drive through, settle","meaningCN":"推到底；了结"},{"word":"transactio","structure":"transactio, -onis (f., third declension; Latin)","meaning":"a settling, an agreement","meaningCN":"了结；协议"}]}},{"word":"transact","ipa_uk":"/trænˈzækt/","ipa_us":"/trænˈzækt/","definition_zh":"进行交易；办理业务；处理（一笔事务）","definition_en":"to carry out a piece of business, especially a sale, a payment or a deal","core_image":"两个人隔着柜台把手各自伸向中间，掌心相合时一张收据落下一角","scene":"隔着柜台，两人的手伸向中间，收据在掌心相合时落下一角。They transact business through a licensed agent.","sceneCN":"这里这个词指「办理一笔业务、完成一次交易」（第 1 个义项：与某人进行业务往来）；句意为他们通过持牌代理人办理业务。图中可辨识物件：柜台、伸出的手、收据、印章。","pos":[{"tag":"v.","zh":"进行交易；办理业务；处理（事务）"}],"collocations":[{"phrase":"transact business","zh":"办理业务；做买卖"},{"phrase":"transact with","zh":"与……进行交易"},{"phrase":"transact a deal","zh":"达成一笔交易"},{"phrase":"transact online","zh":"在线交易"},{"phrase":"transact through an agent","zh":"通过代理人办理"},{"phrase":"transact at a branch","zh":"在网点办理"}],"forms":[{"label":"三单","form":"transacts"},{"label":"过去式","form":"transacted"},{"label":"过去分词","form":"transacted"},{"label":"现在分词","form":"transacting"},{"label":"名词（交易）","form":"transaction"},{"label":"名词（办理者）","form":"transactor"}],"derivatives":[{"word":"transaction","pos":"n.","zh":"交易；事务"},{"word":"transactor","pos":"n.","zh":"交易者；办理者"},{"word":"transactional","pos":"adj.","zh":"交易的；事务性的"},{"word":"transacting","pos":"n.","zh":"交易办理（作名词时）"},{"word":"transactionally","pos":"adv.","zh":"按交易方式地"}],"senses":[{"no":"01","title":"To do business with someone","titleCN":"与某人做买卖、办业务","definition":"to carry out business with a person or a firm","definitionCN":"与某个人或某家公司办理业务","example":"The two houses have transacted with each other for decades.","exampleCN":"这两家商号互相做生意已有几十年。","why":"The verb names the whole activity of dealing, not one finished deal.","whyCN":"这个动词指做生意这一整体活动，而非某一笔已完成的交易。"},{"no":"02","title":"To complete one particular deal","titleCN":"完成某一笔具体交易","definition":"to settle a single sale or agreement from start to finish","definitionCN":"把某一笔买卖或协议从头到尾了结","example":"The sale was transacted in a single afternoon.","exampleCN":"这笔买卖在一个下午就办完了。","why":"The Latin verb means to drive through, so one deal can be driven to its end.","whyCN":"拉丁语动词意为「推到底」，因此一笔交易可以被推到终点。"},{"no":"03","title":"To deal through an intermediary","titleCN":"通过中间人办理","definition":"to carry out business by authorizing another party to act","definitionCN":"授权另一方代为办理业务","example":"Landowners transact through agents at the auction.","exampleCN":"地主们在拍卖会上通过代理人办理交易。","why":"The act can be performed by a hand other than the owner's, and the verb still applies.","whyCN":"这件事可以由业主以外的一只手完成，而动词仍然适用。"},{"no":"04","title":"To deal at a distance","titleCN":"远程办理","definition":"to carry out a deal by phone or over a network rather than face to face","definitionCN":"通过电话或网络而非面对面地完成交易","example":"Most customers now transact online rather than at the counter.","exampleCN":"现在大多数顾客在网上而不是在柜台办理。","why":"The channel changes, but the act of carrying a deal through stays the same.","whyCN":"渠道变了，但把交易办到底这一动作没有变。"},{"no":"05","title":"To deal at a branch or counter","titleCN":"在网点或柜台办理","definition":"to perform a banking or official errand at a physical service point","definitionCN":"在实体服务点办理银行业务或官方手续","example":"You can transact at any branch of the bank.","exampleCN":"你可以在该银行的任何网点办理。","why":"A place designed for these acts gives the verb a setting rather than a new meaning.","whyCN":"为这些行为设计的场所，给动词提供的是场景，而不是新义。"},{"no":"06","title":"To trade in a market","titleCN":"在市场上进行买卖","definition":"to buy and sell within an organized market such as a securities exchange","definitionCN":"在有组织的市场（如证券交易所）中买入卖出","example":"Funds transact in bonds through a small group of dealers.","exampleCN":"基金通过一小群交易商买卖债券。","why":"A market is where repeated dealing happens, and the verb covers that repeated activity.","whyCN":"市场正是反复买卖发生的地方，这个动词覆盖那种反复活动。"},{"no":"07","title":"To settle a sale formally","titleCN":"正式了结一笔买卖","definition":"to complete the formal steps that make a transfer legally effective","definitionCN":"完成使转让在法律上生效的正式步骤","example":"The notary transacted the transfer before witnesses.","exampleCN":"公证人在见证人面前办妥了这次转让。","why":"Formalities are the last stretch of the road the deal has to be driven along.","whyCN":"手续正是这笔交易必须走完的最后一段路。"},{"no":"08","title":"To handle business as routine","titleCN":"作为例行事务处理业务","definition":"to process everyday business as part of normal operations","definitionCN":"作为日常运营的一部分处理每日业务","example":"The office transacts hundreds of small claims each week.","exampleCN":"这个办事处每周处理数百件小额索赔。","why":"When the acts repeat, the verb shifts from one deal to a routine stream.","whyCN":"当这些行为反复出现，动词就从一笔交易转向例行的流水。"}],"etymology":{"intro":{"en":"Transact is a back formation from transaction, which comes from Latin transigere, to drive through or settle, built on trans- across and agere to drive.","cn":"transact 是从 transaction 逆构而成的动词，而 transaction 来自拉丁语 transigere「推到底、了结」，由 trans-「穿过」与 agere「驱动」构成。"},"items":[{"era":"LATIN AGERE","en":"Agere meant to drive, do or act; through actus it also gives act, agent and agenda.","cn":"agere 意为「驱动、做、行动」；通过 actus 它还提供了 act、agent 与 agenda。"},{"era":"LATIN TRANSIGERE","en":"Trans- across plus agere to drive gave transigere, to drive a matter through to its end, hence to settle it.","cn":"表示「穿过」的 trans- 加 agere「驱动」构成 transigere，意为「把一件事推到尽头」，因此指「了结」。"},{"era":"LATIN TRANSACTUM","en":"The supine transactum produced the noun of action, and from it the English noun transaction.","cn":"动名词形式 transactum 产生表示动作的名词，英语名词 transaction 由此而来。"},{"era":"ENGLISH NOUN","en":"English took the noun in the fifteenth century for a settled commercial dealing.","cn":"英语在十五世纪借入这个名词，指一笔已了结的商业往来。"},{"era":"ENGLISH VERB","en":"The verb transact was formed later from the noun, by removing the ending, and it means to carry such a dealing through.","cn":"动词 transact 后来由名词去掉词尾逆构而成，意为「把这样一笔往来办完」。"},{"era":"MODERN ROUTINE","en":"In modern banking and computing the verb also covers routine handling rather than one celebrated deal.","cn":"在现代银行与计算机业务中，这个动词也覆盖例行处理，而不只是一笔引人注目的交易。"}]},"similar":{"note":{"en":"The first group holds the noun and its relatives plus two crossing verbs with different roots; the second holds plainer verbs for doing business.","cn":"第一组是名词及其同族，另加两个词根不同的「越过」类动词；第二组是办理业务的更朴素动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"transaction","ipa":"/trænˈzækʃn/","tag":"the noun","definition":"The deal itself; the verb names the doing of what the noun names.","definitionCN":"交易本身；动词指做名词所指的那件事。"},{"word":"transactor","ipa":"/trænˈzæktə/","tag":"the party","definition":"One who transacts; it names a participant rather than an activity.","definitionCN":"办理交易的人；它指参与者，而非活动。"},{"word":"transit","ipa":"/ˈtrænzɪt/","tag":"different root","definition":"Passage through a place, from trans- plus ire, to go; the prefix matches but the verb does not.","definitionCN":"穿过某地，由 trans- 加 ire「走」构成；前缀相同，动词不同。"},{"word":"transfer","ipa":"/trænsˈfɜː/","tag":"different root","definition":"To move something across, from trans- plus ferre, to carry; it moves goods or rights, not a deal.","definitionCN":"把某物搬过去，由 trans- 加 ferre「搬运」构成；它移动货物或权利，而非一笔交易。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conduct","ipa":"/kənˈdʌkt/","tag":"carry on business","definition":"To carry on an activity or a piece of business; broader and more formal than transact.","definitionCN":"开展某项活动或业务；比 transact 更宽、更正式。"},{"word":"carry out","ipa":"/ˌkæri ˈaʊt/","tag":"perform a task","definition":"To perform a plan or an instruction; it can describe any task, not only a deal.","definitionCN":"执行计划或指令；可描述任何任务，不只交易。"},{"word":"deal","ipa":"/diːl/","tag":"informal","definition":"To buy and sell or to negotiate, used in everyday speech for every size of exchange.","definitionCN":"买卖或谈判，日常口语中可用于各种规模的交换。"},{"word":"negotiate","ipa":"/nɪˈɡəʊʃieɪt/","tag":"argue to agreement","definition":"To discuss in order to reach terms; transact begins once the terms are settled.","definitionCN":"为达成条件而商谈；transact 从条件谈定之后才开始。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Trans- across plus agere to drive: to drive a deal from start to finish.","cn":"表示「穿过」的前缀加「驱动」：把一笔交易从头推到尾。"},{"en":"The family runs transact, transaction, transactor and transactional.","cn":"同族词包括 transact、transaction、transactor 与 transactional。"},{"en":"Fixed phrases mark the channel: transact business, transact online, transact through an agent.","cn":"固定搭配标出渠道：办理业务、在线交易、通过代理人办理。"},{"en":"The verb comes from the noun by dropping the ending, so the deal existed before the doing.","cn":"动词由名词去掉词尾而来，所以先有交易这件事，才有办理这个动作。"},{"en":"In a branch the verb is routine, on a trading floor it is repeated, at a notary it is formal.","cn":"在网点是例行，在交易场是反复，在公证人面前是正式。"}],"abstract":[{"en":"Picture a hand pushing a token across a table until it touches the other hand.","cn":"想象一只手把一枚筹码推过桌面，直到它碰到另一只手。"},{"en":"Picture a corridor with a door at the far end that only opens when you reach it.","cn":"想象一条走廊，尽头的门只有走到那里才会打开。"},{"en":"Picture two signatures arriving on the same line from opposite sides.","cn":"想象两个签名从相反方向落在同一条线上。"}]},"examples":[{"en":"Small firms often transact through a local agent.","cn":"小公司常通过本地代理人办理交易。"},{"en":"The bank allows customers to transact from any branch.","cn":"这家银行允许客户在任何网点办理业务。"},{"en":"They transacted the sale before the registry closed.","cn":"他们在登记处关门之前办完了这笔买卖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「穿过（trans）把事办完（act）」——把一笔买卖从头办到尾 → 进行交易、办理业务","word":"transact"},"root":"由名词 transaction 逆构而来；transaction 出自拉丁语 transigere「推到底、了结」= trans-「穿过」+ agere「驱动、做」。","sensesIntro":{"en":"Eight senses follow one act of driving a deal through: dealing with a party, completing one sale, acting through an agent, dealing at a distance, at a branch, in a market, before a notary, and as daily routine.","cn":"八个义项沿同一个「把交易办到底」的动作展开：与一方往来、完成一笔买卖、通过代理人、远程办理、在网点办理、在市场买卖、在公证人面前办妥，以及作为日常例行。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hands reaching across a counter, a receipt corner falling as they meet.","cn":"核心意象：两只手隔着柜台伸向中间，相合时收据的一角落下。"},"chain":["DRIVE IT ACROSS","MEET THE OTHER SIDE","SETTLE ONE DEAL","ACT THROUGH ANOTHER","USE ANY CHANNEL","MAKE IT ROUTINE"],"branches":[{"senses":"01 · 02","en":"THE ACTIVITY AND THE ACT: dealing with a party in general, and finishing one particular sale.","cn":"活动与单次行为：与一方长期往来，以及把某一笔买卖办完。"},{"senses":"03","en":"ANOTHER HAND: an agent performs the act while the principal remains the party.","cn":"另一只手：代理人执行动作，委托人仍是当事方。"},{"senses":"04 · 05","en":"ANY PLACE: a network and a counter are two channels for the same errand.","cn":"任何地点：网络与柜台是同一件事的两种渠道。"},{"senses":"06 · 07","en":"A MARKET AND A NOTARY: repeated trading and formal completion are the same act at different speeds.","cn":"市场与公证人：反复买卖与正式办妥，是同一动作的不同速度。"},{"senses":"08","en":"ROUTINE: when the act repeats all day, it becomes ordinary handling.","cn":"例行：当这个动作整天重复，它就变成日常处理。"}]},"affixes":{"intro":{"en":"The verb is a Latin prefix meaning across plus a verb meaning to drive, borrowed through the noun and then shortened back into a verb.","cn":"这个动词由表示「穿过」的拉丁语前缀与表示「驱动」的动词构成，经名词借入，再逆构回动词。"},"latinIntro":{"en":"Latin agere gives act, agent and agenda, and trans- gives transition, transfer and transit, each with a different verb behind it.","cn":"拉丁语 agere 提供 act、agent 与 agenda；trans- 提供 transition、transfer 与 transit，各自后面的动词并不相同。"},"items":[{"word":"trans-","structure":"trans- (Latin prefix, across)","meaning":"across; through","meaningCN":"穿过；越过","example":"The prefix moves the action to the far side.","exampleCN":"这个前缀把动作移到对面。"},{"word":"agere","structure":"agere (Latin verb, to drive, do)","meaning":"to drive; to do","meaningCN":"驱动；做","example":"The verb supplies the doing.","exampleCN":"这个动词提供「做」这一层。"},{"word":"transigere","structure":"trans- + agere","meaning":"to drive through; settle","meaningCN":"推到底；了结","example":"They settled the matter in one meeting.","exampleCN":"他们在一次会上把此事了结。"},{"word":"transaction","structure":"transigere + -tion (result)","meaning":"a settled deal","meaningCN":"已了结的交易","example":"The transaction took a week to close.","exampleCN":"这笔交易用了一周才完成。"},{"word":"transact","structure":"back formation from transaction","meaning":"to carry out a deal","meaningCN":"进行交易","example":"They transact business at the counter.","exampleCN":"他们在柜台办理业务。"},{"word":"transactor","structure":"transact + -or (agent)","meaning":"a party to a deal","meaningCN":"交易一方","example":"Each transactor receives a receipt.","exampleCN":"交易各方都会拿到收据。"},{"word":"transactional","structure":"transaction + -al (relating to)","meaning":"relating to dealings","meaningCN":"与交易有关的","example":"The fee is transactional, not annual.","exampleCN":"这笔费用是按交易收取的，不是年费。"},{"word":"act","structure":"Latin actus, from agere","meaning":"a deed","meaningCN":"行为","example":"One act closed the dispute.","exampleCN":"一个举动结束了争端。"},{"word":"agenda","structure":"Latin agenda, things to be done","meaning":"a list of matters to handle","meaningCN":"待办事项；议程","example":"The agenda lists every deal to settle.","exampleCN":"议程列出了每一笔待了结的交易。"}],"latinEntries":[{"word":"agere","structure":"agere, egi, actum (third conjugation; Latin)","meaning":"to drive, do","meaningCN":"驱动；做"},{"word":"transigere","structure":"transigere, transegi, transactum (third conjugation; Latin)","meaning":"to drive through, settle","meaningCN":"推到底；了结"},{"word":"transactio","structure":"transactio, -onis (f., third declension; Latin)","meaning":"a settling","meaningCN":"了结；和解"}]}},{"word":"trader","ipa_uk":"/ˈtreɪdə/","ipa_us":"/ˈtreɪdər/","definition_zh":"商人；交易员；从事某类货物买卖的人","definition_en":"a person or firm that buys and sells goods, currencies or securities as a business","core_image":"交易大厅里一个人盯着屏幕上的报价，桌上的电话响个不停，手边摊着几张成交单","scene":"交易大厅里，一个人盯着屏幕上的报价，手边的电话一直响。A currency trader watches the rate move before placing an order.","sceneCN":"这里这个词指「以买卖为业的人」（第 1 个义项：从事买卖的人）；句意为一名外汇交易员在下单之前盯着汇率变动。图中可辨识物件：报价屏幕、电话、成交单、座椅。","pos":[{"tag":"n.","zh":"商人；交易员；（某类货物的）买卖者"}],"collocations":[{"phrase":"currency trader","zh":"外汇交易员"},{"phrase":"stock trader","zh":"股票交易员"},{"phrase":"commodity trader","zh":"大宗商品交易商"},{"phrase":"street trader","zh":"街头小贩"},{"phrase":"day trader","zh":"当日冲销交易者"},{"phrase":"trader in","zh":"做某类货物买卖的人"}],"forms":[{"label":"复数","form":"traders"},{"label":"动词（交易）","form":"trade"},{"label":"动词三单","form":"trades"},{"label":"动词过去式","form":"traded"},{"label":"名词（贸易）","form":"trade"},{"label":"名词（交易活动）","form":"trading"}],"derivatives":[{"word":"trade","pos":"n./v.","zh":"贸易；交易；买卖"},{"word":"trading","pos":"n./adj.","zh":"交易活动；交易的"},{"word":"tradesman","pos":"n.","zh":"手艺人；小商人"},{"word":"tradeable","pos":"adj.","zh":"可交易的"}],"senses":[{"no":"01","title":"A person who buys and sells as a business","titleCN":"以买卖为业的人","definition":"someone whose living comes from buying goods and selling them on","definitionCN":"靠买进货物再卖出谋生的人","example":"The grain trader buys from farms and sells to mills.","exampleCN":"粮商从农场买进，再卖给磨坊。","why":"Trade names the activity, and the ending names the one who performs it.","whyCN":"trade 指这种活动，词尾则指从事这种活动的人。"},{"no":"02","title":"A professional in a financial market","titleCN":"金融市场里的专业人员","definition":"someone employed to buy and sell currencies, shares or contracts for a firm","definitionCN":"受雇为某机构买卖外汇、股票或合约的人","example":"The trader closed the position before the announcement.","exampleCN":"交易员在公告发布前平掉了头寸。","why":"The market keeps the old word for dealing but adds speed and a screen.","whyCN":"市场沿用旧的「买卖者」一词，只是加上了速度与屏幕。"},{"no":"03","title":"A seller at a stall or on the street","titleCN":"摊位或街边的售卖者","definition":"a small seller working from a stall, a cart or a pavement","definitionCN":"在摊位、推车或人行道上做小本买卖的人","example":"A street trader sold roasted nuts outside the station.","exampleCN":"一位街头小贩在车站外卖炒货。","why":"The oldest kind of trader is simply the person standing beside the goods.","whyCN":"最古老的商人，就是站在货物旁边的那个人。"},{"no":"04","title":"A dealer in physical commodities","titleCN":"实物大宗商品的交易商","definition":"a firm that handles actual cargoes of oil, metal or grain rather than paper claims","definitionCN":"处理石油、金属或谷物实际货物、而非纸面权益的公司","example":"The commodity trader chartered a ship for the copper.","exampleCN":"大宗商品交易商为这批铜租下了一条船。","why":"When the goods are heavy, the trader must handle ships and warehouses, not only prices.","whyCN":"当货物沉重时，商人要处理船与仓库，而不只是价格。"},{"no":"05","title":"A short-term speculator","titleCN":"做短线的投机者","definition":"someone who opens and closes positions within one day to profit from small moves","definitionCN":"在一天之内开仓又平仓、靠小幅波动获利的人","example":"A day trader may make a dozen decisions before lunch.","exampleCN":"当日冲销者午饭前可能做十几次决定。","why":"The same dealing word takes a time prefix, and the prefix becomes the identity.","whyCN":"同一个表示买卖的词加上时间前缀，前缀就成了身份。"},{"no":"06","title":"A specialist in one kind of goods","titleCN":"专做某一类货物的买卖者","definition":"a person known by the goods they handle, such as silk, wine or furs","definitionCN":"以所经营货物而得名的人，如丝绸、葡萄酒或毛皮","example":"Her grandfather was a fur trader on the northern route.","exampleCN":"她的祖父是北方线路上的毛皮商人。","why":"The goods can be attached to the trader, and the phrase becomes a trade name.","whyCN":"货物名可以挂在商人前面，这个短语就成了行业名号。"},{"no":"07","title":"One who trades in influence or favors","titleCN":"拿影响力或人情做交换的人","definition":"a person who exchanges information, favors or access as if they were goods","definitionCN":"把信息、人情或门路当作货物来交换的人","example":"The columnist called him a trader in rumors.","exampleCN":"那位专栏作家称他是拿传闻做买卖的人。","why":"The market word can be borrowed for any exchange, including one with no goods at all.","whyCN":"这个市场词可被借去指任何交换，包括完全没有货物的交换。"},{"no":"08","title":"A merchant on a long trade route","titleCN":"长途贸易路线上的商人","definition":"a historical figure who carried goods between distant regions","definitionCN":"在遥远地区之间运送货物的历史人物","example":"Caravan traders linked the coast to the inland towns.","exampleCN":"商队商人把海岸与内陆城镇连了起来。","why":"Before markets had screens, the trader was the person who moved goods across distance.","whyCN":"在市场还没有屏幕之前，商人就是把货物跨越距离的人。"}],"etymology":{"intro":{"en":"Trader is trade plus the native agent ending -er. Trade first meant a track or a course of life, and only later the business of buying and selling; its source is Germanic, not Latin.","cn":"trader 是 trade 加本族施事后缀 -er 构成。trade 最初指「路径、生活方式」，后来才指买卖这种行业；其来源属日耳曼语，不是拉丁语。"},"items":[{"era":"MIDDLE LOW GERMAN TRADE","en":"Trade meant a track, a course or a way of life, and it passed into English from the Low Countries.","cn":"trade 意为「路径、行程、生活方式」，从低地国家传入英语。"},{"era":"MIDDLE ENGLISH TRADE","en":"In Middle English trade still meant a path or a habitual course, including a craft and its practice.","cn":"在中古英语中，trade 仍指路径或惯常的行当，包括手艺及其做法。"},{"era":"COMMERCE SENSE","en":"By the sixteenth century trade had narrowed to the business of buying and selling, the sense that now dominates.","cn":"到十六世纪，trade 已收窄为买卖这种行业，这一义项如今占主导。"},{"era":"ENGLISH TRADER","en":"Trader added the agent ending to the new commercial sense, naming a person who lives by dealing.","cn":"trader 在这个新的商业义上加施事后缀，指以买卖为生的人。"},{"era":"MARKET PROFESSIONAL","en":"In the nineteenth and twentieth centuries the word moved onto exchange floors and trading desks.","cn":"在十九与二十世纪，这个词进入交易所大厅与交易台。"},{"era":"GLOBAL ROUTES","en":"The older sense survives in phrases such as fur trader, where the goods and the route define the person.","cn":"较旧的用法仍保留在「毛皮商人」这类说法里，货物与路线共同界定这个人。"}]},"similar":{"note":{"en":"The first group holds the word, its base and two look-alikes from different sources; the second holds other names for someone who sells.","cn":"第一组是这个单词、它的词基，以及两个来源不同的形近词；第二组是卖东西的人的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"trade","ipa":"/treɪd/","tag":"the activity","definition":"The business of buying and selling; the person ending turns it into the one who does it.","definitionCN":"买卖这一行业；加上表示人的词尾，就变成从事它的人。"},{"word":"trading","ipa":"/ˈtreɪdɪŋ/","tag":"the activity, noun","definition":"The activity itself, often used of markets and sessions; it names the doing, not the doer.","definitionCN":"活动本身，常用于市场与交易时段；它指做的事，不指做的人。"},{"word":"tradesman","ipa":"/ˈtreɪdzmən/","tag":"skilled seller","definition":"A skilled worker or a small shopkeeper; it stresses a craft or a shop, not market dealing.","definitionCN":"熟练工匠或小店店主；它强调手艺或店铺，而非市场买卖。"},{"word":"traitor","ipa":"/ˈtreɪtə/","tag":"different root","definition":"One who betrays, from Latin tradere, to hand over; the spelling is close but the root is entirely different.","definitionCN":"背叛者，来自拉丁语 tradere「交出」；拼写相近，但词根完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"merchant","ipa":"/ˈmɜːtʃənt/","tag":"formal, goods","definition":"A wholesale dealer, often importing or exporting; more formal and larger in scale than trader.","definitionCN":"批发商，常指进出口商；比 trader 更正式、规模更大。"},{"word":"dealer","ipa":"/ˈdiːlə/","tag":"buys to resell","definition":"A person or firm that buys goods in order to sell them, common in cars, art and securities.","definitionCN":"买进货物再出售的个人或公司，常见于汽车、艺术品与证券。"},{"word":"broker","ipa":"/ˈbrəʊkə/","tag":"acts for others","definition":"An intermediary who arranges a deal for a fee rather than owning the goods.","definitionCN":"收取费用替他人安排交易的中介，并不拥有货物。"},{"word":"vendor","ipa":"/ˈvendə/","tag":"the selling side","definition":"The party that sells in a particular transaction, often used in law and on the street.","definitionCN":"某一笔交易中的卖方，常用于法律文书与街头场景。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Trade plus er: the one who lives by buying and selling.","cn":"「买卖」加施事后缀：靠买进卖出为生的人。"},{"en":"The family runs trade, trading, trader, tradesman and tradeable.","cn":"同族词包括 trade、trading、trader、tradesman 与 tradeable。"},{"en":"Fixed phrases mark the market and the street: currency trader, commodity trader, street trader.","cn":"固定搭配标出市场与街头两面：外汇交易员、大宗商品交易商、街头小贩。"},{"en":"Keep trader and traitor apart: one deals, the other hands over what should be kept.","cn":"把商人与叛徒分开：一个做买卖，一个把该守住的东西交出去。"},{"en":"A trader stands beside the goods, whether the goods are crates or screens.","cn":"商人站在货物旁边，无论货物是木箱还是屏幕。"}],"abstract":[{"en":"Picture a hand that never stops passing objects across a table.","cn":"想象一只手不停地从桌子这头把东西递到那头。"},{"en":"Picture a person whose shadow is a price tag.","cn":"想象一个人的影子是一张价签。"},{"en":"Picture two market stalls facing each other, and one figure walking between them all day.","cn":"想象两个相对的摊位，一个人整天在其间来回走动。"}]},"examples":[{"en":"The trader keeps a record of every cargo he handles.","cn":"这名商人记录他经手的每一批货物。"},{"en":"A bond trader can move millions before the market opens.","cn":"债券交易员能在开市前调动数百万资金。"},{"en":"The street trader pays a small fee for the pitch.","cn":"街头小贩为这个摊位付一小笔费用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「trade（买卖）+ er（人）」——靠买进卖出为生的人 → 商人、交易员","word":"trader"},"root":"trade 来自中古低地德语 trade「路径、行程、生活方式」，后收窄为买卖之义；加本族施事后缀 -er 成为 trader。来源属日耳曼语，无拉丁词根。","sensesIntro":{"en":"Eight senses follow one dealer: a general buyer and seller, a market professional, a stall keeper, a commodity house, a day speculator, a specialist in one good, a trader in favors and a merchant on a long route.","cn":"八个义项沿同一个买卖者展开：一般的买进卖出者、市场专业人员、摊位小贩、大宗商品商、短线投机者、专做一类货物的人、拿人情做交换的人，以及长途路线上的商人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a figure beside a screen with a telephone and a stack of dealing slips.","cn":"核心意象：一个人守在屏幕旁，手边有电话与一叠成交单。"},"chain":["BUY AND SELL","LIVE BY DEALING","DO IT AT SPEED","DO IT ON THE STREET","DO IT IN ONE GOOD","TRADE ANYTHING"],"branches":[{"senses":"01 · 03","en":"THE SAME PERSON IN TWO PLACES: a general dealer and a stall keeper differ only in the size of the counter.","cn":"同一个人在两个地方：一般商人与摊位小贩的差别只在于柜台大小。"},{"senses":"02 · 05","en":"SPEED: a market professional and a day speculator are the same role at different time scales.","cn":"速度：市场专业人员与当日投机者是同一角色在不同时间尺度上。"},{"senses":"04 · 06","en":"CARGO AND SPECIALITY: heavy goods need ships, and one kind of goods gives the trader a name.","cn":"货物与专长：沉重的货物需要船，而某一类货物给了商人一个名号。"},{"senses":"07","en":"NO GOODS AT ALL: favors and rumors can be traded like crates.","cn":"根本没有货物：人情与传闻也能像木箱一样被买卖。"},{"senses":"08","en":"DISTANCE: the oldest trader is the one who carries goods between far places.","cn":"距离：最古老的商人，是在远方之间运送货物的人。"}]},"affixes":{"intro":{"en":"The word is a Germanic noun of path and practice plus the native ending for a person, so it reads as one whose course of life is dealing.","cn":"这个词由日耳曼语中表示「路径与行当」的名词，加本族表示人的词尾构成，读作「以买卖为行当的人」。"},"latinIntro":{"en":"There is no Latin root in this word; trade is Germanic and the ending is native, so the Latin entries stay empty.","cn":"这个词没有拉丁词根；trade 属日耳曼语，词尾是本族成分，因此拉丁语词形一栏留空。"},"items":[{"word":"trade","structure":"Middle Low German trade (track, course)","meaning":"a path; a craft; buying and selling","meaningCN":"路径；行当；买卖","example":"Trade began as a word for a way of life.","exampleCN":"这个词最初指一种生活方式。"},{"word":"-er","structure":"-er (native agent suffix)","meaning":"one who does something","meaningCN":"做某事的人","example":"The ending turns a practice into a practitioner.","exampleCN":"这个后缀把一种行当变成从业者。"},{"word":"trader","structure":"trade + -er","meaning":"one who deals","meaningCN":"做买卖的人","example":"The trader buys the crop at the gate.","exampleCN":"商人在农场门口买下收成。"},{"word":"trading","structure":"trade + -ing (verbal noun)","meaning":"the activity of dealing","meaningCN":"买卖活动","example":"Trading stopped when the storm cut the road.","exampleCN":"暴风雨切断道路后，买卖停了下来。"},{"word":"tradesman","structure":"trade + -s + man","meaning":"a skilled worker or shopkeeper","meaningCN":"手艺人；小店店主","example":"The tradesman repaired the roof himself.","exampleCN":"这位手艺人自己修了屋顶。"},{"word":"tradeable","structure":"trade + -able (fit to be)","meaning":"able to be bought and sold","meaningCN":"可交易的","example":"Only graded grain is tradeable on the exchange.","exampleCN":"只有分级的谷物才能在交易所交易。"},{"word":"merchant","structure":"Latin mercari (to trade), through Old French marchant","meaning":"a wholesale dealer","meaningCN":"批发商","example":"A merchant ships the cloth abroad.","exampleCN":"批发商把布匹运往海外。"},{"word":"deal","structure":"Old English dælan (to divide, share)","meaning":"to buy and sell","meaningCN":"买卖；交易","example":"They deal in used machinery.","exampleCN":"他们做二手机械的买卖。"},{"word":"exchange","structure":"Latin excambiare, from cambire (to swap)","meaning":"a market where goods or claims are traded","meaningCN":"交易所；交换","example":"The exchange sets a price every morning.","exampleCN":"交易所每天早上定出一个价格。"}],"latinEntries":[]}},{"word":"trading","ipa_uk":"/ˈtreɪdɪŋ/","ipa_us":"/ˈtreɪdɪŋ/","definition_zh":"交易；买卖活动；（证券）交易时段","definition_en":"the activity of buying and selling goods, currencies or securities, or a period when such activity takes place","core_image":"交易大厅的屏幕上数字不断跳动，成排的桌子前坐着下单的人，电话线在桌面下缠绕","scene":"交易大厅的屏幕上数字不断跳动，成排的桌子前坐着下单的人。Trading was halted for an hour after the price jumped.","sceneCN":"这里这个词指「买卖活动本身」（第 1 个义项：买进卖出的活动）；句意为价格暴涨之后，交易暂停了一小时。图中可辨识物件：报价屏幕、成排交易桌、电话线、下单记录。","pos":[{"tag":"n.","zh":"交易；买卖活动（不可数）"},{"tag":"adj.","zh":"交易的；从事买卖的（作定语，如贸易公司）"}],"collocations":[{"phrase":"trading volume","zh":"交易量"},{"phrase":"trading session","zh":"交易时段"},{"phrase":"trading floor","zh":"交易大厅"},{"phrase":"trading partner","zh":"贸易伙伴"},{"phrase":"insider trading","zh":"内幕交易"},{"phrase":"emissions trading","zh":"排放权交易"}],"forms":[{"label":"不可数名词","form":"trading"},{"label":"动词原形","form":"trade"},{"label":"动词三单","form":"trades"},{"label":"动词过去式","form":"traded"},{"label":"名词（贸易）","form":"trade"},{"label":"名词（商人）","form":"trader"}],"derivatives":[{"word":"trade","pos":"n./v.","zh":"贸易；交易；买卖"},{"word":"trader","pos":"n.","zh":"商人；交易员"},{"word":"tradeable","pos":"adj.","zh":"可交易的"},{"word":"trading floor","pos":"n.","zh":"交易大厅（固定说法）"},{"word":"trading post","pos":"n.","zh":"交易站；商站（历史用法）"}],"senses":[{"no":"01","title":"Buying and selling as an activity","titleCN":"作为活动的买进与卖出","definition":"the general activity of exchanging goods or claims for money","definitionCN":"用货物或权益换取金钱的一般活动","example":"Trading on the market was quiet all morning.","exampleCN":"整个上午市场的交易都很清淡。","why":"The noun simply names the activity that the verb performs.","whyCN":"这个名词只是给动词所做的事起了一个名字。"},{"no":"02","title":"One session of a market","titleCN":"市场的一个交易时段","definition":"the hours during which an exchange is open and deals may be made","definitionCN":"交易所开门、可以成交的那几个小时","example":"Trading opens at nine and closes at four.","exampleCN":"交易在九点开始，四点结束。","why":"An activity confined to hours becomes a countable session with a bell.","whyCN":"被限定在几个小时内的活动，变成了带开市铃的一个时段。"},{"no":"03","title":"The volume of deals done","titleCN":"成交的数量","definition":"the total amount bought and sold in a period","definitionCN":"某一时期内买进与卖出的总量","example":"Trading volume doubled after the report was published.","exampleCN":"报告发布之后，交易量翻了一倍。","why":"Once counted, the activity becomes a number that can rise and fall.","whyCN":"一旦被计数，这个活动就变成一个可以涨落的数字。"},{"no":"04","title":"The business of a trading company","titleCN":"贸易公司的业务","definition":"the commercial operations of a firm that buys and sells goods","definitionCN":"一家买进卖出货物的公司的商业运作","example":"The trading arm of the group handles all exports.","exampleCN":"集团的贸易部门负责所有出口。","why":"A company can be named after its activity, and the activity then means its operations.","whyCN":"一家公司可以按它的活动来命名，而这个活动就指它的业务。"},{"no":"05","title":"Insider trading as an offence","titleCN":"作为违法行为的内幕交易","definition":"dealing in shares by someone who uses information not yet public","definitionCN":"利用尚未公开的信息买卖股票的行为","example":"Insider trading carries heavy penalties in most markets.","exampleCN":"在大多数市场，内幕交易会招致重罚。","why":"The neutral activity takes on a moral colour when the information is stolen.","whyCN":"当信息是偷来的，这个中性的活动就带上道德色彩。"},{"no":"06","title":"Trading between partner countries or firms","titleCN":"伙伴国家或公司之间的贸易","definition":"the continuing exchange between two economies or two businesses","definitionCN":"两个经济体或两家企业之间持续进行的交换","example":"The two countries became trading partners after the treaty.","exampleCN":"条约签订后，两国成了贸易伙伴。","why":"The activity becomes a relationship when it repeats between the same two sides.","whyCN":"当同样的两方反复进行，这个活动就变成一种关系。"},{"no":"07","title":"Trading in permits or allowances","titleCN":"许可证或配额的交易","definition":"a system in which rights to emit or to use a resource are bought and sold","definitionCN":"买卖排放或使用某种资源的权利的制度","example":"Emissions trading sets a price on every ton of carbon.","exampleCN":"排放权交易给每吨碳定了一个价格。","why":"The thing traded need not be a good at all; a right can be sold like a crate.","whyCN":"被买卖的东西根本不必是货物；一项权利也能像木箱一样出售。"},{"no":"08","title":"Dealing as a way of life","titleCN":"作为一种生计的买卖","definition":"the occupation of a person or a community that lives by exchange","definitionCN":"靠交换为生的个人或群体的职业","example":"Trading was the family's only livelihood for three generations.","exampleCN":"买卖这家做了三代人，是唯一的生计。","why":"This is the old sense of a course of life, still visible behind the modern market word.","whyCN":"这是「生活方式」的旧义，仍隐约可见于现代的市场词背后。"}],"etymology":{"intro":{"en":"Trading is the noun of trade, a Germanic word that first meant a track or a course of life and later the business of exchange.","cn":"trading 是 trade 的名词形式，后者属日耳曼语，最初指「路径、生活方式」，后来指交换这种行业。"},"items":[{"era":"MIDDLE LOW GERMAN TRADE","en":"Trade meant a track or a course, and it entered English from the Low Countries.","cn":"trade 意为「路径、行程」，从低地国家传入英语。"},{"era":"MIDDLE ENGLISH TRADE","en":"In Middle English the word covered a habitual path, a craft and the practice of a calling.","cn":"在中古英语中，这个词涵盖惯常路径、手艺以及一门行当的做法。"},{"era":"COMMERCE SENSE","en":"By the sixteenth century the word had narrowed to buying and selling, and the verbal noun followed.","cn":"到十六世纪，这个词收窄为买卖，其动名词形式也随之出现。"},{"era":"MARKET SESSIONS","en":"Organized exchanges gave trading fixed hours, and the word came to name a session as well as an activity.","cn":"有组织的交易所给交易定下固定时间，这个词于是既指活动，也指一个时段。"},{"era":"REGULATED TRADING","en":"Modern law added phrases such as insider trading, where the activity is named in order to be restricted.","cn":"现代法律加上「内幕交易」这类说法，活动被命名正是为了加以限制。"},{"era":"PERMIT MARKETS","en":"Late twentieth-century policy created markets in emission allowances, extending the word to rights rather than goods.","cn":"二十世纪后期的政策创造出排放配额市场，把这个词扩展到权利而非货物上。"}]},"similar":{"note":{"en":"The first group holds the activity, its base and two look-alikes; the second holds broader words for commerce.","cn":"第一组是这项活动、它的词基与两个形近词；第二组是更宽泛的商业词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"trade","ipa":"/treɪd/","tag":"base noun and verb","definition":"The activity or the act of dealing; trading is its verbal noun, used especially of markets.","definitionCN":"买卖这一行业或一次买卖；trading 是它的动名词，尤用于市场。"},{"word":"trader","ipa":"/ˈtreɪdə/","tag":"the person","definition":"One who deals; the person is named, not the activity.","definitionCN":"做买卖的人；这里命名的是人，不是活动。"},{"word":"tread","ipa":"/tred/","tag":"different root","definition":"To step or walk, from Old English tredan; the spelling is close but it has no commercial sense.","definitionCN":"踩踏、行走，来自古英语 tredan；拼写相近，但没有商业义。"},{"word":"trade-off","ipa":"/ˈtreɪd ɒf/","tag":"a balance, not dealing","definition":"A compromise in which one benefit is given up for another; it shares the word trade but not the market sense.","definitionCN":"为得到一项好处而放弃另一项的折中；它含有 trade，但不是市场义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"commerce","ipa":"/ˈkɒmɜːs/","tag":"large-scale exchange","definition":"Trade on a large scale, especially between countries; broader and more formal than trading.","definitionCN":"大规模贸易，尤指国与国之间；比 trading 更宽、更正式。"},{"word":"dealing","ipa":"/ˈdiːlɪŋ/","tag":"day-to-day deals","definition":"The activity of making deals, often used of securities or of a person's conduct.","definitionCN":"做交易的活动，常用于证券或某人的行事方式。"},{"word":"business","ipa":"/ˈbɪznəs/","tag":"the whole enterprise","definition":"Commercial activity in general, including production, finance and employment.","definitionCN":"泛指商业活动，包括生产、金融与雇用。"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","tag":"one swap or a market","definition":"A single act of swapping, or the place where swaps are organized.","definitionCN":"一次交换行为，或组织交换的场所。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Trade plus ing: the activity itself, with the noun ending naming what is done.","cn":"「买卖」加动名词词尾：活动本身，词尾命名所做的事。"},{"en":"The family runs trade, trading, trader and tradeable.","cn":"同族词包括 trade、trading、trader 与 tradeable。"},{"en":"Fixed phrases mark the market and the law: trading volume, trading session, insider trading.","cn":"固定搭配标出市场与法律两面：交易量、交易时段、内幕交易。"},{"en":"Trading is the river; a trader is a boat on it; trade is the water.","cn":"trading 是河流，trader 是河上的船，trade 是水本身。"},{"en":"Permits, carbon tons and shares can all be traded, so the thing sold need not be a product.","cn":"许可证、碳吨数与股票都能交易，所以被卖的东西不必是产品。"}],"abstract":[{"en":"Picture a bell that starts a river flowing and stops it again at four.","cn":"想象一口钟让一条河开始流动，又在四点把它停住。"},{"en":"Picture numbers breathing in and out on a screen, in and out, all day.","cn":"想象屏幕上的数字整天一呼一吸。"},{"en":"Picture a right to pollute folded into a paper slip and sold like a ticket.","cn":"想象一项排放权被折成一张纸片，像票一样卖掉。"}]},"examples":[{"en":"Trading resumes when the exchange reopens.","cn":"交易所重新开市时，交易恢复。"},{"en":"The firm moved its trading desk to a smaller office.","cn":"这家公司把交易台搬到了更小的办公室。"},{"en":"Carbon trading turns an allowance into a price.","cn":"碳交易把一项配额变成一个价格。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「trade（买卖）+ ing（正在进行）」——正在进行的买进卖出 → 交易活动、交易时段","word":"trading"},"root":"trade 来自中古低地德语 trade「路径、行程」，后收窄为买卖；加动名词词尾 -ing 成为 trading。来源属日耳曼语，无拉丁词根。","sensesIntro":{"en":"Eight senses follow one activity: buying and selling in general, a session with a bell, the volume done, a company's operations, an illegal use of private information, a partnership between two sides, a market in permits, and dealing as a livelihood.","cn":"八个义项沿同一项活动展开：一般的买进卖出、带开市铃的时段、成交的数量、公司的业务、非法利用内部信息、两方之间的伙伴关系、许可证市场，以及作为生计的买卖。"},"semanticMap":{"core":{"en":"CORE IMAGE: a screen whose numbers move while rows of desks below take orders.","cn":"核心意象：屏幕上数字跳动，下方成排的桌子在接单。"},"chain":["LIVE BY BUYING AND SELLING","DO IT IN HOURS","COUNT WHAT IS DONE","RUN A COMPANY ON IT","USE SECRETS","TRADE RIGHTS"],"branches":[{"senses":"01 · 08","en":"THE ACTIVITY AND THE LIVELIHOOD: what is done in a market and what a family lives on are one activity at two depths.","cn":"活动与生计：市场里所做的事与一家人赖以生活的事，是同一活动的两个深度。"},{"senses":"02 · 03","en":"TIME AND AMOUNT: a session and a volume are the activity measured in hours and in quantity.","cn":"时间与数量：时段与交易量，是把同一活动按时长和按数量来量。"},{"senses":"04","en":"THE FIRM: a company's operations are the activity given an owner.","cn":"公司：企业的业务就是这项活动有了主人。"},{"senses":"05 · 07","en":"THINGS THAT SHOULD NOT BE SOLD: private information and a right to pollute both test what may be traded.","cn":"不该被卖的东西：内部信息与排放权，都在试探什么可以交易。"},{"senses":"06","en":"A LASTING RELATION: repeated exchange between the same two sides becomes a partnership.","cn":"持久的关系：同样两方反复交换，就变成伙伴关系。"}]},"affixes":{"intro":{"en":"The word is a Germanic noun of path and practice with the native ending that turns an action into an activity.","cn":"这个词由日耳曼语中表示「路径与行当」的名词，加本族把动作变为活动的词尾构成。"},"latinIntro":{"en":"No Latin root is present here; trade is Germanic and the ending is native, so the Latin entries stay empty.","cn":"这里没有拉丁词根；trade 属日耳曼语，词尾是本族成分，因此拉丁语词形一栏留空。"},"items":[{"word":"trade","structure":"Middle Low German trade (track, course)","meaning":"a path; buying and selling","meaningCN":"路径；买卖","example":"Trade once meant a way of life.","exampleCN":"这个词曾指一种生活方式。"},{"word":"-ing","structure":"-ing (native verbal noun ending)","meaning":"the activity of doing","meaningCN":"做某事这一活动","example":"The ending turns a verb into ongoing activity.","exampleCN":"这个后缀把动词变成持续的活动。"},{"word":"trading","structure":"trade + -ing","meaning":"the activity of dealing","meaningCN":"买卖活动","example":"Trading continues through the afternoon.","exampleCN":"交易持续整个下午。"},{"word":"trader","structure":"trade + -er (agent)","meaning":"one who deals","meaningCN":"做买卖的人","example":"Every trader keeps a record.","exampleCN":"每个交易者都保留记录。"},{"word":"tradeable","structure":"trade + -able (fit to be)","meaning":"able to be traded","meaningCN":"可交易的","example":"The allowance is tradeable between firms.","exampleCN":"这项配额可以在企业之间交易。"},{"word":"session","structure":"Latin sessio, from sedere (to sit)","meaning":"a period of sitting or activity","meaningCN":"一段坐着的时期；一场","example":"The morning session sets the tone.","exampleCN":"上午的时段定下基调。"},{"word":"volume","structure":"Latin volumen (a roll, a book)","meaning":"an amount or quantity","meaningCN":"数量；体量","example":"Volume measures how much changed hands.","exampleCN":"交易量衡量有多少易手。"},{"word":"insider","structure":"inside + -er (one within)","meaning":"a person with private access","meaningCN":"内部人员","example":"An insider knew before the public did.","exampleCN":"内部人员比公众先知道。"},{"word":"emission","structure":"Latin emittere (to send out)","meaning":"the release of a substance","meaningCN":"排放；散发","example":"Each plant receives an emission allowance.","exampleCN":"每座工厂得到一份排放配额。"}],"latinEntries":[]}},{"word":"international trade","ipa_uk":"/ɪnˌtɜːnæʃənl ˈtreɪd/","ipa_us":"/ɪnˌtɜːrnæʃənl ˈtreɪd/","definition_zh":"国际贸易；跨越国界的货物与服务交换","definition_en":"the exchange of goods and services across national borders","core_image":"港口堆着成排集装箱，吊机把箱子从船上移到岸上，报关单在窗口逐个盖章","scene":"港口堆着成排集装箱，吊机把箱子从一艘船移到岸上，报关单在窗口盖章。International trade grew faster than output for most of the last century.","sceneCN":"这里这个词组指「跨国界的货物交换」（第 1 个义项：货物跨境买卖）；句意为在上个世纪的大部分时间里，国际贸易的增长快于产出。图中可辨识物件：集装箱、吊机、货船、报关窗口的印章。","pos":[{"tag":"n.","zh":"国际贸易（不可数）"}],"collocations":[{"phrase":"international trade law","zh":"国际贸易法"},{"phrase":"international trade agreement","zh":"国际贸易协定"},{"phrase":"international trade in services","zh":"国际服务贸易"},{"phrase":"international trade statistics","zh":"国际贸易统计"},{"phrase":"barriers to international trade","zh":"国际贸易壁垒"},{"phrase":"international trade organization","zh":"国际贸易组织"}],"forms":[{"label":"不可数名词","form":"international trade"},{"label":"相关形容词","form":"international"},{"label":"相关名词（贸易）","form":"trade"},{"label":"相关名词（出口商）","form":"exporter"},{"label":"相关名词（进口商）","form":"importer"},{"label":"相关名词（贸易差额）","form":"trade balance"}],"derivatives":[{"word":"trade","pos":"n./v.","zh":"贸易；交易"},{"word":"international","pos":"adj.","zh":"国际的"},{"word":"internationalize","pos":"v.","zh":"使国际化"},{"word":"exporter","pos":"n.","zh":"出口商"},{"word":"importer","pos":"n.","zh":"进口商"}],"senses":[{"no":"01","title":"Cross-border exchange of goods","titleCN":"跨越国界的货物交换","definition":"the buying and selling of physical goods between countries","definitionCN":"国家之间对实物货物的买进与卖出","example":"International trade in grain depends on port capacity.","exampleCN":"谷物的国际贸易取决于港口吞吐能力。","why":"Two words say it plainly: trade that crosses between nations.","whyCN":"两个词把意思说得很直白：在国家之间越过的买卖。"},{"no":"02","title":"Trade in services across borders","titleCN":"跨越国界的服务贸易","definition":"the sale of transport, finance, tourism or advice between countries","definitionCN":"国家之间出售运输、金融、旅游或咨询","example":"International trade in services now exceeds trade in many goods.","exampleCN":"服务贸易如今超过了许多货物的贸易。","why":"A service can be exported without a crate, and the phrase still applies.","whyCN":"服务不需要木箱也能出口，而这个短语仍然适用。"},{"no":"03","title":"The rules and institutions of trade","titleCN":"贸易的规则与机构","definition":"the laws, treaties and bodies that govern exchange between countries","definitionCN":"管理国家间交换的法律、条约与机构","example":"International trade law governs the dispute over the shipment.","exampleCN":"国际贸易法管辖这起货物运输纠纷。","why":"Once trade crosses borders, it needs rules, and the phrase names the whole regime.","whyCN":"一旦贸易越过国界，就需要规则，这个短语于是指整套制度。"},{"no":"04","title":"The balance of exports and imports","titleCN":"出口与进口的差额","definition":"the difference between what a country sells abroad and what it buys","definitionCN":"一国卖到国外与从国外买入之间的差额","example":"The trade balance turned negative after energy prices rose.","exampleCN":"能源价格上涨之后，贸易差额转为逆差。","why":"Two flows in opposite directions invite a subtraction, and the balance is that result.","whyCN":"两股方向相反的流自然引出减法，差额就是那个结果。"},{"no":"05","title":"Agreements that open or close markets","titleCN":"打开或关闭市场的协定","definition":"treaties that lower barriers or set quotas between signatory countries","definitionCN":"在签署国之间降低壁垒或设定配额的条约","example":"The new agreement reshaped international trade in machinery.","exampleCN":"新协定重塑了机械领域的国际贸易。","why":"Governments bargain over access, and the agreement becomes part of what the phrase covers.","whyCN":"各国政府为市场准入而谈判，协定就成了这个短语所涵盖的一部分。"},{"no":"06","title":"The theory of why countries exchange","titleCN":"解释各国为何交换的理论","definition":"the economic study of specialization and comparative advantage between nations","definitionCN":"研究国家之间专业化与比较优势的经济学问","example":"The course begins with the theory of international trade.","exampleCN":"这门课从国际贸易理论讲起。","why":"The phenomenon becomes an object of study, and the phrase names the field.","whyCN":"这一现象成为研究对象，这个短语就成了学科名。"},{"no":"07","title":"Recorded flows in statistics","titleCN":"统计中记录的流动","definition":"the measured value of goods and services exchanged, published as data","definitionCN":"被测量并公布为数据的货物与服务交换值","example":"International trade statistics are revised every quarter.","exampleCN":"国际贸易统计数据每季度修订一次。","why":"Customs records turn millions of shipments into aggregate flows.","whyCN":"海关记录把数以百万计的货运变成汇总的流动。"},{"no":"08","title":"Exchange of ideas and culture","titleCN":"思想与文化的交流","definition":"the movement of knowledge, styles and people across borders, described as trade","definitionCN":"知识、风格与人的跨境流动，被以「贸易」来描述","example":"Historians speak of an international trade in ideas along the caravan roads.","exampleCN":"历史学家谈到商队道路上思想的国家间交流。","why":"The phrase can be borrowed for anything that travels and is exchanged.","whyCN":"这个短语可被借去指任何会旅行并被交换的东西。"}],"etymology":{"intro":{"en":"The phrase joins international, coined in the eighteenth century from Latin inter between and natio birth, with trade, a Germanic word for a course of life that became commerce.","cn":"这个短语把 international 与 trade 组合起来。international 是十八世纪用拉丁语 inter「之间」与 natio「出生」造出的词；trade 是日耳曼语词，本指生活方式，后转为商业。"},"items":[{"era":"LATIN NATIO","en":"Natio meant a birth or a people born together, from nasci, to be born.","cn":"natio 意为「出生、同源而生的一群人」，来自 nasci「出生」。"},{"era":"LATIN INTER","en":"Inter meant between or among, and it remains the first element of many modern compounds.","cn":"inter 意为「在……之间」，至今仍是许多现代复合词的第一部分。"},{"era":"ENGLISH INTERNATIONAL","en":"The adjective was coined in the late eighteenth century to mean between nations, and it spread with the growth of treaties and trade.","cn":"这个形容词在十八世纪后期被造出，意为「国家之间的」，随条约与贸易的发展而普及。"},{"era":"GERMANIC TRADE","en":"Trade came into English meaning a track or a way of life, and later narrowed to buying and selling.","cn":"trade 进入英语时指路径或生活方式，后来收窄为买进卖出。"},{"era":"THE COMPOUND","en":"The two words joined once goods began to be counted across borders rather than only at local markets.","cn":"当货物开始被按跨境而非仅按本地市场统计时，这两个词走到了一起。"},{"era":"GLOBAL SYSTEM","en":"In the twentieth century the phrase came to name a system of rules, statistics and institutions, not only the shipments themselves.","cn":"到二十世纪，这个短语指一套规则、统计与机构，而不只是货运本身。"}]},"similar":{"note":{"en":"The first group holds the parts of the phrase and one prefix look-alike; the second holds other names for trade between countries.","cn":"第一组是短语的组成部分与一个前缀形近词；第二组是国家间贸易的其他叫法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"international","ipa":"/ɪnˌtɜːnæʃənl/","tag":"the adjective","definition":"Between nations; it can describe law, sport or trade, and does not by itself mean commerce.","definitionCN":"国家之间的；可修饰法律、体育或贸易，本身并不指商业。"},{"word":"nation","ipa":"/ˈneɪʃn/","tag":"the unit","definition":"A people or a state; it is the unit across which the trade moves.","definitionCN":"一个民族或国家；它正是贸易所跨过的单位。"},{"word":"trade","ipa":"/treɪd/","tag":"the activity","definition":"Buying and selling in general; the longer phrase only adds the crossing of borders.","definitionCN":"泛指买进卖出；较长的短语只是加上了「跨越国界」。"},{"word":"internal","ipa":"/ɪnˈtɜːnl/","tag":"different prefix","definition":"Inside a country or an organization, from intra- within; it is the opposite of international in trade talk.","definitionCN":"在一国或一个组织之内，来自 intra-「在内」；在贸易话题中正是国际的反面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"foreign trade","ipa":"/ˈfɒrən treɪd/","tag":"seen from one country","definition":"A single country's trade with others; the phrase takes the viewpoint of one state, not the system.","definitionCN":"某一国与其他国家的贸易；它取一国的视角，而非整个体系。"},{"word":"global trade","ipa":"/ˌɡləʊbl ˈtreɪd/","tag":"the whole world","definition":"Trade considered as one worldwide network rather than as relations between nations.","definitionCN":"把贸易看作一个全球网络，而非国家之间的关系。"},{"word":"commerce","ipa":"/ˈkɒmɜːs/","tag":"large-scale exchange","definition":"Trade on a large scale; it may be internal as well as international.","definitionCN":"大规模贸易；既可以是国际的，也可以是一国之内的。"},{"word":"export trade","ipa":"/ɪkˈspɔːt treɪd/","tag":"one direction","definition":"The half of the exchange that sells abroad; the full phrase covers both directions.","definitionCN":"交换中向外出售的那一半；完整短语涵盖两个方向。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"International plus trade: buying and selling that crosses a border.","cn":"「国家之间的」加「买卖」：越过边界的买进卖出。"},{"en":"The parts are nation, inter- and trade, each with its own history.","cn":"组成部分是「国家」「之间」与「买卖」，各有一段自己的历史。"},{"en":"Fixed phrases mark law, services and statistics: international trade law, trade in services, trade statistics.","cn":"固定搭配标出法律、服务与统计：国际贸易法、服务贸易、贸易统计。"},{"en":"Keep international and internal apart: one crosses out, one stays in.","cn":"把「国际」与「内部」分开：一个跨出去，一个留在里面。"},{"en":"A container crane lifting a box from ship to shore is the visible unit of the whole system.","cn":"吊机把集装箱从船移到岸，就是整个体系可见的单位。"}],"abstract":[{"en":"Picture two countries as two rooms with a door that only opens outward.","cn":"想象两个国家像两个房间，中间一扇门只朝外开。"},{"en":"Picture a map where borders are drawn as thin lines that goods must step over.","cn":"想象一张地图，边界被画成货物必须跨过的细线。"},{"en":"Picture a ledger with two columns, one for what leaves and one for what arrives.","cn":"想象一本账簿有两栏，一栏记出去的，一栏记进来的。"}]},"examples":[{"en":"International trade slowed when the shipping lanes closed.","cn":"航道关闭时，国际贸易放缓。"},{"en":"The course covers international trade and its legal framework.","cn":"这门课讲授国际贸易及其法律框架。"},{"en":"Services now make up a larger share of international trade.","cn":"服务现在占国际贸易的更大比重。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「国家之间（international）的买卖（trade）」——货物与服务跨越国界的交换 → 国际贸易","word":"international trade"},"root":"international 由拉丁语 inter「之间」与 natio「出生、族群」构成，十八世纪后期造出；trade 来自日耳曼语，本指路径与生活方式，后指买卖。","sensesIntro":{"en":"Eight senses follow one flow across a border: goods, services, the rules, the balance, the agreements, the theory, the statistics and finally ideas carried along the same roads.","cn":"八个义项沿同一股跨境流动展开：货物、服务、规则、差额、协定、理论、统计，最后是沿着同一条路走的思想。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crane lifting a container from a ship while a customs officer stamps a form.","cn":"核心意象：吊机把集装箱从船上吊起，海关关员同时在报关单上盖章。"},"chain":["CROSS A BORDER","GOODS MOVE","SERVICES MOVE","RULES ARE WRITTEN","FLOWS ARE COUNTED","IDEAS TRAVEL TOO"],"branches":[{"senses":"01 · 02","en":"WHAT MOVES: a crate and a service are two forms of the same export.","cn":"移动的东西：木箱与服务是同一种出口的两种形态。"},{"senses":"03 · 05","en":"THE RULES: law and agreements are the border turned into text.","cn":"规则：法律与协定就是把边界写成了文字。"},{"senses":"04","en":"THE BALANCE: two opposite flows invite a subtraction.","cn":"差额：两股相反的流自然引出减法。"},{"senses":"06","en":"THE THEORY: the flow becomes an object of study.","cn":"理论：这股流动成为研究对象。"},{"senses":"07 · 08","en":"COUNTED AND BORROWED: statistics turn shipments into data, and the phrase stretches to ideas.","cn":"被计数与被借用：统计把货运变成数据，短语又被拉到思想上。"}]},"affixes":{"intro":{"en":"The phrase is a Latin-built adjective of betweenness plus a Germanic noun of practice, so it reads as dealing that goes between nations.","cn":"这个短语由一个用拉丁语成分构成的「之间」形容词加一个日耳曼语表示行当的名词组成，读作「在国家之间进行的买卖」。"},"latinIntro":{"en":"Latin inter and natio build international; trade itself is Germanic and brings no Latin root.","cn":"拉丁语 inter 与 natio 构成 international；trade 本身属日耳曼语，不带来拉丁词根。"},"items":[{"word":"inter-","structure":"inter- (Latin prefix, between)","meaning":"between; among","meaningCN":"在……之间","example":"The prefix places the action between two parties.","exampleCN":"这个前缀把动作放在两方之间。"},{"word":"natio","structure":"natio, -onis (f., third declension; Latin)","meaning":"a birth; a people","meaningCN":"出生；族群","example":"The noun gives the word its unit of belonging.","exampleCN":"这个名词提供「归属单位」这一层。"},{"word":"international","structure":"inter- + nation + -al","meaning":"between nations","meaningCN":"国家之间的","example":"The rule applies to international shipments.","exampleCN":"这条规则适用于国际货运。"},{"word":"trade","structure":"Middle Low German trade (track, course)","meaning":"buying and selling","meaningCN":"买卖；贸易","example":"Trade moved along the river for centuries.","exampleCN":"几百年来贸易沿着这条河进行。"},{"word":"international trade","structure":"international + trade","meaning":"exchange across borders","meaningCN":"跨境交换","example":"International trade needs ports and paperwork.","exampleCN":"国际贸易需要港口与文书。"},{"word":"exporter","structure":"export + -er (agent)","meaning":"one who sells abroad","meaningCN":"出口商","example":"The exporter bears the freight cost.","exampleCN":"出口商承担运费。"},{"word":"importer","structure":"import + -er (agent)","meaning":"one who buys from abroad","meaningCN":"进口商","example":"The importer clears the goods at customs.","exampleCN":"进口商在海关清关。"},{"word":"balance","structure":"Latin bilanx (two scales)","meaning":"a difference between two sides","meaningCN":"两边的差额","example":"The trade balance compares two flows.","exampleCN":"贸易差额比较两股流动。"},{"word":"statistics","structure":"Latin statisticus, from status (state)","meaning":"collected numerical data","meaningCN":"统计数据","example":"Statistics record what crosses the border.","exampleCN":"统计记录越过边界的东西。"}],"latinEntries":[{"word":"inter","structure":"inter (Latin preposition and prefix)","meaning":"between, among","meaningCN":"在……之间"},{"word":"natio","structure":"natio, -onis (f., third declension; Latin)","meaning":"birth; a people","meaningCN":"出生；族群"}]}},{"word":"trade barrier","ipa_uk":"/ˈtreɪd ˌbæriə/","ipa_us":"/ˈtreɪd ˌbæriər/","definition_zh":"贸易壁垒；阻碍商品或服务跨境流动的措施","definition_en":"a government measure that makes it harder or costlier for goods and services to cross a border","core_image":"公路尽头立着一道横杆，横杆上挂着税率牌与检验章，卡车在横杆前排队等候","scene":"公路尽头立着一道横杆，横杆上挂着税率牌与检验章，卡车排队等候。A high tariff is the oldest form of trade barrier.","sceneCN":"这里这个词组指「妨碍跨境贸易的措施」（第 1 个义项：阻碍贸易往来的手段）；句意为高关税是最古老的贸易壁垒形式。图中可辨识物件：横杆、税率牌、检验章、排队卡车。","pos":[{"tag":"n.","zh":"贸易壁垒（可数；指一项具体措施）"}],"collocations":[{"phrase":"tariff barrier","zh":"关税壁垒"},{"phrase":"non-tariff barrier","zh":"非关税壁垒"},{"phrase":"technical trade barrier","zh":"技术性贸易壁垒"},{"phrase":"remove a trade barrier","zh":"消除贸易壁垒"},{"phrase":"raise trade barriers","zh":"提高贸易壁垒"},{"phrase":"trade barrier to entry","zh":"进入市场的贸易障碍"}],"forms":[{"label":"复数","form":"trade barriers"},{"label":"相关名词（壁垒本身）","form":"barrier"},{"label":"相关名词（关税）","form":"tariff"},{"label":"相关名词（配额）","form":"quota"},{"label":"相关名词（禁运）","form":"embargo"},{"label":"相关名词（贸易）","form":"trade"}],"derivatives":[{"word":"barrier","pos":"n.","zh":"障碍；屏障"},{"word":"tariff","pos":"n.","zh":"关税"},{"word":"quota","pos":"n.","zh":"配额"},{"word":"protectionism","pos":"n.","zh":"保护主义"},{"word":"embargo","pos":"n./v.","zh":"禁运；实施禁运"}],"senses":[{"no":"01","title":"Any measure that obstructs cross-border trade","titleCN":"妨碍跨境贸易的任何措施","definition":"a government rule whose effect is to slow or block the movement of goods between countries","definitionCN":"其效果在于减慢或阻断货物在国家间流动的政府规定","example":"Licensing rules can act as a trade barrier even without a duty.","exampleCN":"即使没有关税，许可规则也能起贸易壁垒的作用。","why":"The phrase is a picture: trade is a road, and a barrier stands across it.","whyCN":"这个短语是一幅画：贸易是一条路，一道栏杆横在路前。"},{"no":"02","title":"A tariff on imported goods","titleCN":"对进口货物征收的关税","definition":"a tax collected at the border that raises the price of foreign goods","definitionCN":"在边境征收、抬高外国货物价格的税","example":"The tariff barrier made imported steel more expensive.","exampleCN":"关税壁垒让进口钢材变得更贵。","why":"The oldest barrier is a toll gate, and a tariff is exactly a toll on goods.","whyCN":"最古老的壁垒就是收费门，而关税正是对货物收的门票钱。"},{"no":"03","title":"A quota that limits the quantity","titleCN":"限制数量的配额","definition":"a ceiling on how much of a good may enter in a period","definitionCN":"某一时期内允许进入的货物数量上限","example":"The quota barrier kept imports below last year's level.","exampleCN":"配额壁垒把进口量压在上一年水平之下。","why":"A gate may open only for a counted number of trucks, which is a barrier of quantity.","whyCN":"一道门可以只放定数的卡车通过，这是数量上的壁垒。"},{"no":"04","title":"A non-tariff barrier of paperwork","titleCN":"由文书手续构成的非关税壁垒","definition":"a requirement of forms, inspections or delays that adds cost without adding a tax","definitionCN":"通过表格、检验或拖延增加成本、却不加税的要求","example":"Endless paperwork became a non-tariff barrier in practice.","exampleCN":"没完没了的文书实际上成了非关税壁垒。","why":"A barrier can be made of time and paper rather than of stone.","whyCN":"壁垒可以由时间与纸张构成，而不必由石头构成。"},{"no":"05","title":"A safety standard used as a barrier","titleCN":"被用作壁垒的安全标准","definition":"a technical rule that is reasonable in itself but excludes foreign products in effect","definitionCN":"本身合理、实际上却把外国产品排除在外的技术规则","example":"The packaging standard was challenged as a hidden trade barrier.","exampleCN":"这项包装标准被质疑为隐蔽的贸易壁垒。","why":"A rule that looks like care can still stand across the road.","whyCN":"一条看起来像出于关照的规则，仍然可以横在路中央。"},{"no":"06","title":"A subsidy that indirectly blocks rivals","titleCN":"间接阻挡竞争者的补贴","definition":"support paid to domestic producers that makes foreign goods uncompetitive","definitionCN":"给予本国生产者的支持，使外国货物失去竞争力","example":"Farm subsidies can work as a trade barrier without any border tax.","exampleCN":"农业补贴可以在没有任何边境税的情况下充当贸易壁垒。","why":"A barrier need not face outward; lifting one side's ground has the same effect.","whyCN":"壁垒不必朝外立；把一边的地基抬高，效果相同。"},{"no":"07","title":"A barrier to entering a market","titleCN":"进入某一市场的障碍","definition":"any cost or rule that keeps a new seller out, including in a domestic market","definitionCN":"把新卖家挡在门外的任何成本或规则，包括在本国市场内","example":"The licence is a trade barrier for small importers.","exampleCN":"这项执照对小进口商来说是一道贸易障碍。","why":"The road-and-gate image is borrowed for entry in general.","whyCN":"「路与门」的画面被借去指一般的进入。"},{"no":"08","title":"A barrier removed by agreement","titleCN":"经协定拆除的壁垒","definition":"a measure that treaties commit countries to lower or abolish","definitionCN":"条约要求各国降低或废除的措施","example":"The round of talks removed one trade barrier after another.","exampleCN":"那一轮会谈拆除了一道又一道贸易壁垒。","why":"Once barriers are listed in treaties, they become objects that can be taken down.","whyCN":"当壁垒被列进条约，它们就成了可以被拆掉的对象。"}],"etymology":{"intro":{"en":"Trade barrier joins the Germanic word trade with barrier, from Old French barriere, a fence built from bars; the modern policy sense is nineteenth-century.","cn":"trade barrier 把日耳曼语的 trade 与 barrier 组合起来；barrier 来自古法语 barriere，指用横杆围成的栅栏；现代政策义出现于十九世纪。"},"items":[{"era":"OLD FRENCH BARRIERE","en":"Barriere named a fence or a gate made of bars, especially one that closed a road into a town.","cn":"barriere 指用横杆做成的栅栏或门，尤指封住进城道路的那一道。"},{"era":"VULGAR LATIN BARRA","en":"The bar itself is usually traced to a spoken Latin word barra, but that form is a reconstruction and its origin is source uncertain.","cn":"横杆本身常被追溯到口语拉丁语 barra，但该形式属重构，其来源不确定。"},{"era":"ENGLISH BARRIER","en":"English barrier first meant a physical gate or fence, and then any obstacle that stops movement.","cn":"英语 barrier 最初指实体的门或栅栏，后指任何阻挡前进的障碍。"},{"era":"TRADE BARRIER","en":"In the nineteenth century the phrase was applied to duties and rules that stood in the way of commerce between countries.","cn":"十九世纪，这个短语被用于阻挡国家间商业往来的税与规则。"},{"era":"NON-TARIFF EXTENSION","en":"After tariffs fell in the twentieth century, the phrase widened to cover standards, licences and paperwork.","cn":"二十世纪关税下降之后，这个短语扩展到标准、执照与文书手续。"},{"era":"NEGOTIATED REMOVAL","en":"Trade rounds turned the barrier into something listed, negotiated and removed clause by clause.","cn":"各轮贸易谈判把壁垒变成可以逐条列出、逐条谈掉的东西。"}]},"similar":{"note":{"en":"The first group holds the two parts of the phrase and two look-alikes; the second holds specific measures that count as barriers.","cn":"第一组是短语的两个组成部分与两个形近词；第二组是算作壁垒的具体措施。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"barrier","ipa":"/ˈbæriə/","tag":"the obstacle itself","definition":"Any fence, gate or obstacle; the longer phrase narrows it to the border of trade.","definitionCN":"任何栅栏、门或障碍；较长的短语把它收窄到贸易边界。"},{"word":"bar","ipa":"/bɑː/","tag":"the piece of the fence","definition":"A long piece of metal or wood, and a place that serves drinks; the first is the part a barrier is made of.","definitionCN":"一根长条金属或木头，也指卖酒的店；前者正是构成栅栏的部件。"},{"word":"barrister","ipa":"/ˈbɑːrɪstə/","tag":"different sense of bar","definition":"A lawyer called to the bar; the bar here is a courtroom railing, not a trade gate.","definitionCN":"取得出庭资格的律师；这里的 bar 指法庭围栏，不是贸易关卡。"},{"word":"trade","ipa":"/treɪd/","tag":"the thing blocked","definition":"Buying and selling; it supplies the first half and the thing the barrier obstructs.","definitionCN":"买进卖出；它提供短语前半，也是被阻挡的对象。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tariff","ipa":"/ˈtærɪf/","tag":"a tax at the border","definition":"A duty on imports; it is one kind of trade barrier, not the whole category.","definitionCN":"对进口征收的税；它是贸易壁垒的一种，而非整个类别。"},{"word":"quota","ipa":"/ˈkwəʊtə/","tag":"a quantity ceiling","definition":"A fixed maximum of goods allowed in; another single kind of barrier.","definitionCN":"允许进入的货物上限；另一种单一的壁垒。"},{"word":"embargo","ipa":"/ɪmˈbɑːɡəʊ/","tag":"a full stop","definition":"An official ban on trade with a particular country, the hardest form of barrier.","definitionCN":"对某一国家贸易的官方禁令，是最严厉的壁垒形式。"},{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","tag":"general limit","definition":"Any limit placed on an activity; it is broader than trade barrier and may have nothing to do with borders.","definitionCN":"对某项活动施加的任何限制；比贸易壁垒更宽，也可能与边界无关。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"Trade plus barrier: a fence drawn across the road goods must travel.","cn":"「贸易」加「栏杆」：横在货物必经之路上的栅栏。"},{"en":"The parts are trade and barrier, the second from a fence of bars.","cn":"组成部分是「贸易」与「栏杆」，后者来自用横杆围成的栅栏。"},{"en":"Fixed phrases mark the kinds: tariff barrier, non-tariff barrier, technical trade barrier.","cn":"固定搭配标出种类：关税壁垒、非关税壁垒、技术性贸易壁垒。"},{"en":"A tariff is a toll gate; a quota is a counting gate; paperwork is a gate of time.","cn":"关税是收费门，配额是计数门，文书是耗时门。"},{"en":"Any listed barrier can be negotiated down, which is why trade rounds exist.","cn":"任何被列出的壁垒都能通过谈判降低，这正是贸易谈判轮次存在的理由。"}],"abstract":[{"en":"Picture a road with a gate that charges not money but forms and days.","cn":"想象一条路，门口的收费不是钱，而是表格与天数。"},{"en":"Picture a wall built one brick at a time, each brick a separate rule.","cn":"想象一堵砖墙，每次砌一块，每块砖都是一条单独的规则。"},{"en":"Picture a gate that stands open but has a very high step.","cn":"想象一扇门敞开着，只是门槛非常高。"}]},"examples":[{"en":"The licensing system operates as a trade barrier in practice.","cn":"这套许可制度实际上起着贸易壁垒的作用。"},{"en":"Talks aimed at removing every trade barrier between the two markets.","cn":"会谈旨在拆除两个市场之间的每一道贸易壁垒。"},{"en":"A technical standard may be a legitimate safety rule or a hidden trade barrier.","cn":"一项技术标准可能是正当的安全规则，也可能是隐蔽的贸易壁垒。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「贸易（trade）路上的栏杆（barrier）」——横在跨境买卖前面的关税、配额与手续 → 贸易壁垒","word":"trade barrier"},"root":"trade 来自日耳曼语，本指路径与生活方式，后指买卖；barrier 来自古法语 barriere「横杆围成的栅栏」，其横杆的拉丁语来源属重构形式，来源不确定。","sensesIntro":{"en":"Eight senses follow one fence across a road: any obstructive measure, a tariff gate, a quota gate, a paperwork gate, a safety rule gate, a subsidy that lifts one side, a barrier to entry, and a barrier written into a treaty.","cn":"八个义项沿同一道横在路上的栅栏展开：任何阻碍性措施、关税门、配额门、文书门、安全规则门、抬高一边的补贴、进入市场的障碍，以及被写进条约的壁垒。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bar across a highway with a duty board and an inspection stamp hanging from it.","cn":"核心意象：横在公路上的一道栏杆，上面挂着税率牌与检验章。"},"chain":["A ROAD FOR GOODS","A BAR ACROSS IT","A TOLL AT THE BAR","A COUNTED NUMBER","PAPER AND STANDARDS","THE BAR TAKEN DOWN"],"branches":[{"senses":"01 · 07","en":"ANY GATE: a border measure and an entry obstacle are the same bar in two settings.","cn":"任何门：边境措施与进入障碍是同一道栏杆在两种场合。"},{"senses":"02","en":"THE TOLL: a tariff is the oldest and most visible form of the bar.","cn":"过路费：关税是最古老、最显眼的栏杆形式。"},{"senses":"03 · 04","en":"COUNTING AND PAPER: a quota and a form both stop goods by number or by time.","cn":"计数与纸张：配额与表格分别用数量和耗时挡住货物。"},{"senses":"05 · 06","en":"LOOKS HELPFUL: a safety rule and a subsidy can bar the road from behind the gate.","cn":"看似有益：安全规则与补贴可以从门后把路挡上。"},{"senses":"08","en":"REMOVED BY TREATY: once listed, the bar becomes an object negotiators can take down.","cn":"经条约拆除：一旦被列出，栏杆就成了谈判者可以拆掉的对象。"}]},"affixes":{"intro":{"en":"The phrase joins a Germanic word for dealing with a French word for a fence, so it reads as a fence standing across commerce.","cn":"这个短语把日耳曼语中表示「买卖」的词与法语中表示「栅栏」的词组合起来，读作「横在商业前面的一道栅栏」。"},"latinIntro":{"en":"Barrier goes back to a spoken Latin word for a bar, recorded only as a reconstruction, so the Latin entries are left empty here.","cn":"barrier 可追溯到口语拉丁语中表示「横杆」的词，但该词只有重构形式，因此这里把拉丁语词形一栏留空。"},"items":[{"word":"trade","structure":"Middle Low German trade (track, course)","meaning":"buying and selling","meaningCN":"买卖；贸易","example":"Trade needs open roads.","exampleCN":"贸易需要开放的道路。"},{"word":"bar","structure":"Old French barre (a rod, a bar)","meaning":"a long piece of wood or metal","meaningCN":"横杆；长条","example":"The gate is built from iron bars.","exampleCN":"这道门由铁横杆构成。"},{"word":"barrier","structure":"Old French barriere (a fence of bars)","meaning":"a fence or gate that stops passage","meaningCN":"阻挡通行的栅栏或门","example":"A barrier closed the road into the town.","exampleCN":"一道栅栏封住了进城的路。"},{"word":"trade barrier","structure":"trade + barrier","meaning":"an obstacle to cross-border commerce","meaningCN":"跨境商业的障碍","example":"The duty acted as a trade barrier.","exampleCN":"这项税起了贸易壁垒的作用。"},{"word":"tariff","structure":"Italian tariffa, from Arabic","meaning":"a duty on imports","meaningCN":"进口关税","example":"The tariff raised the price at the border.","exampleCN":"关税在边境抬高了价格。"},{"word":"quota","structure":"Latin quota (how great a part)","meaning":"a fixed share or maximum","meaningCN":"配额；上限","example":"The quota limits the number of crates.","exampleCN":"配额限制了木箱的数量。"},{"word":"embargo","structure":"Spanish embargo, from embargar (to hinder)","meaning":"an official ban on trade","meaningCN":"贸易禁令","example":"The embargo stopped all shipments.","exampleCN":"禁运停止了一切货运。"},{"word":"subsidy","structure":"Latin subsidium (help, reserve)","meaning":"support paid to producers","meaningCN":"补贴","example":"A subsidy can make imports uncompetitive.","exampleCN":"补贴可以让进口货失去竞争力。"},{"word":"standard","structure":"Old French estandart (a fixed point)","meaning":"a rule of quality or safety","meaningCN":"标准","example":"A strict standard can exclude foreign goods.","exampleCN":"严格的标准可以把外国货物排除在外。"}],"latinEntries":[]}},{"word":"tariff","ipa_uk":"/ˈtærɪf/","ipa_us":"/ˈterɪf/","definition_zh":"关税；税率表；（公用事业）价目表","definition_en":"a tax on goods entering a country, a published table of such rates, or a schedule of charges for a service","core_image":"海关窗口上贴着一张长表，每一行写着一种货物与一个百分比，关员用笔在表上划线","scene":"海关窗口上贴着一张长表，每一行写着一种货物与一个百分比，关员用笔在表上划线。The government raised the tariff on imported steel.","sceneCN":"这里这个词指「对进口货物征收的税」（第 1 个义项：进口关税）；句意为政府对进口钢材提高了关税。图中可辨识物件：长表、货物名称、百分比、关员的笔。","pos":[{"tag":"n.","zh":"关税；税率表；（水、电、通信的）价目表"},{"tag":"v.","zh":"对……征收关税；按价目表收费（较少用）"}],"collocations":[{"phrase":"import tariff","zh":"进口关税"},{"phrase":"tariff rate","zh":"关税税率"},{"phrase":"protective tariff","zh":"保护性关税"},{"phrase":"retaliatory tariff","zh":"报复性关税"},{"phrase":"tariff barrier","zh":"关税壁垒"},{"phrase":"tariff schedule","zh":"关税税则；税率表"}],"forms":[{"label":"复数","form":"tariffs"},{"label":"形容词（按关税的）","form":"tariffed"},{"label":"名词（定税率）","form":"tariffing"},{"label":"相关名词（关税，同义）","form":"duty"},{"label":"相关名词（海关）","form":"customs"},{"label":"相关名词（税率表）","form":"schedule"}],"derivatives":[{"word":"tariffed","pos":"adj.","zh":"被征收关税的"},{"word":"tariffing","pos":"n.","zh":"制定税率；按价目表收费"},{"word":"tariffless","pos":"adj.","zh":"无关税的"},{"word":"duty","pos":"n.","zh":"关税；义务"},{"word":"customs","pos":"n.","zh":"海关；关税"}],"senses":[{"no":"01","title":"A tax on imported goods","titleCN":"对进口货物征收的税","definition":"a charge collected at the border on goods coming into a country","definitionCN":"在边境对进入一国的货物收取的费用","example":"The tariff on imported steel doubled overnight.","exampleCN":"进口钢材的关税一夜之间翻了一倍。","why":"The word came to mean a published list of charges, and the charge for imports became its central sense.","whyCN":"这个词本指一份公布的收费表，而对进口的收费成了它最核心的义项。"},{"no":"02","title":"The published schedule of rates","titleCN":"公布的税率表","definition":"the official table that lists each kind of goods and the rate charged on it","definitionCN":"列出各类货物及所征税率的官方表格","example":"The customs office keeps the tariff in a thick bound volume.","exampleCN":"海关把税则保存在一本厚厚的大册里。","why":"A tax needs a table before it can be collected, and the table shares the name.","whyCN":"税在征收之前需要一张表，这张表便与税共用同一个名字。"},{"no":"03","title":"A protective tariff","titleCN":"保护性关税","definition":"a duty set high enough to shield domestic producers from foreign competition","definitionCN":"高到足以让本国生产者免受外国竞争冲击的关税","example":"The protective tariff kept the local mills open for a decade.","exampleCN":"保护性关税让本地磨坊多开了十年。","why":"A toll can be set not to raise money but to keep traffic out.","whyCN":"一道收费门可以不为收钱，而为把车流挡在外面。"},{"no":"04","title":"A retaliatory tariff","titleCN":"报复性关税","definition":"a duty imposed in answer to another country's duty","definitionCN":"为回应另一国的关税而施加的关税","example":"The retaliatory tariff hit fruit from the neighbouring market.","exampleCN":"报复性关税打击了邻国市场的水果。","why":"When a toll is charged against you, the answer is another toll.","whyCN":"当别人对你收过路费，回答就是再收一道。"},{"no":"05","title":"The rate itself, whether by value or by unit","titleCN":"税率本身，按价值或按数量计","definition":"the percentage of value or the fixed sum per unit that the duty amounts to","definitionCN":"关税所折算成的价值百分比或每单位固定金额","example":"The tariff rate is charged on the value stated on the invoice.","exampleCN":"税率按发票上申报的价值征收。","why":"Behind the table sits a number, and that number is what officials actually apply.","whyCN":"表格背后是一个数字，官员实际适用的正是那个数字。"},{"no":"06","title":"A utility's schedule of charges","titleCN":"公用事业的收费表","definition":"the published list of rates for electricity, gas, water or telephone service","definitionCN":"电力、燃气、水或电话服务公布的费率表","example":"The night tariff makes off-peak power cheaper.","exampleCN":"夜间电价表让非高峰用电更便宜。","why":"The same word for a published rate table serves any service that bills by a schedule.","whyCN":"同一个表示公布费率表的词，适用于任何按表计费的服务。"},{"no":"07","title":"A tariff war between countries","titleCN":"国家之间的关税战","definition":"a cycle in which each side raises duties in response to the other","definitionCN":"双方互相提高关税以回应对方的循环","example":"The tariff war raised prices on both sides of the border.","exampleCN":"关税战抬高了两国边境两侧的价格。","why":"Repeated retaliation turns a single duty into a sustained conflict.","whyCN":"反复报复把单项关税变成持续冲突。"},{"no":"08","title":"A general price list or fee schedule","titleCN":"一般的价目表或收费表","definition":"any table of charges, as for a hotel, a taxi service or a repair shop","definitionCN":"任何收费表，如旅馆、出租车或修理店的价目表","example":"The hotel keeps its tariff on a card behind the door.","exampleCN":"旅馆把价目表放在门后的卡片上。","why":"This is the oldest surviving sense: a list of prices printed to be read.","whyCN":"这是留存下来的最早义项：一份印出来供人查看的价格清单。"}],"etymology":{"intro":{"en":"Tariff came into English through Italian and French from Arabic tarif, a notification or an assessment, from the verb meaning to know. The sense of a duty grew out of the published list of charges.","cn":"tariff 经意大利语与法语进入英语，来自阿拉伯语中表示「通告、估定」的词，其动词意为「知道」。关税义由公布的收费表发展而来。"},"items":[{"era":"ARABIC ARAFA","en":"The verb meant to know or to inform, and from it came the noun for a notification or an assessment.","cn":"这个动词意为「知道、告知」，由其产生表示「通告、估定」的名词。"},{"era":"ARABIC TARIF","en":"Tarif named a statement of charges or a list of prices, the sense that travelled into Europe.","cn":"tarif 指一份收费说明或价格清单，这一义项传入欧洲。"},{"era":"ITALIAN TARIFFA","en":"Italian tariffa kept the sense of a schedule of charges, used in ports and customs houses.","cn":"意大利语 tariffa 保留「收费表」之义，用于港口与海关。"},{"era":"FRENCH TARIF","en":"French tarif carried the word onward, and English borrowed it in the sixteenth century.","cn":"法语 tarif 继续传递这个词，英语在十六世纪借入。"},{"era":"ENGLISH TARIFF","en":"In English the word first meant a table of rates, then the duty charged according to that table.","cn":"在英语中，这个词先指费率表，后指按该表征收的税。"},{"era":"UTILITY SCHEDULES","en":"In the nineteenth and twentieth centuries gas, water and telephone companies published their own tariffs, keeping the older list sense alive.","cn":"十九与二十世纪，燃气、水与电话公司各自公布价目表，使较旧的「清单」义得以延续。"}]},"similar":{"note":{"en":"The first group holds the word and two look-alikes, one of them unrelated in origin; the second holds other charges and the words closest in meaning.","cn":"第一组是这个单词与两个形近词，其中一个来源无关；第二组是其他收费与最接近的同义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tariffed","ipa":"/ˈtærɪft/","tag":"the adjective","definition":"Subjected to a tariff; it describes goods or trade rather than the tax itself.","definitionCN":"被征收关税的；它描述货物或贸易，而非税本身。"},{"word":"tariffing","ipa":"/ˈtærɪfɪŋ/","tag":"the act","definition":"The act of setting rates or charging according to a schedule, used in regulation and utilities.","definitionCN":"制定费率或按价目表收费的行为，用于监管与公用事业。"},{"word":"traffic","ipa":"/ˈtræfɪk/","tag":"different origin","definition":"The movement of vehicles or goods, from Italian traffico; it looks close to tariff but comes from another word entirely.","definitionCN":"车辆或货物的流动，来自意大利语 traffico；它与 tariff 拼写相近，来源却完全不同。"},{"word":"tariffless","ipa":"/ˈtærɪfləs/","tag":"without duties","definition":"Free of tariffs; it is a derived adjective, not the tax.","definitionCN":"无关税的；它是派生形容词，不是税本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"duty","ipa":"/ˈdjuːti/","tag":"the tax itself","definition":"A tax on imports or exports; it is close to tariff but can also mean an obligation.","definitionCN":"对进出口征收的税；与 tariff 接近，但也指义务。"},{"word":"levy","ipa":"/ˈlevi/","tag":"the collecting","definition":"A charge imposed by authority, or the act of imposing it; broader than a border tax.","definitionCN":"当局征收的费用，或征收这一行为；比边境税更宽。"},{"word":"toll","ipa":"/təʊl/","tag":"a charge for passage","definition":"A charge for using a road or a bridge; historically the same idea as a tariff but for traffic.","definitionCN":"使用道路或桥梁所付的费用；历史上与关税同一思路，只是针对通行。"},{"word":"rate","ipa":"/reɪt/","tag":"the figure in the table","definition":"The amount charged per unit; a tariff is a table of such rates.","definitionCN":"每单位收取的金额；关税就是这类费率构成的表。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词，而非编造的顺口溜。"},"normal":[{"en":"The word first meant a published list of charges, and a duty is one line in that list.","cn":"这个词最初指公布的收费表，而关税就是表上的一行。"},{"en":"The family runs tariff, tariffed, tariffing and tariffless.","cn":"同族词包括 tariff、tariffed、tariffing 与 tariffless。"},{"en":"Fixed phrases mark the border and the utility: import tariff, tariff rate, night tariff.","cn":"固定搭配标出边境与公用事业两面：进口关税、税率、夜间电价。"},{"en":"Keep tariff and traffic apart: one is a table of charges, the other is movement.","cn":"把关税与交通分开：一个是收费表，一个是流动。"},{"en":"A customs officer with a pen on a long table is the picture of the whole word.","cn":"一名关员拿着笔在长表上划线，就是这个词的整体画面。"}],"abstract":[{"en":"Picture a menu of charges posted at a border, where each dish is a kind of goods.","cn":"想象边境上贴着一份收费菜单，每道菜就是一种货物。"},{"en":"Picture two countries each raising a wall one brick higher than the other's.","cn":"想象两个国家各自把墙砌得比对方高一块砖。"},{"en":"Picture a household meter read at night, with a cheaper column waiting for dark.","cn":"想象一只家用表在夜里被抄读，表上有一栏更便宜的费率等着天黑。"}]},"examples":[{"en":"The tariff applies to the stated value of each shipment.","cn":"关税按每批货运申报的价值征收。"},{"en":"Farmers asked for a protective tariff on imported grain.","cn":"农民要求对进口谷物征收保护性关税。"},{"en":"The utility publishes a separate tariff for night use.","cn":"这家公用事业单位另行公布夜间使用的价目表。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「抬（ta）里（rif）夫」——边境照着费率表抬价收钱 → 关税、税率表","word":"tariff"},"root":"来自阿拉伯语 tarif「通告、估定的收费」，经意大利语 tariffa 与法语 tarif 进入英语；本义是公布的收费表，后指按表征收的关税。","sensesIntro":{"en":"Eight senses follow one published table: a duty on imports, the table itself, a protective duty, a retaliatory duty, the rate applied, a utility schedule, a war of duties, and any printed price list.","cn":"八个义项沿同一张公布的表格展开：进口关税、表格本身、保护性关税、报复性关税、实际适用的税率、公用事业价目表、关税战，以及任何印出的价目表。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long rate table pinned at a customs window, with a pen tracing one line.","cn":"核心意象：海关窗口上钉着一张长费率表，一支笔正划过其中一行。"},"chain":["A LIST IS PUBLISHED","A LINE IS A DUTY","THE DUTY PROTECTS","THE DUTY ANSWERS","A RATE IS APPLIED","A SERVICE BILLS BY IT"],"branches":[{"senses":"01 · 02","en":"THE LINE AND THE LIST: a single duty and the whole table are the same page at two scales.","cn":"一行与整表：单项关税与整张表是同一页纸的两个尺度。"},{"senses":"03","en":"A WALL OF PRICE: a protective duty is set to keep goods out rather than to raise money.","cn":"价格的墙：保护性关税是要把货物挡在外面，而不是为了收钱。"},{"senses":"04 · 07","en":"ANSWER AND ESCALATION: one retaliatory duty repeated becomes a tariff war.","cn":"回应与升级：一项报复性关税反复出现，就成了关税战。"},{"senses":"05","en":"THE NUMBER UNDER THE LINE: the rate is what an officer actually applies.","cn":"行下的数字：税率才是关员实际执行的东西。"},{"senses":"06 · 08","en":"BILLS AND MENUS: a utility schedule and a printed price list keep the oldest sense alive.","cn":"账单与菜单：公用事业价目表与印出的价格清单保留了最古老的义项。"}]},"affixes":{"intro":{"en":"The word is a single Arabic loan that passed through Italian and French; it has no Latin root, so its parts are best read as the borrowed stem plus English endings.","cn":"这个词是一个经意大利语与法语传来的阿拉伯语借词，没有拉丁词根，因此各部分宜读作「借入的词干」加英语词尾。"},"latinIntro":{"en":"No Latin root is involved; the source is Arabic, so the Latin entries stay empty.","cn":"这里不涉及拉丁词根；来源是阿拉伯语，因此拉丁语词形一栏留空。"},"items":[{"word":"tarif","structure":"Arabic tarif (a notification, an assessment)","meaning":"a published statement of charges","meaningCN":"公布的收费说明","example":"The list of charges travelled from port to port.","exampleCN":"这份收费清单从一个港口传到另一个港口。"},{"word":"tariffa","structure":"Italian tariffa (a schedule of charges)","meaning":"a table of rates","meaningCN":"费率表","example":"The harbour kept a tariffa for every cargo.","exampleCN":"港口为每种货物备有一份费率表。"},{"word":"tariff","structure":"French tarif, from Italian tariffa","meaning":"a duty; a table of rates","meaningCN":"关税；费率表","example":"The tariff lists every kind of goods.","exampleCN":"税则列出每一种货物。"},{"word":"tariffed","structure":"tariff + -ed (provided with)","meaning":"subject to a duty","meaningCN":"被征收关税的","example":"Tariffed goods clear more slowly.","exampleCN":"被征关税的货物清关更慢。"},{"word":"tariffing","structure":"tariff + -ing (the act)","meaning":"setting or applying rates","meaningCN":"制定或适用费率","example":"Tariffing the network took a full year.","exampleCN":"为网络制定费率花了整整一年。"},{"word":"tariffless","structure":"tariff + -less (without)","meaning":"free of duties","meaningCN":"无关税的","example":"The two neighbours trade tariffless goods.","exampleCN":"这两个邻国互相交易无关税的货物。"},{"word":"duty","structure":"Anglo-French duete (due, owed)","meaning":"a tax owed","meaningCN":"应缴的税","example":"Duty is paid at the border.","exampleCN":"税在边境缴纳。"},{"word":"customs","structure":"Old French costume, from Latin consuetudo (habit)","meaning":"the office that collects border duties","meaningCN":"海关","example":"Customs checks every declared value.","exampleCN":"海关核查每一笔申报价值。"},{"word":"rate","structure":"Medieval Latin rata (a fixed share)","meaning":"a fixed charge per unit","meaningCN":"费率；单价","example":"Each line of the table is a rate.","exampleCN":"表上的每一行都是一个费率。"}],"latinEntries":[]}}]);
